class OfficerWakeRequest(BaseModel):
    minutes: int
    reason: str = ""


class OfficerNotifyRequest(BaseModel):
    message: str
    urgency: str = "log"  # log | digest | page
    subject: str = ""


_CONFERENCE_BRAIN_KEYS = ("model", "reasoning_level")


def _inherit_conference_brain(
    config_override: dict, officer: Optional[dict]
) -> list[str]:
    """Fill the conference's ``llm`` gaps from the standing officer's brain.

    A conference is his embodiment, so it thinks with his model and effort
    unless the request says otherwise (officer_visibility_streamline.md §3.1,
    closing conference live-fire F2 — every conference used to boot on the
    platform default). Request-provided keys win; only absent ones are
    filled. Returns the keys inherited, for the log line. Never raises: a
    vacant post or a brainless officer means today's behavior.
    """
    if not officer:
        return []
    metadata = officer.get("metadata") or {}
    if isinstance(metadata, str):
        try:
            metadata = json.loads(metadata)
        except (json.JSONDecodeError, TypeError):
            metadata = {}
    brain = (metadata.get("config_override") or {}).get("llm") or {}
    if not isinstance(brain, dict):
        return []
    inherited: list[str] = []
    for key in _CONFERENCE_BRAIN_KEYS:
        value = brain.get(key)
        if not isinstance(value, str) or not value.strip():
            continue
        llm = config_override.setdefault("llm", {})
        if llm.get(key):
            continue
        llm[key] = value
        inherited.append(key)
    return inherited


def _thread_is_conference(thread: dict) -> bool:
    """True for a conference embodiment (centurion.md §2/S9) — a normal
    interactive session wearing the officer's identity via
    ``officer.conference``; ``officer.enabled`` stays false on it."""
    return _thread_officer_meta(thread).get("conference") in (True, "true")


async def _find_open_conference_thread(project_id: str) -> Optional[dict]:
    """The project's open (non-ended) conference thread, if any.

    One open conference per project is the single-writer rule (§2): the
    create path reattaches to this instead of minting a rival embodiment.

    An authorized retirement is irrevocable — the thread admits no further
    input — so it no longer counts, whatever its status column still says.
    Otherwise a retirement that cannot settle (a stuck runtime) would lock
    the project out of conferences for as long as it stays stuck.
    """
    async with postgres_db.acquire() as conn:
        row = await conn.fetchrow(
            """
            SELECT id, status, title, created_at FROM threads
             WHERE project_id = $1
               AND status <> 'ended'
               AND runtime_retirement_authorized_at IS NULL
               AND COALESCE(metadata->'config_override'
                            ->'officer'->>'conference','false') = 'true'
             ORDER BY created_at DESC
             LIMIT 1
            """,
            project_id,
        )
    return dict(row) if row else None


async def _hold_officer_for_conference(
    project_id: str, conference_thread_id: str
) -> None:
    """Stamp the background officer's conference hold (centurion.md §4).

    With the external timer the hold is uniform: the wake-claim query skips
    held threads entirely (events AND timer rows stay pending) and the
    watchdog stands down. A live stand-by notice is injected best-effort so
    a mid-turn officer parks politely instead of racing the meeting. No-op
    without an enabled officer — a conference on an officer-less project is
    just a session with the persona.
    """
    try:
        officer = await postgres_db.get_officer_thread_for_project(project_id)
        if not officer or str(officer["id"]) == str(conference_thread_id):
            return
        officer_tid = str(officer["id"])
        hold_result = await postgres_db.set_project_officer_hold(
            project_id,
            expected_thread_id=officer_tid,
            hold={
                "kind": "conference",
                "thread_id": str(conference_thread_id),
                "since": datetime.now(timezone.utc).isoformat(),
            },
            route_reason="officer_hold",
        )
        logger.info(
            "officer %s: conference hold stamped (conference %s)",
            officer_tid[:8],
            str(conference_thread_id)[:8],
        )
        await _deliver_staged_officer_routes(
            hold_result.get("routes") or [], reason="officer_hold"
        )
        from orchestrator.services import session_wake as _sw

        officer_thread = await postgres_db.get_thread(officer_tid)
        if officer_thread is not None:
            agent = await _sw._resolve_live_agent(postgres_db, officer_thread)
            if agent is not None:
                await _sw._inject_live(
                    agent,
                    "[conference started — the Legate is meeting with your "
                    "conference embodiment. Standing hold: take no scheduling "
                    "actions; your timers and events queue durably and arrive "
                    "with the session brief. If your backstop fires before "
                    "the brief: sleep.]",
                    delivery_id=str(uuid4()),
                    db=postgres_db,
                )
    except Exception:
        logger.exception("conference hold: stamping failed (non-fatal)")


async def _conclude_conference_if_any(thread: dict) -> None:
    """On a conference thread leaving service: release the officer's hold and
    enqueue the ``conference`` brief wake (centurion.md §4).

    The wake coalesces with everything that queued during the meeting —
    insert-dedup on the conference thread id makes end-hook and watchdog
    self-heal idempotent. The brief is a pointer, not a transcript: direction
    agreed in conference lands in the project stores (charter posture, KB,
    backlog), which the officer re-reads anyway. Never raises.
    """
    try:
        if not _thread_is_conference(thread):
            return
        project_id = thread.get("project_id")
        if not project_id:
            return
        conf_tid = str(thread["id"])
        officer = await postgres_db.get_officer_thread_for_project(str(project_id))
        if not officer:
            return
        officer_tid = str(officer["id"])
        hold = _thread_officer_meta(officer).get("hold") or {}
        if isinstance(hold, dict) and hold.get("thread_id") in (None, conf_tid):
            await postgres_db.set_project_officer_hold(
                str(project_id),
                expected_thread_id=officer_tid,
                hold=None,
            )
        await postgres_db.enqueue_session_wake_event(
            officer_tid,
            source="conference",
            dedup_key=conf_tid,
            payload={
                "conference_thread_id": conf_tid,
                "title": str(thread.get("title") or ""),
                "summary": (
                    "conference concluded — direction agreed there is now in "
                    "force. Re-read the charter posture and any KB/backlog "
                    "notes updated during the meeting before your next "
                    "scheduling decision."
                ),
            },
            project_id=str(project_id),
        )
        _kick_officer_event_drain(postgres_db)
        logger.info(
            "conference %s concluded — officer %s hold released, brief wake enqueued",
            conf_tid[:8],
            officer_tid[:8],
        )
    except Exception:
        logger.exception("conference end: brief wake failed (non-fatal)")


def _roster_officer_view(row: dict[str, Any]) -> dict[str, Any]:
    """One roster line from a ``project_officers`` join row."""
    from orchestrator.services.officer_backlog import auto_pull_enabled

    raw_metadata = row.get("metadata")
    metadata = raw_metadata or {}
    metadata_shape_valid = isinstance(metadata, dict)
    if isinstance(metadata, str):
        try:
            metadata = json.loads(metadata)
            metadata_shape_valid = isinstance(metadata, dict)
        except (json.JSONDecodeError, TypeError):
            metadata = {}
            metadata_shape_valid = False
    if not metadata_shape_valid:
        metadata = {}
    config_override = metadata.get("config_override") or {}
    config_override_shape_valid = isinstance(config_override, dict)
    if not config_override_shape_valid:
        config_override = {}
    officer_cfg = config_override.get("officer") or {}
    officer_cfg_shape_valid = isinstance(officer_cfg, dict)
    if not officer_cfg_shape_valid:
        officer_cfg = {}
    raw_post_config_override = row.get("post_config_override")
    post_config_override = raw_post_config_override
    post_config_shape_valid = isinstance(post_config_override, dict)
    if isinstance(post_config_override, str):
        try:
            post_config_override = json.loads(post_config_override)
            post_config_shape_valid = isinstance(post_config_override, dict)
        except (json.JSONDecodeError, TypeError):
            post_config_override = {}
            post_config_shape_valid = False
    if not post_config_shape_valid:
        post_config_override = {}
    officer_missing = object()
    durable_officer_cfg = post_config_override.get("officer", officer_missing)
    durable_officer_shape_valid = durable_officer_cfg is officer_missing or isinstance(
        durable_officer_cfg, dict
    )
    if durable_officer_cfg is officer_missing:
        durable_officer_cfg = {}
    if not durable_officer_shape_valid:
        durable_officer_cfg = {}
    llm_cfg = config_override.get("llm") or {}
    if not isinstance(llm_cfg, dict):
        llm_cfg = {}
    thread_id = row.get("thread_id")
    thread_status = row.get("thread_status")
    linked = bool(thread_id)
    commissioned = linked and thread_status not in (None, "ended")

    def _strict_auto_pull(config: dict[str, Any]) -> tuple[bool | None, bool]:
        if "auto_pull" not in config:
            return False, True
        value = config.get("auto_pull")
        if type(value) is bool:
            return value, True
        # A legacy string/number is not evidence that a downgrade is safe.
        # Do not let Python's ``1.0 == True`` equality collapse it into an
        # apparently valid boolean.
        return None, False

    durable_auto_pull, durable_auto_pull_scalar_valid = _strict_auto_pull(
        durable_officer_cfg
    )
    durable_auto_pull_valid = (
        post_config_shape_valid
        and durable_officer_shape_valid
        and durable_auto_pull_scalar_valid
    )
    if linked:
        runtime_auto_pull, runtime_auto_pull_scalar_valid = _strict_auto_pull(
            officer_cfg
        )
        runtime_auto_pull_valid = (
            commissioned
            and str(row.get("thread_project_id") or "")
            == str(row.get("project_id") or "")
            and metadata_shape_valid
            and config_override_shape_valid
            and officer_cfg_shape_valid
            and officer_cfg.get("enabled") is True
            and runtime_auto_pull_scalar_valid
        )
    else:
        runtime_auto_pull, runtime_auto_pull_valid = None, True
    mirror_consistent = (
        durable_auto_pull_valid
        and runtime_auto_pull_valid
        and (runtime_auto_pull is None or runtime_auto_pull == durable_auto_pull)
    )
    return {
        "project_id": str(row.get("project_id")),
        "project_name": row.get("project_name"),
        "thread_id": str(thread_id) if thread_id else None,
        "thread_status": thread_status,
        "commissioned": commissioned,
        "held": officer_cfg.get("hold") or None,
        "next_wake_at": _iso_or_none(row.get("next_wake_at")),
        "pending_events": int(row.get("pending_events") or 0),
        "in_flight_jobs": int(row.get("in_flight_jobs") or 0),
        "auto_pull": (
            auto_pull_enabled(officer_cfg)
            if linked
            else auto_pull_enabled(durable_officer_cfg)
        ),
        # Safe, credential-free rollout evidence. A system administrator's
        # all-project roster is the supported downgrade preflight: pre-BP-01
        # binaries must not return until every durable value and every current
        # runtime mirror is false and mutually consistent.
        "auto_pull_durable": durable_auto_pull,
        "auto_pull_durable_valid": durable_auto_pull_valid,
        "auto_pull_runtime": runtime_auto_pull,
        "auto_pull_runtime_valid": runtime_auto_pull_valid,
        "auto_pull_mirror_consistent": mirror_consistent,
        "auto_pull_enable_available": OFFICER_AUTO_PULL_RELEASE_ENABLED,
        "model": llm_cfg.get("model"),
        "last_activity_at": _iso_or_none(row.get("last_agent_activity")),
    }


def _iso_or_none(value: Any) -> str | None:
    if isinstance(value, datetime):
        return value.isoformat()
    return str(value) if value else None


@app.get("/api/officers")
async def list_officers(request: Request) -> dict[str, Any]:
    """Every post the caller can see, vacant ones included — the roster.

    Discovery for a Legate (or an assistant holding his credentials) who has
    more projects than officers: one call answers which projects have an
    officer, whether he is awake, held or vacant, and whether anything is
    waiting on him. Per-slot kit utilization stays on the per-project card,
    which computes it lineage-aware; this read stays cheap.
    """
    user = await require_approved_user(request, postgres_db)
    visible = await user_visible_project_ids(user, postgres_db)
    if visible != "all" and not visible:
        return {
            "officers": [],
            "total": 0,
            "auto_pull_downgrade": {
                "scope": "visible_projects",
                "safe": False,
                "release_fence_closed": not OFFICER_AUTO_PULL_RELEASE_ENABLED,
                "durable_enabled": 0,
                "runtime_enabled": 0,
                "invalid_values": 0,
                "mirror_mismatches": 0,
                "reason": "all_projects_admin_scope_required",
            },
        }
    rows = await postgres_db.list_project_officer_posts(
        None if visible == "all" else sorted(str(pid) for pid in visible)
    )
    officers = [_roster_officer_view(row) for row in rows]
    all_projects = visible == "all"
    durable_enabled = sum(bool(row["auto_pull_durable"]) for row in officers)
    runtime_enabled = sum(row["auto_pull_runtime"] is True for row in officers)
    invalid_values = sum(
        not row["auto_pull_durable_valid"] or not row["auto_pull_runtime_valid"]
        for row in officers
    )
    mirror_mismatches = sum(not row["auto_pull_mirror_consistent"] for row in officers)
    downgrade_safe = (
        all_projects
        and not OFFICER_AUTO_PULL_RELEASE_ENABLED
        and durable_enabled == 0
        and runtime_enabled == 0
        and invalid_values == 0
        and mirror_mismatches == 0
    )
    return {
        "officers": officers,
        "total": len(officers),
        "auto_pull_downgrade": {
            "scope": "all_projects" if all_projects else "visible_projects",
            "safe": downgrade_safe,
            "release_fence_closed": not OFFICER_AUTO_PULL_RELEASE_ENABLED,
            "durable_enabled": durable_enabled,
            "runtime_enabled": runtime_enabled,
            "invalid_values": invalid_values,
            "mirror_mismatches": mirror_mismatches,
            "reason": (
                None
                if downgrade_safe
                else (
                    "all_projects_admin_scope_required"
                    if not all_projects
                    else (
                        "release_fence_open"
                        if OFFICER_AUTO_PULL_RELEASE_ENABLED
                        else "auto_pull_not_fully_disabled"
                    )
                )
            ),
        },
    }


async def _can_manage_project_officer(user: dict[str, Any], project_id: str) -> bool:
    """Server-owned owner/admin capability for Officer mutations."""
    if user.get("is_admin"):
        return True
    return (
        await postgres_db.get_user_role_in_project(project_id, str(user["id"]))
        == "owner"
    )


@app.get("/api/projects/{project_id}/officer")
async def get_project_officer_summary(
    request: Request, project_id: str
) -> dict[str, Any]:
    """The project's post at a glance — the cockpit's officer card.

    officer_post.md §4/§8: always returns the post. ``commissioned`` /
    ``held`` / ``kit`` / ``incarnations`` / ``communication_policy`` /
    ``while_vacant`` come from the durable ``project_officers`` row; the
    ``officer`` block is ALWAYS present so the card's editor seeds from one
    place — live thread metadata when commissioned, the row's config when
    vacant (live-only fields null there). Kit utilization is lineage-aware:
    in-flight counts follow every incarnation on the post, not just the
    current thread.
    """
    user, _project = await require_project_member(
        request, postgres_db, project_id, min_role="viewer"
    )
    can_manage = await _can_manage_project_officer(user, project_id)

    post = await postgres_db.get_or_create_project_officer(project_id) or {}
    officer = await postgres_db.get_officer_thread_for_project(project_id)
    conference = await _find_open_conference_thread(project_id)
    conference_block = (
        {
            "thread_id": str(conference["id"]),
            "status": conference.get("status"),
        }
        if conference
        else None
    )

    # Lineage-aware utilization (officer_post.md §4): jobs dispatched by any
    # incarnation keep occupying their slots across decommission→recommission.
    lineage = await postgres_db.get_project_officer_lineage(project_id)
    in_flight_by_slot: dict[Any, int] = {}
    if lineage:
        # Through the shared admission helper, not a local copy of its query.
        # This is the third place that count lived; when admission widened to
        # all-non-terminal, a stale copy here would show the Legate a free slot
        # the funnel then refuses with a 409.
        from orchestrator.services.officer_admission import count_in_flight_by_slot

        async with postgres_db.acquire() as conn:
            in_flight_by_slot = await count_in_flight_by_slot(conn, lineage)

    # Ready depth per pool — the number the officer's queue duty is measured
    # against (officer_backlog_pools.md §6). Computed through the tick's own
    # eligibility path so the card cannot promise dispatches the tick will not
    # make; a KB outage leaves it absent rather than showing a false zero.
    ready_by_pool: dict[str, int] = {}

    def _kit_view(slots: Any) -> dict[str, Any] | None:
        """Roster spec + per-slot in-flight + pool depth, or None on a flat cap."""
        if not isinstance(slots, dict) or not slots:
            return None
        kit: dict[str, Any] = {}
        for name, spec in slots.items():
            entry = dict(spec) if isinstance(spec, dict) else {}
            entry["in_flight"] = int(in_flight_by_slot.get(name) or 0)
            if entry.get("category") and str(name) in ready_by_pool:
                depth = ready_by_pool[str(name)]
                entry["ready_depth"] = depth
                # The floor IS the slot count (§13.2). Rendered, not just
                # enforced: a policy the officer cannot see invites drift.
                entry["below_floor"] = depth < int(entry.get("count") or 0)
            kit[str(name)] = entry
        return kit

    row_officer_cfg = (post.get("config_override") or {}).get("officer") or {}
    if not isinstance(row_officer_cfg, dict):
        row_officer_cfg = {}
    row_llm_cfg = (post.get("config_override") or {}).get("llm") or {}
    if not isinstance(row_llm_cfg, dict):
        row_llm_cfg = {}
    provisioning_preflights = await postgres_db.list_officer_job_preflights(
        project_id=project_id
    )
    knowledge_materialization = await postgres_db.list_knowledge_materialization_health(
        project_id
    )
    floor_wakes = await postgres_db.list_officer_floor_wake_outcomes(project_id)
    from orchestrator.services.job_liveness import get_liveness_policy
    from orchestrator.services.officer_backlog import auto_pull_enabled, pools_from_meta
    from orchestrator.services.officer_backlog import (
        ready_depth_by_pool as _ready_depth,
    )

    stale_claim_policy = get_liveness_policy().stale_claim.as_dict()
    post_block: dict[str, Any] = {
        # OC-10: a safe capability derived from the same current membership
        # authority as the mutation endpoints.  It is refreshed with every
        # summary poll; the owner/admin endpoint guards remain authoritative.
        "can_manage": can_manage,
        # OC-03 read surface: commissioned means a LIVE thread holds the post,
        # not that the link column is non-null. ``officer`` comes from the
        # post join with the non-ended filter, so it IS the live-post proof; a
        # stale link (a retire that predates the O3 decommission flow, or a
        # thread ended around the endpoint) must read as vacant — the old
        # bool(thread_id) form returned commissioned:true with an empty
        # officer block, and the card wedged on a state it cannot render.
        "commissioned": officer is not None,
        "held": None,
        "kit": None,
        "communication_policy": post.get("communication_policy") or {},
        "incarnations": post.get("incarnations") or [],
        "while_vacant": _while_vacant_view(post.get("state")),
        "runtime_authorization": _officer_runtime_authorization_view(
            post.get("state"), commissioned=officer is not None
        ),
        "runtime_lifecycle": {
            "observed_build_sha": None,
            "expected_build_sha": persistent_provisioner.expected_build_sha,
            "drift_state": "unknown",
            "recycle_phase": "idle",
            "last_failure": None,
            "automatic_reconciliation_enabled": (
                PERSISTENT_AGENT_RECONCILIATION_ENABLED
            ),
        },
        # Always present so the card never has to branch on shape. A vacant
        # post has no live counters — only the setting the next incarnation
        # will boot with.
        "backlog": {
            "auto_pull": auto_pull_enabled(row_officer_cfg),
            "auto_pull_control": {
                "enable_available": OFFICER_AUTO_PULL_RELEASE_ENABLED,
                "source": "deployment_policy",
                "reason": (
                    None if OFFICER_AUTO_PULL_RELEASE_ENABLED else "release_gate_closed"
                ),
            },
            "breakers": {},
            "stale_claims": [],
            "stale_claim_policy": stale_claim_policy,
            "worker_spend_ceiling_daily": row_officer_cfg.get(
                "worker_spend_ceiling_daily"
            ),
            "provisioning_preflights": provisioning_preflights,
            "knowledge_materialization": knowledge_materialization,
            "floor_wakes": floor_wakes,
        },
    }

    if not officer:
        # Vacant — including a stale ended-thread link, which now reads as
        # vacant on the ``commissioned`` flag too (OC-03). The editor seeds
        # from the row — the last real kit a decommission or the backfill
        # harvested there. The officer block is present but live-only fields
        # (thread_id, status, hold) are null.
        post_block["kit"] = _kit_view(row_officer_cfg.get("slots"))
        try:
            row_ceiling = int(row_officer_cfg.get("daily_token_ceiling") or 0)
        except (TypeError, ValueError):
            row_ceiling = 0
        return {
            "officer": {
                "thread_id": None,
                "status": None,
                "title": None,
                "created_at": None,
                "hold": None,
                **_officer_editor_block(row_officer_cfg, row_llm_cfg),
            },
            "conference": conference_block,
            "spend_today": await _officer_spend_today(None, row_ceiling),
            **post_block,
        }

    officer_tid = str(officer["id"])
    officer_meta = _thread_officer_meta(officer)
    metadata = officer.get("metadata") or {}
    if isinstance(metadata, str):
        try:
            metadata = json.loads(metadata)
        except (json.JSONDecodeError, TypeError):
            metadata = {}
    officer_state = metadata.get("officer_state") or {}
    if not isinstance(officer_state, dict):
        officer_state = {}
    lifecycle_view = persistent_recycle_view(metadata)
    lifecycle_view["expected_build_sha"] = persistent_provisioner.expected_build_sha
    lifecycle_view["automatic_reconciliation_enabled"] = (
        PERSISTENT_AGENT_RECONCILIATION_ENABLED
    )
    if persistent_provisioner.is_available:
        pod_status = await persistent_provisioner.get_pod_status(officer_tid)
        if pod_status:
            lifecycle_view["observed_build_sha"] = pod_status.get("build_sha")
            lifecycle_view["drift_state"] = (
                "current"
                if not persistent_provisioner.expected_build_sha
                or pod_status.get("build_sha")
                == persistent_provisioner.expected_build_sha
                else "drifted"
            )
        elif lifecycle_view.get("recycle_phase") != "idle":
            lifecycle_view["drift_state"] = "missing"
    post_block["runtime_lifecycle"] = lifecycle_view

    timer = await postgres_db.get_pending_officer_timer(officer_tid)
    async with postgres_db.acquire() as conn:
        pending_events = await conn.fetchval(
            "SELECT COUNT(*) FROM session_wake_events "
            "WHERE thread_id = $1 AND state = 'pending'",
            UUID(officer_tid),
        )

    today = datetime.now(timezone.utc).date().isoformat()
    try:
        token_ceiling = int(officer_meta.get("daily_token_ceiling") or 0)
    except (TypeError, ValueError):
        token_ceiling = 0

    # Hold is thread-scoped runtime state (officer_post.md §5) — read live.
    raw_hold = officer_meta.get("hold")
    public_hold = (
        {k: v for k, v in raw_hold.items() if not str(k).startswith("_")}
        if isinstance(raw_hold, dict)
        else raw_hold
    )
    post_block["held"] = public_hold or None

    _pools = pools_from_meta(officer_meta)
    if _pools and vector_db is not None:
        ready_by_pool = await _ready_depth(
            postgres_db,
            vector_db,
            project_id,
            _pools,
            caller="officer_summary",
        )

    post_block["kit"] = _kit_view(
        officer_meta.get("slots") or row_officer_cfg.get("slots")
    )
    # The backlog policies the tick enforces on his behalf. Breakers and stale
    # claims are already computed and stored by the tick — this only surfaces
    # them, so the card cannot disagree with what actually happened.
    post_block["backlog"] = {
        "auto_pull": auto_pull_enabled(officer_meta),
        "auto_pull_control": {
            "enable_available": OFFICER_AUTO_PULL_RELEASE_ENABLED,
            "source": "deployment_policy",
            "reason": (
                None if OFFICER_AUTO_PULL_RELEASE_ENABLED else "release_gate_closed"
            ),
        },
        "breakers": {
            pool: entry
            for pool, entry in (officer_state.get("backlog_breakers") or {}).items()
            if isinstance(entry, dict)
        },
        "stale_claims": officer_state.get("backlog_stale_claims") or [],
        "stale_claim_policy": officer_state.get("backlog_stale_claim_policy")
        or stale_claim_policy,
        "worker_spend_ceiling_daily": officer_meta.get("worker_spend_ceiling_daily"),
        "provisioning_preflights": provisioning_preflights,
        "knowledge_materialization": knowledge_materialization,
        "floor_wakes": floor_wakes,
    }

    return {
        **post_block,
        "officer": {
            "thread_id": officer_tid,
            "status": officer.get("status"),
            "title": officer.get("title"),
            "created_at": officer.get("created_at"),
            "hold": public_hold or None,
            # The brain HIS judgment runs on (explicit override only — a null
            # means he's on the resolved session default, which the card
            # renders as exactly that) + the full editor numerics, live from
            # the thread's runtime projection.
            **_officer_editor_block(
                officer_meta,
                (metadata.get("config_override") or {}).get("llm") or {},
            ),
        },
        "next_wake_at": (timer or {}).get("fire_at"),
        "pending_events": int(pending_events or 0),
        "token_ceiling": {
            "daily": token_ceiling,
            "deferred_today": officer_state.get("ceiling_notice") == today,
        },
        "spend_today": await _officer_spend_today(officer_tid, token_ceiling),
        # The officer's pages and digests are feed rows now — the card reads
        # GET /api/notifications?source_kind=thread&source_id=<officer_tid>.
        "conference": conference_block,
    }


async def _officer_spend_today(thread_id: str | None, ceiling: int) -> dict[str, Any]:
    """Today's session-token spend against the officer's daily ceiling (§8).

    The exact call the ceiling brake makes per wake
    (``session_wake._officer_ceiling_deferral``), reused for the card:
    ``usage_ledger.query_usage`` over today's UTC window, ``ref_id`` =
    officer thread, tokens-unit categories summed. ``tokens`` is 0 for a
    vacant post (nothing metered), None when metering is unavailable — the
    card can render an honest dash instead of a fake zero.
    """
    tokens: float | None = 0
    if thread_id:
        tokens = None
        try:
            if usage_ledger is not None and usage_ledger.is_available:
                now = datetime.now(timezone.utc)
                day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
                usage = await usage_ledger.query_usage(
                    from_ts=day_start, to_ts=now, ref_id=str(thread_id)
                )
                tokens = llm_tokens_from_rows(usage.get("by_category") or [])
        except Exception:
            logger.warning(
                "officer spend: usage query failed (non-fatal)", exc_info=True
            )
            tokens = None
    try:
        ceiling_int = max(0, int(ceiling or 0))
    except (TypeError, ValueError):
        ceiling_int = 0
    return {"tokens": tokens, "ceiling": ceiling_int}


def _officer_editor_block(
    officer_cfg: dict[str, Any], llm_cfg: dict[str, Any]
) -> dict[str, Any]:
    """The kit fields the card's editor seeds from, one shape for both card
    states (officer_post.md §8): live thread metadata when commissioned, the
    durable row config when vacant. Unset numerics stay null so the editor
    shows the true default provenance instead of a materialized fake."""

    def _num(key: str) -> int | None:
        value = officer_cfg.get(key)
        if value is None:
            return None
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    return {
        "model": llm_cfg.get("model"),
        "reasoning_level": llm_cfg.get("reasoning_level"),
        "slots": officer_cfg.get("slots") or None,
        "sleep_minutes": {
            "min": _num("sleep_min_minutes") or 5,
            "max": _num("sleep_max_minutes") or 60,
        },
        "sleep_min_minutes": _num("sleep_min_minutes"),
        "sleep_max_minutes": _num("sleep_max_minutes"),
        "daily_token_ceiling": _num("daily_token_ceiling"),
        "max_actions_per_wake": _num("max_actions_per_wake"),
        "max_concurrent_workers": _num("max_concurrent_workers"),
    }


def _while_vacant_view(state: Any) -> dict[str, Any]:
    """The row's while-vacant ledger in the card's shape:
    ``{entries: [{at?, job_id?, status?, title?}], dropped: n}``. ``title``
    is derived from the stored ``description`` so the storage shape (shared
    with the wake payloads) stays stable."""
    if not isinstance(state, dict):
        state = {}
    raw = state.get("while_vacant")
    entries = []
    if isinstance(raw, list):
        for entry in raw:
            if not isinstance(entry, dict):
                continue
            view = dict(entry)
            if view.get("title") is None and view.get("description"):
                view["title"] = view["description"]
            entries.append(view)
    try:
        dropped = max(0, int(state.get("while_vacant_dropped") or 0))
    except (TypeError, ValueError):
        dropped = 0
    return {"entries": entries, "dropped": dropped}


def _officer_runtime_authorization_view(
    state: Any, *, commissioned: bool
) -> dict[str, Any]:
    """Safe Post projection of the durable runtime-grant incident."""

    if not isinstance(state, dict):
        state = {}
    incident = state.get("runtime_actor_incident")
    if not isinstance(incident, dict):
        return {"status": "authorized" if commissioned else "not_applicable"}
    if incident.get("status") == "open":
        notification = incident.get("notification")
        if not isinstance(notification, dict):
            notification = {}
        return {
            "status": "unavailable",
            "failure_class": str(incident.get("failure_class") or "unavailable"),
            "since": incident.get("first_failed_at"),
            "last_attempted_at": incident.get("last_failed_at"),
            "next_retry_at": incident.get("next_retry_at"),
            "operator_notification": str(notification.get("state") or "pending"),
            "planning_suppressed": True,
        }
    return {
        "status": "authorized" if commissioned else "not_applicable",
        "recovered_at": incident.get("resolved_at"),
        "planning_suppressed": False,
    }


# =============================================================================
# The officer's post — lifecycle + editing (officer_post.md §5/§7, O3/O4)
# =============================================================================

# §7's per-field honesty table, shown in the UI. Sleep bounds act at the next
# filing AND immediately at the watchdog (it re-reads the thread row per
# tick); max_actions/brain are baked into config.officer at attach, so the
# only honest label is the next respawn.
# The bundled expert that defines an officer's job surface
# (config/experts/centurion/). Commission must name it explicitly: the create
# request's default is ``session_base``, which grants no job_control plane.
OFFICER_CONFIG_NAME = "centurion"

# A commissioned officer runs headless — no session exists in which a human
# could answer a permission prompt — so he must not inherit the create
# endpoint's ``supervised`` default. A post may still pin a stricter mode
# explicitly; this only fills the absent case.
OFFICER_PERMISSION_MODE = "autonomous"

_OFFICER_POST_EFFECTS: dict[str, str] = {
    "slots": "next dispatch",
    "auto_pull": "next dispatch",
    "worker_spend_ceiling_daily": "next dispatch",
    "max_concurrent_workers": "next dispatch",
    "daily_token_ceiling": "next delivery",
    "sleep_min_minutes": "next sleep filing + watchdog immediately",
    "sleep_max_minutes": "next sleep filing + watchdog immediately",
    "max_actions_per_wake": "next respawn",
    "brain": "next respawn",
    "communication_policy": "next worker message",
}

_OFFICER_POST_INT_FIELDS = frozenset(
    {
        "max_concurrent_workers",
        "max_actions_per_wake",
        "daily_token_ceiling",
        "sleep_min_minutes",
        "sleep_max_minutes",
    }
)

_OFFICER_POST_POSITIVE_NUMBER_FIELDS = frozenset({"worker_spend_ceiling_daily"})

# Row-only worker-message routing policy (officer_post.md §7): the server
# resolves it per message, the officer thread can never rewrite it, and it is
# deliberately NEVER mirrored into thread metadata.
_COMMUNICATION_WORKER_MESSAGES = frozenset(
    {"user_direct", "officer_and_user", "officer_first"}
)
_COMMUNICATION_RESPONSE_MINUTES_BOUNDS = (5, 120)


def _validated_officer_post_patch(
    body: Any,
) -> tuple[dict[str, Any], Optional[dict[str, Any]], dict[str, str]]:
    """Validate a partial post edit (PATCH body, commission body — same shape).

    Returns ``(config_fragment, communication_policy_patch, effects)`` where
    the fragment is row/thread-mergeable (``{"officer": {...}, "llm":
    {...}}``), the policy patch stays row-only, and ``effects`` carries §7's
    per-field labels for exactly the keys the caller sent. Raises
    HTTPException(400) on unknown fields or bad values — a typo'd kit fails
    HERE, the same hard line the create funnel draws
    (``_validated_session_officer_override``).

    Null-as-clear (the card's revert affordance): an explicit ``null`` on
    ``slots`` (→ flat cap), ``brain`` (→ session default), or any numeric
    field (→ platform default) writes a JSON null through the deep merge —
    every reader treats null as unset. ``communication_policy: null`` is
    refused with an explanation; the policy always has explicit values.
    """
    if body is None:
        return {}, None, {}
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="Body must be a JSON object")
    unknown = set(body) - set(_OFFICER_POST_EFFECTS)
    if unknown:
        raise HTTPException(
            status_code=400,
            detail=f"Unknown officer post fields: {sorted(unknown)}",
        )

    officer_patch: dict[str, Any] = {}
    llm_patch: dict[str, Any] = {}
    comm_patch: Optional[dict[str, Any]] = None

    if "slots" in body:
        if body["slots"] is None:
            officer_patch["slots"] = None  # revert to flat cap
        else:
            # The same hard validation provision gets — a typo'd kit 400s.
            from orchestrator.services.officer_slots import validate_slots_spec

            try:
                officer_patch["slots"] = validate_slots_spec(body["slots"])
            except ValueError as exc:
                raise HTTPException(status_code=400, detail=str(exc)) from exc

    if "auto_pull" in body:
        value = body["auto_pull"]
        if value is None:
            # Null clears to the safe database/UI default rather than leaving
            # a truthy historical projection behind.
            officer_patch["auto_pull"] = False
        elif not isinstance(value, bool):
            raise HTTPException(status_code=400, detail="auto_pull must be a boolean")
        else:
            officer_patch["auto_pull"] = value

    for key in sorted(_OFFICER_POST_POSITIVE_NUMBER_FIELDS):
        if key not in body:
            continue
        value = body[key]
        if value is None:
            officer_patch[key] = None
            continue
        if isinstance(value, bool):
            raise HTTPException(
                status_code=400, detail=f"{key} must be a positive USD number"
            )
        try:
            ceiling = float(value)
        except (TypeError, ValueError) as exc:
            raise HTTPException(
                status_code=400, detail=f"{key} must be a positive USD number"
            ) from exc
        if not math.isfinite(ceiling) or ceiling <= 0:
            raise HTTPException(
                status_code=400, detail=f"{key} must be a positive USD number"
            )
        officer_patch[key] = ceiling

    for key in sorted(_OFFICER_POST_INT_FIELDS):
        if key in body:
            if body[key] is None:
                officer_patch[key] = None  # revert to the platform default
                continue
            try:
                officer_patch[key] = max(0, int(body[key]))
            except (TypeError, ValueError) as exc:
                raise HTTPException(
                    status_code=400, detail=f"{key} must be an integer"
                ) from exc

    if "brain" in body:
        brain = body["brain"]
        if brain is None:
            # Clear the whole override — he thinks on the session default.
            llm_patch["model"] = None
            llm_patch["reasoning_level"] = None
            brain = {}
        if not isinstance(brain, dict) or (not brain and body["brain"] is not None):
            raise HTTPException(
                status_code=400,
                detail="brain must be an object of model and/or reasoning_level",
            )
        unknown_brain = set(brain) - {"model", "reasoning_level"}
        if unknown_brain:
            raise HTTPException(
                status_code=400,
                detail=f"Unknown brain keys: {sorted(unknown_brain)}",
            )
        if "model" in brain:
            model = brain["model"]
            if model is None:
                llm_patch["model"] = None
            elif not isinstance(model, str) or not model.strip() or len(model) > 128:
                raise HTTPException(
                    status_code=400, detail="brain.model must be a short string"
                )
            else:
                llm_patch["model"] = model.strip()
        if "reasoning_level" in brain:
            # Same vocabulary gate as the create bridge — garbage fails loud,
            # the family capability still clamps at attach.
            llm_patch["reasoning_level"] = (
                None
                if brain["reasoning_level"] is None
                else _validated_reasoning_level(brain["reasoning_level"])
            )

    if "communication_policy" in body:
        policy = body["communication_policy"]
        if policy is None:
            raise HTTPException(
                status_code=400,
                detail=(
                    "communication_policy cannot be cleared — send explicit "
                    "values for worker_messages and/or officer_response_minutes"
                ),
            )
        if not isinstance(policy, dict) or not policy:
            raise HTTPException(
                status_code=400,
                detail=(
                    "communication_policy must be an object of worker_messages "
                    "and/or officer_response_minutes"
                ),
            )
        unknown_policy = set(policy) - {
            "worker_messages",
            "officer_response_minutes",
        }
        if unknown_policy:
            raise HTTPException(
                status_code=400,
                detail=f"Unknown communication_policy keys: {sorted(unknown_policy)}",
            )
        cleaned_policy: dict[str, Any] = {}
        if "worker_messages" in policy:
            if policy["worker_messages"] not in _COMMUNICATION_WORKER_MESSAGES:
                raise HTTPException(
                    status_code=400,
                    detail=(
                        "worker_messages must be one of "
                        f"{sorted(_COMMUNICATION_WORKER_MESSAGES)}"
                    ),
                )
            cleaned_policy["worker_messages"] = policy["worker_messages"]
        if "officer_response_minutes" in policy:
            lo, hi = _COMMUNICATION_RESPONSE_MINUTES_BOUNDS
            try:
                minutes = int(policy["officer_response_minutes"])
            except (TypeError, ValueError) as exc:
                raise HTTPException(
                    status_code=400,
                    detail="officer_response_minutes must be an integer",
                ) from exc
            if not lo <= minutes <= hi:
                raise HTTPException(
                    status_code=400,
                    detail=f"officer_response_minutes must be between {lo} and {hi}",
                )
            cleaned_policy["officer_response_minutes"] = minutes
        comm_patch = cleaned_policy

    fragment: dict[str, Any] = {}
    if officer_patch:
        fragment["officer"] = officer_patch
    if llm_patch:
        fragment["llm"] = llm_patch
    effects = {key: _OFFICER_POST_EFFECTS[key] for key in body}
    return fragment, comm_patch, effects


def _enforce_officer_auto_pull_release(desired: Any) -> None:
    """Refuse unattended enablement while the deployment release fence is dark.

    Callers pass the *effective* commissioned value, not merely the incoming
    patch. A post enabled before a rollback therefore cannot be recommissioned
    behind a dark fence. False/absent always passes so the supported stop path
    remains available during an incident.
    """

    # Historical JSON written before the typed surface may contain the exact
    # truthy shapes accepted by ``auto_pull_enabled``.  A rollback must fence
    # those too; otherwise a recommission could turn an unsupported string or
    # integer into live unattended authority behind the dark gate.
    if desired in (True, "true", "True", 1) and not OFFICER_AUTO_PULL_RELEASE_ENABLED:
        raise HTTPException(
            status_code=409,
            detail=(
                "Officer auto-pull is not released in this deployment. "
                "Keep it off until the unattended-operation gates are complete."
            ),
        )


def _check_officer_sleep_bounds(
    current_officer_cfg: dict[str, Any], officer_patch: dict[str, Any]
) -> None:
    """min ≤ max over the MERGED view (§7) — a patch of one bound is checked
    against the standing other bound, defaults 5/60 where nothing is set."""
    if not officer_patch or not (
        {"sleep_min_minutes", "sleep_max_minutes"} & set(officer_patch)
    ):
        return

    def _bound(key: str, default: int) -> int:
        if key in officer_patch:
            # A null patch value clears the bound — it reverts to the default.
            if officer_patch[key] is None:
                return default
            return int(officer_patch[key])
        try:
            return int(current_officer_cfg.get(key) or default)
        except (TypeError, ValueError):
            return default

    new_min = _bound("sleep_min_minutes", 5)
    new_max = _bound("sleep_max_minutes", 60)
    if new_min > new_max:
        raise HTTPException(
            status_code=400,
            detail=(
                f"sleep_min_minutes ({new_min}) must not exceed "
                f"sleep_max_minutes ({new_max})"
            ),
        )


async def _inject_officer_notice(officer_thread: dict[str, Any], text: str) -> bool:
    """Best-effort one-liner via the agent's /api/input (bypasses holds by
    design — Legate input always reaches him). Never raises."""
    try:
        from orchestrator.services import session_wake as _sw

        agent = await _sw._resolve_live_agent(postgres_db, officer_thread)
        if agent is None:
            return False
        outcome = await _sw._inject_live(
            agent,
            text,
            delivery_id=str(uuid4()),
            db=postgres_db,
        )
        return outcome == _sw.WakeDeliveryResult.EXECUTED
    except Exception:
        logger.debug("officer notice: inject failed (non-fatal)", exc_info=True)
        return False


async def _deliver_staged_officer_routes(
    routes: list[dict[str, Any]], *, reason: str
) -> int:
    """Deliver durable route fallback intents after their transaction commits.

    A failed dispatch leaves ``user_delivery_at`` null, which is the routing
    reconciler's retry contract. Delivery can therefore never roll back or
    falsify a hold/decommission transition.
    """
    if not routes:
        return 0
    from orchestrator.services import message_routing as _routing_svc

    delivered = 0
    for route in routes:
        try:
            if await _routing_svc.deliver_route_to_user(
                postgres_db, route, reason=reason
            ):
                delivered += 1
        except Exception:
            logger.warning(
                "Officer route %s delivery failed after durable %s transition; "
                "leaving it retryable",
                str(route.get("route_id") or "")[:8],
                reason,
                exc_info=True,
            )
    return delivered


async def _decommission_officer_post(
    thread: dict[str, Any],
    *,
    reason: str,
    force: bool = False,
    allow_orphan_retirement: bool = False,
    retirement: Mapping[str, Any] | None = None,
) -> Optional[dict[str, Any]]:
    """Run the authoritative commissioned -> vacant database transition.

    PostgreSQL reads the thread state again under post -> thread row locks;
    the caller's ``thread`` is identity only. Harvest, wake folding, durable
    route fallback, one incarnation append, unlink and server-owned
    disable/end are one transaction. Route notification delivery happens only
    after that commit and a failed notifier leaves ``user_delivery_at`` null
    for the reconciler.
    """
    project_id = thread.get("project_id")
    if not project_id:
        return None
    project_id = str(project_id)
    thread_id = str(thread["id"])
    retirement_kwargs: dict[str, Any] = {}
    if retirement is not None:
        retirement_kwargs = {
            "retirement_token": str(retirement.get("token")),
            "retirement_generation": str(retirement.get("generation")),
            "retirement_settle_status": str(
                (retirement.get("context") or {}).get("settle_status") or ""
            ),
        }
    summary = await postgres_db.decommission_project_officer(
        project_id,
        thread_id,
        reason=reason,
        force=force,
        allow_orphan_retirement=allow_orphan_retirement,
        **retirement_kwargs,
    )

    routes = summary.get("routes") or []
    delivered = (
        await _deliver_staged_officer_routes(routes, reason="officer_decommissioned")
        if summary.get("transitioned")
        else 0
    )
    summary["routes_staged"] = len(routes)
    summary["routes_delivered"] = delivered
    summary.pop("routes", None)
    if summary.get("blocked_by_in_flight"):
        logger.info(
            "officer post %s: no-force decommission held by %d in-flight jobs",
            project_id[:8],
            len(summary.get("in_flight_jobs") or []),
        )
    elif summary.get("transitioned"):
        logger.info(
            "officer post %s: decommissioned thread %s (reason=%s, harvested=%s, "
            "queue folded=%d deleted=%d)",
            project_id[:8],
            thread_id[:8],
            reason,
            summary.get("harvested", False),
            summary.get("folded", 0),
            summary.get("deleted", 0),
        )
    else:
        logger.info(
            "officer post %s: decommission no-op for thread %s "
            "(already_decommissioned=%s orphan_retired=%s)",
            project_id[:8],
            thread_id[:8],
            summary.get("already_decommissioned", False),
            summary.get("orphan_retired", False),
        )
    return summary


def _officer_in_flight_decommission_response(
    summary: dict[str, Any],
) -> dict[str, Any]:
    jobs = list(summary.get("in_flight_jobs") or [])
    return {
        "status": "in_flight",
        "warning": (
            f"{len(jobs)} job(s) in flight on this post. Decommission leaves "
            "them running; retry with force=true to proceed."
        ),
        "in_flight_jobs": jobs,
    }


class OfficerDecommissionRequest(BaseModel):
    """Body for POST .../officer/decommission."""

    force: bool = Field(
        False,
        description=(
            "Acknowledge the in-flight-jobs warning (jobs keep running — force "
            "never cancels them) and end a mid-turn session."
        ),
    )
    reason: str | None = Field(
        None, description="Recorded on the incarnation entry (default 'decommissioned')"
    )


class OfficerHoldRequest(BaseModel):
    """Body for POST .../officer/hold."""

    note: str | None = Field(None, description="Shown on the card's held badge")


@app.post("/api/projects/{project_id}/officer/recycle")
async def recycle_project_officer(request: Request, project_id: str) -> dict[str, Any]:
    """Recycle only the commissioned Officer's disposable runtime pod.

    The existing project owner/admin policy is authoritative.  This is not an
    Officer tool and runtime actors cannot use it to recycle themselves.
    """

    await require_project_owner(request, postgres_db, project_id, allow_archived=False)
    officer = await postgres_db.get_officer_thread_for_project(project_id)
    if officer is None:
        raise HTTPException(status_code=409, detail="The Officer Post is vacant")
    recycler = _persistent_thread_recycler
    if recycler is None or not persistent_provisioner.is_available:
        raise HTTPException(
            status_code=503, detail="Persistent runtime lifecycle is unavailable"
        )
    thread_id = str(officer["id"])
    # The recycler provisions from the STORED threads.config_name, so a row
    # poisoned before that column was validated on write reaches the pod
    # entrypoint's allow-list here and raises. That is a bad row, not a broken
    # server: answer it with the validator's own sentence and a 4xx the
    # operator can act on, instead of letting the generic Exception handler
    # turn it into an opaque 500.
    try:
        result = await recycler.request_and_reconcile(
            thread_id=thread_id,
            reason="operator_requested",
            expected_build_sha=persistent_provisioner.expected_build_sha,
            observation=await recycler.observe(thread_id),
            expected_project_id=project_id,
        )
    except InvalidConfigNameError as exc:
        logger.warning(
            "Officer runtime recycle refused for thread %s: %s", thread_id, exc
        )
        raise HTTPException(
            status_code=422,
            detail=(
                f"This Officer's stored session config cannot be booted: {exc} "
                "Decommission and re-commission the post to reset it."
            ),
        ) from exc
    if result.state in {"blocked", "cancelled"}:
        raise HTTPException(
            status_code=409,
            detail="Officer runtime recycle could not acquire current authority",
        )
    return {"thread_id": thread_id, **result.safe_view()}


@app.post("/api/projects/{project_id}/officer/commission")
async def commission_project_officer(
    request: Request,
    project_id: str,
    body: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Raise an officer onto the project's post (officer_post.md §5).

    Auth: project admin (owner or platform admin) — the kit belongs to the
    century, not to whoever clicked provision (§11 Q1, decided). Optional
    body: the same partial kit as PATCH; validated and merged into the row
    FIRST, so the thread is created from the durable record. A stale
    ended/disabled link completes the authoritative handoff before provisioning;
    the new thread then goes through the one create funnel, whose registration
    claim links it and 409s rivals. The continuity brief is his first wake:
    vacant-since/until, a pointer at his restored state + charter, and the
    while-vacant ledger.

    Project-binding invariant (officer_knowledge_plane.md §3.1, K1): a
    commissioned background officer has exactly one project — the sole native
    writable KB — and no override may replace that write target. This
    endpoint satisfies most of it by construction: the project comes from the
    URL, ``ThreadCreateRequest`` carries a single ``project_id``, and the kit
    patch vocabulary (``_SESSION_OFFICER_OVERRIDE_KEYS`` + workspace/tools/
    llm/interactive passthrough) has no project or datasource channel. The
    guard below rejects an unparseable project id (fail-closed 422 instead of
    a DB-layer 500); the agent-side attach re-checks the resolved bindings
    and refuses to boot a mis-bound officer.
    """
    try:
        UUID(str(project_id))
    except (TypeError, ValueError):
        raise HTTPException(
            status_code=422,
            detail=(
                "officer commission requires one valid project id — got "
                f"'{project_id}'. The officer's post binds exactly one "
                "project knowledge base (officer_knowledge_plane.md §3.1)."
            ),
        )
    user, project = await require_project_owner(
        request, postgres_db, project_id, allow_archived=False
    )

    # Parse the money-spending authority before stale-link handoff or any
    # other lifecycle mutation. A closed release fence must be a no-write
    # refusal, not a half-completed commission.
    fragment, comm_patch, _effects = _validated_officer_post_patch(body)
    requested_officer_patch = fragment.get("officer") or {}
    if requested_officer_patch.get("auto_pull") is True:
        _enforce_officer_auto_pull_release(True)

    # Capability gate, BEFORE anything mutates. The config PDP would also catch
    # this downstream (``evaluate`` refuses ``officer.enabled`` without the
    # grant, which is what covers a hand-rolled thread create), but only after
    # ``update_project_officer_post`` below has already written the kit — a 422
    # on a half-applied commission. Fail here, loudly, with nothing touched.
    if not await postgres_db.user_can_run_unattended_operations(user, project_id):
        raise HTTPException(
            status_code=403,
            detail=(
                "Commissioning an officer requires the unattended_operations "
                "capability grant. Ask an administrator to grant it "
                "(Admin → Grants) for your user or for this project."
            ),
        )

    standing = await postgres_db.get_officer_thread_for_project(project_id)
    if standing:
        raise HTTPException(
            status_code=409,
            detail=(
                "already commissioned: this project's post is held by thread "
                f"{standing['id']} — decommission him before raising another "
                "officer."
            ),
        )

    post = await postgres_db.get_or_create_project_officer(project_id)
    if post is None:
        raise HTTPException(status_code=404, detail="Project post not found")

    row_officer_before = (post.get("config_override") or {}).get("officer") or {}
    effective_auto_pull = (
        requested_officer_patch.get("auto_pull")
        if "auto_pull" in requested_officer_patch
        else row_officer_before.get("auto_pull")
    )
    _enforce_officer_auto_pull_release(effective_auto_pull)

    # A stale ended/disabled link is not a live commission, but it still owns
    # an unfinished handoff. Complete that handoff atomically before preparing
    # a successor; registration itself never performs a partial fold.
    stale_link = post.get("thread_id")
    if stale_link:
        stale_thread = await postgres_db.get_thread(str(stale_link)) or {
            "id": str(stale_link),
            "project_id": project_id,
        }
        try:
            await _decommission_officer_post(stale_thread, reason="retired", force=True)
        except OfficerPostLifecycleConflict as exc:
            raise HTTPException(status_code=409, detail=exc.detail) from exc
        post = await postgres_db.get_project_officer(project_id) or post

    _check_officer_sleep_bounds(
        (post.get("config_override") or {}).get("officer") or {},
        fragment.get("officer") or {},
    )
    try:
        post_generation = post.get("updated_at")
        if post_generation is None:
            raise OfficerPostLifecycleConflict(
                "commission_generation_missing",
                "Officer Post has no lifecycle generation; retry commission.",
            )
        updated = await postgres_db.update_project_officer_post(
            project_id,
            config_updates=fragment or None,
            communication_policy_patch=comm_patch,
            expected_vacant_updated_at=post_generation,
        )
    except OfficerPostLifecycleConflict as exc:
        status = 400 if exc.code == "invalid_config" else 409
        raise HTTPException(status_code=status, detail=exc.detail) from exc
    if updated is None:
        raise HTTPException(status_code=404, detail="Project post not found")
    post = updated["post"] or post

    # Build the funnel request from the row. llm/interactive ride the
    # request's own bridges (the funnel rebuilds config_override from
    # validated fragments only); the officer block is sanitized to the
    # create-time vocabulary with enabled forced on — commission is the one
    # legitimate writer of a live officer class.
    row_cfg = post.get("config_override") or {}
    row_officer = row_cfg.get("officer") or {}
    officer_fragment = {
        k: v
        for k, v in row_officer.items()
        # Nulls are cleared fields (PATCH null-as-clear) — an omitted key is
        # how the funnel spells "default", so they must not travel.
        # Auto-pull, the century spend ceiling, and the complete roster travel
        # only through the private durable-snapshot seam. Keeping them out of
        # this public-shaped payload makes an accidental future direct call to
        # the generic validator fail closed instead of acquiring Post authority.
        if k in _SESSION_OFFICER_OVERRIDE_KEYS
        and k not in _OFFICER_POST_OWNED_CREATE_KEYS
        and k != "conference"
        and v is not None
    }
    officer_fragment["enabled"] = True
    create_override: dict[str, Any] = {"officer": officer_fragment}
    for passthrough in ("workspace", "tools"):
        sub = row_cfg.get(passthrough)
        if isinstance(sub, dict) and sub:
            create_override[passthrough] = sub
    # The commissioning request owns infrastructure, independently of Centurion.
    create_override.setdefault("workspace", {}).setdefault("backend", "none")
    row_llm = row_cfg.get("llm") or {}
    row_interactive = row_cfg.get("interactive") or {}
    create_request = ThreadCreateRequest(
        project_id=project_id,
        title=f"Centurion — {project.get('name') or project_id[:8]}",
        # The expert IS the officer's job surface. Without this the request
        # falls to ThreadCreateRequest's ``session_base`` default, and a
        # commissioned officer boots with research/citation tools and NO
        # job_control plane — he cannot dispatch, steer, approve or read
        # evidence, which is the whole of his charge. Found live on the
        # Resavio change of command (2026-08-15): the endpoint-commissioned
        # officer had 34 tools and not one could create a job, while the
        # July officer — provisioned by hand with config_name=centurion —
        # had the full 49. Commissioning selects no workspace above; Centurion
        # supplies the reviewed knowledge grant and behavioral settings; ``officer.enabled`` stays false there and is flipped by
        # the thread override above, which is the documented split.
        config_name=OFFICER_CONFIG_NAME,
        config_override=create_override,
        model=row_llm.get("model"),
        reasoning_level=row_llm.get("reasoning_level"),
        temperature=row_llm.get("temperature"),
        # A background officer is HEADLESS: there is no session for a human to
        # answer a permission prompt in. Falling to the create default
        # (``supervised``) gates every tool call on an approval that can never
        # arrive — the officer issues his calls, the first one parks the turn
        # ("Permission gate unanswered … parking turn; N call(s) left
        # ungated"), and the rest are stripped as orphans on the next pass. He
        # cycles turns forever executing NOTHING: no reads, no dispatches, no
        # sleep filed, empty assistant text, and not one tool result persisted.
        # Observed live 2026-08-15 alongside the config_name defect above, and
        # far harder to see, because every symptom looks like a model problem.
        # The row may still pin a stricter mode deliberately; only the absent
        # case is defaulted.
        permission_mode=row_interactive.get("permission_mode")
        or OFFICER_PERMISSION_MODE,
        # Third field of this shape, after config_name and permission_mode:
        # the endpoint hand-builds the funnel request and omits what the UI
        # supplies (buildConferenceThreadCreateBody sends exactly this for the
        # conference thread). Without it the post falls to ``omitted_compat``
        # and persists ``datasource_ids: []``, which is then inherited by
        # anything that legitimately reads the officer's own selection. His
        # tier is lite, so default_datasource_selection correctly withholds
        # clone-based repositories here — dispatch resolves defaults again
        # against the *worker's* backend, which is where the repo attaches.
        use_datasource_defaults=True,
    )
    create_request._officer_post_config_snapshot = copy.deepcopy(row_cfg)
    created = await create_thread(create_request, request)
    thread_id = str(created["thread_id"])

    # Registration, state restore, while-vacant drain, and brief INSERT were
    # one post-locked transaction inside the create funnel. This final locked
    # confirmation linearizes the response against an immediately racing
    # decommission: whichever holds the post first defines the truthful result.
    continuity = create_request._officer_commission_result
    if continuity is None or not await postgres_db.confirm_project_officer_incarnation(
        project_id, thread_id
    ):
        raise HTTPException(
            status_code=409,
            detail=(
                "Officer commission was superseded by a concurrent lifecycle "
                "transition; re-read the post before retrying."
            ),
        )
    brief_enqueued = bool(continuity.get("brief_enqueued"))
    if brief_enqueued:
        _kick_officer_event_drain(postgres_db)
    else:
        logger.warning(
            "officer commission: brief wake did not enqueue for thread %s",
            thread_id[:8],
        )

    return {
        "status": "commissioned",
        "thread_id": thread_id,
        "title": create_request.title,
        "brief_enqueued": brief_enqueued,
        "while_vacant": len(continuity.get("while_vacant") or []),
        "while_vacant_dropped": int(continuity.get("while_vacant_dropped") or 0),
        "state_restored": bool(continuity.get("state_restored")),
    }


@app.post("/api/projects/{project_id}/officer/decommission")
async def decommission_project_officer(
    request: Request,
    project_id: str,
    body: OfficerDecommissionRequest | None = None,
) -> dict[str, Any]:
    """Stand the officer down and keep everything he had (officer_post.md §5).

    Auth: project admin. Returns a 200 warning result listing in-flight jobs unless
    ``force`` — and force only acknowledges the warning: jobs are LEFT
    RUNNING either way; their completions land on the vacant post's ledger.
    The actual hygiene (harvest → queue fold → unlink → incarnation) runs
    inside the shared ``end_thread`` stand-down, so this endpoint and a
    direct thread DELETE are one funnel.
    """
    await require_project_owner(request, postgres_db, project_id)
    body = body or OfficerDecommissionRequest()
    reason = (body.reason or "").strip() or "decommissioned"

    post = await postgres_db.get_or_create_project_officer(project_id)
    if post is None:
        raise HTTPException(status_code=404, detail="Project post not found")
    linked_tid = post.get("thread_id")
    if not linked_tid:
        # Idempotent lifecycle command: a lost first response may be retried.
        # The post row is already the durable proof of vacancy; do not append
        # a synthetic second incarnation.
        return {
            "status": "decommissioned",
            "already_vacant": True,
            "incarnations": post.get("incarnations") or [],
        }
    linked_tid = str(linked_tid)

    thread = await postgres_db.get_thread(linked_tid)
    if thread is None:
        # The FK normally clears this link on hard delete, but a stale/missing
        # fixture is repaired through the SAME atomic handoff, not two writes.
        try:
            summary = await _decommission_officer_post(
                {"id": linked_tid, "project_id": project_id},
                reason=reason,
                force=body.force,
            )
        except OfficerPostLifecycleConflict as exc:
            raise HTTPException(status_code=409, detail=exc.detail) from exc
        if summary and summary.get("blocked_by_in_flight"):
            return _officer_in_flight_decommission_response(summary)
        return {
            "status": "decommissioned",
            "thread_id": linked_tid,
            "note": "thread row was already gone; link cleared",
            **{
                key: value
                for key, value in (summary or {}).items()
                if key not in {"incarnation", "post"}
            },
        }

    if thread.get("status") == "ended":
        # Crash-ended incarnation under the page-and-wait policy: the thread
        # is already down — run the post hygiene directly, no end flow.
        try:
            summary = (
                await _decommission_officer_post(
                    thread, reason=reason, force=body.force
                )
                or {}
            )
        except OfficerPostLifecycleConflict as exc:
            raise HTTPException(status_code=409, detail=exc.detail) from exc
        if summary.get("blocked_by_in_flight"):
            return _officer_in_flight_decommission_response(summary)
        return {
            "status": "decommissioned",
            "thread_id": linked_tid,
            "already_ended": True,
            **{k: v for k, v in summary.items() if k != "incarnation"},
        }

    flow_result = await _end_thread_flow(
        linked_tid,
        thread,
        permanent=False,
        force=body.force,
        officer_retire_reason=reason,
        officer_post_required=True,
        include_officer_handoff=True,
    )
    if flow_result.get("status") == "in_flight":
        return flow_result
    handoff = flow_result.pop("_officer_handoff", {}) or {}

    fresh_post = await postgres_db.get_project_officer(project_id) or {}
    return {
        "status": "decommissioned",
        "thread_id": linked_tid,
        "in_flight_jobs": handoff.get("in_flight_jobs") or [],
        "harvested": bool(project_officer_harvested_state(fresh_post.get("state"))),
        "incarnations": fresh_post.get("incarnations") or [],
    }


@app.post("/api/projects/{project_id}/officer/hold")
async def hold_project_officer(
    request: Request,
    project_id: str,
    body: OfficerHoldRequest | None = None,
) -> dict[str, Any]:
    """Maintenance hold — pause ≠ retire (officer_post.md §5, decided 08-01).

    Auth: project admin. Stamps ``officer.hold = {kind, since, note}`` on the
    THREAD (hold is runtime state; a vacant post 400s) with — critically —
    NO ``thread_id`` key: that absence is what keeps the watchdog's
    stale-conference-hold self-heal from ever releasing it. One key, four
    effects, all pre-wired by the conference machinery: drain skips him,
    dispatches 409, watchdog stands down, nothing self-heals.
    """
    await require_project_owner(request, postgres_db, project_id)
    officer = await postgres_db.get_officer_thread_for_project(project_id)
    if not officer:
        raise HTTPException(
            status_code=400, detail="The post is vacant — nothing to hold"
        )
    officer_tid = str(officer["id"])
    existing = _thread_officer_meta(officer).get("hold")
    if existing:
        raise HTTPException(
            status_code=400,
            detail=(
                "already held "
                f"(kind={existing.get('kind') if isinstance(existing, dict) else '?'})"
                " — release before holding again"
            ),
        )
    hold = {
        "kind": "maintenance",
        "since": datetime.now(timezone.utc).isoformat(),
        "note": ((body.note if body else None) or "").strip(),
    }
    try:
        hold_result = await postgres_db.set_project_officer_hold(
            project_id,
            expected_thread_id=officer_tid,
            hold=hold,
            route_reason="officer_hold",
        )
    except OfficerPostLifecycleConflict as exc:
        raise HTTPException(status_code=409, detail=exc.detail) from exc
    staged_routes = hold_result.get("routes") or []
    delivered_routes = await _deliver_staged_officer_routes(
        staged_routes, reason="officer_hold"
    )
    notified = await _inject_officer_notice(
        officer,
        "[maintenance hold — the Legate has stood you down. Take no "
        "scheduling actions; your timers and events queue durably and arrive "
        "when the hold is released. Legate messages still reach you.]",
    )
    logger.info(
        "officer %s: maintenance hold stamped (project %s)",
        officer_tid[:8],
        project_id[:8],
    )
    return {
        "status": "held",
        "thread_id": officer_tid,
        "held": hold,
        "notified": notified,
        "drained_blocking_routes": len(staged_routes),
        "delivered_blocking_routes": delivered_routes,
    }


@app.post("/api/projects/{project_id}/officer/release")
async def release_project_officer(request: Request, project_id: str) -> dict[str, Any]:
    """Release the officer's hold (officer_post.md §5). Auth: project admin.

    Clears via the established lever — deep-merge ``{"officer": {"hold":
    None}}`` → JSON null, which every reader (watchdog, wake claim, dispatch
    fence) treats as unheld. Queued events drain within one ~20s tick; the
    kick below just makes it immediate.
    """
    await require_project_owner(request, postgres_db, project_id, allow_archived=False)
    officer = await postgres_db.get_officer_thread_for_project(project_id)
    if not officer:
        raise HTTPException(
            status_code=400, detail="The post is vacant — nothing to release"
        )
    officer_tid = str(officer["id"])
    hold = _thread_officer_meta(officer).get("hold")
    if not hold:
        raise HTTPException(status_code=400, detail="The officer is not held")
    if isinstance(hold, dict) and hold.get("_persistent_recycle_generation"):
        raise HTTPException(
            status_code=409,
            detail=(
                "The Officer runtime recycle owns this maintenance hold; "
                "it releases only after replacement authority is healthy"
            ),
        )
    try:
        await postgres_db.set_project_officer_hold(
            project_id,
            expected_thread_id=officer_tid,
            hold=None,
        )
    except OfficerPostLifecycleConflict as exc:
        raise HTTPException(status_code=409, detail=exc.detail) from exc
    _kick_officer_event_drain(postgres_db)
    notified = await _inject_officer_notice(
        officer,
        "[hold released — resume your duties. Events queued during the hold "
        "arrive with your next wake.]",
    )
    logger.info(
        "officer %s: hold released (project %s, was kind=%s)",
        officer_tid[:8],
        project_id[:8],
        hold.get("kind") if isinstance(hold, dict) else "?",
    )
    return {"status": "released", "thread_id": officer_tid, "notified": notified}


OFFICER_NOTE_MAX_CHARS = 8000


class OfficerNoteRequest(BaseModel):
    """Body for POST .../officer/note."""

    model_config = ConfigDict(extra="forbid")

    message: str = Field(..., description="What the Legate wants him to know or do")


def _format_legate_note(user: dict[str, Any], message: str) -> str:
    """Stamp a note with its author before it reaches the officer.

    He treats a Legate directive as top authority, so who wrote it is part of
    the message: a note composed by an assistant holding the Legate's
    credentials must not read as words the Legate typed himself.
    """
    actor = str(user.get("display_name") or user.get("email") or "the Legate").strip()
    channel = "via MCP" if str(user.get("auth_method") or "") == "mcp" else "via API"
    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    return f"[Legate note — {actor} {channel}, {stamp}]\n\n{message}"


@app.post("/api/projects/{project_id}/officer/note")
async def send_project_officer_note(
    request: Request,
    project_id: str,
    body: OfficerNoteRequest,
) -> dict[str, Any]:
    """Send the project's officer a one-way note (officer_legate_channel.md).

    Auth: project owner — a note carries command authority, the same bar as
    hold/release. The reply, if he has one, arrives in his log or as a page;
    this endpoint deliberately has no ask-and-wait leg.

    The response states which durable acceptance happened rather than a bare
    200: ``queued`` is a wake row whose stable identity is claimed by the
    exact current runtime, and ``held`` is fenced behind a hold that must lift
    first. Durable acceptance is never reported as provider admission.
    """
    user, _project = await require_project_owner(
        request, postgres_db, project_id, allow_archived=False
    )
    message = (body.message or "").strip()
    if not message:
        raise HTTPException(status_code=400, detail="message must not be empty")
    if len(message) > OFFICER_NOTE_MAX_CHARS:
        raise HTTPException(
            status_code=400,
            detail=(
                f"message must be at most {OFFICER_NOTE_MAX_CHARS} characters "
                f"(got {len(message)}) — put the long form in the knowledge "
                "base and point him at it"
            ),
        )
    officer = await postgres_db.get_officer_thread_for_project(project_id)
    if not officer:
        raise HTTPException(
            status_code=409,
            detail=(
                "The post is vacant — commission an officer before sending him orders"
            ),
        )
    officer_tid = str(officer["id"])
    text = _format_legate_note(user, message)
    delivered = await _deliver_officer_note(postgres_db, officer, text)
    if delivered == "queued":
        _kick_officer_event_drain(postgres_db)
    next_wake_at = None
    if delivered != "live":
        timer = await postgres_db.get_pending_officer_timer(officer_tid)
        next_wake_at = (timer or {}).get("fire_at")
    hold = _thread_officer_meta(officer).get("hold") or None
    logger.info(
        "officer %s: legate note %s (project %s, %d chars)",
        officer_tid[:8],
        delivered,
        project_id[:8],
        len(message),
    )
    return {
        "delivered": delivered,
        "thread_id": officer_tid,
        "project_id": project_id,
        "next_wake_at": next_wake_at,
        "held": hold,
    }


@app.patch("/api/projects/{project_id}/officer")
async def patch_project_officer(
    request: Request, project_id: str, body: dict[str, Any]
) -> dict[str, Any]:
    """Edit the post — the missing form (officer_post.md §7). Auth: project
    owner or system admin (the kit belongs to the century, §11 decision 1).

    Writes the durable row always; when commissioned, merges the fragment into
    thread metadata (with an explicitly supplied ``slots`` map replacing the
    whole roster) and injects a one-line notice —
    deliberately NOT a wake (the next sitrep's capacity line carries the
    truth). Shrinking below in-flight is drain semantics, decided: the 409
    lives at the next dispatch, running jobs are untouched.
    ``communication_policy`` is row-only and never touches the thread.
    """
    await require_project_owner(request, postgres_db, project_id, allow_archived=False)
    fragment, comm_patch, effects = _validated_officer_post_patch(body)
    if (fragment.get("officer") or {}).get("auto_pull") is True:
        _enforce_officer_auto_pull_release(True)
    if not fragment and comm_patch is None:
        raise HTTPException(
            status_code=400,
            detail=(
                "Nothing to update — send at least one of "
                f"{sorted(_OFFICER_POST_EFFECTS)}"
            ),
        )
    post = await postgres_db.get_or_create_project_officer(project_id)
    if post is None:
        raise HTTPException(status_code=404, detail="Project post not found")
    _check_officer_sleep_bounds(
        (post.get("config_override") or {}).get("officer") or {},
        fragment.get("officer") or {},
    )
    try:
        update = await postgres_db.update_project_officer_post(
            project_id,
            config_updates=fragment or None,
            communication_policy_patch=comm_patch,
        )
    except OfficerPostLifecycleConflict as exc:
        status = 400 if exc.code == "invalid_config" else 409
        raise HTTPException(status_code=status, detail=exc.detail) from exc
    if update is None:
        raise HTTPException(status_code=404, detail="Project post not found")
    post = update["post"] or post
    officer = update.get("thread")
    applied_to_thread = bool(update.get("applied_to_thread"))
    if officer and fragment and applied_to_thread:
        changed = ", ".join(sorted(k for k in effects if k != "communication_policy"))
        await _inject_officer_notice(
            officer,
            f"[post updated — {changed}. No action needed; your next sitrep "
            "reflects the change.]",
        )

    return {
        "status": "updated",
        "commissioned": bool(officer),
        "applied_to_thread": bool(applied_to_thread),
        "effects": effects,
        "config_override": post.get("config_override") or {},
        "communication_policy": post.get("communication_policy") or {},
    }


@app.post("/api/agents/threads/{thread_id}/officer/wake")
async def agent_file_officer_wake(
    request: Request,
    thread_id: str,
    body: OfficerWakeRequest,
) -> dict[str, Any]:
    """File an officer session's durable sleep timer. **Internal** — requires
    ``X-Internal-Key``; ingress strips this path.

    Called by the sleep tool's park path (centurion.md §4, decision
    2026-07-29): the timer is a Postgres ``session_wake_events`` row
    (source='timer'), so pod or node death never loses the schedule — the
    drain fires it when due. Minutes are clamped to the thread's officer
    bounds HERE; the tool's value is a request, not an order.
    """
    await require_internal(request)
    thread = await postgres_db.get_thread(thread_id)
    if thread is None:
        raise HTTPException(status_code=404, detail="Thread not found")
    officer_meta = _thread_officer_meta(thread)
    if not _officer_meta_enabled(officer_meta):
        raise HTTPException(status_code=409, detail="Thread is not an officer session")
    try:
        sleep_min = int(officer_meta.get("sleep_min_minutes") or 5)
        sleep_max = int(officer_meta.get("sleep_max_minutes") or 60)
    except (TypeError, ValueError):
        sleep_min, sleep_max = 5, 60
    minutes = max(sleep_min, min(int(body.minutes), max(sleep_min, sleep_max)))
    filed = await file_officer_timer(postgres_db, thread_id, minutes, body.reason)
    return {"filed": filed, "minutes": minutes}


def _officer_session_link(thread_id: str) -> str | None:
    """Absolute cockpit deep link to an officer session, or None when the
    cockpit base URL is unknown.

    Reads ``COCKPIT_EXTERNAL_URL`` (chart configmap, from ``srw.cockpitUrl``
    — the same var the email/notification services use for their deep links)
    at call time. Unset → None: a page without a link beats a page with a
    broken one.
    """
    base = os.getenv("COCKPIT_EXTERNAL_URL", "").strip().rstrip("/")
    if not base:
        return None
    return f"{base}/sessions/{thread_id}"


async def _dispatch_officer_page(
    thread: dict,
    thread_id: str,
    subject: str,
    message_md: str,
    *,
    category: str = "officer_question",
    severity: str = "high",
    dedup_key: str | None = None,
) -> str | None:
    """Record an officer → Legate notification on the thread owner's feed.

    Shared by the notify endpoint's page/digest urgencies, the recycler's
    respawn-failure alert and the runtime-authorization incident. Delivery
    (email per the owner's preferences, later the escalation ladder) is the
    notification system's business, not this function's: ``severity`` is the
    officer's urgency, never a channel selector (unified notification system,
    D1). A ``high`` row mails now; ``low`` is in-app only.

    Appends a deep link to the officer's session so every page carries a way
    back. Deliberately a labeled bare URL, not a markdown ``[label](url)``:
    the email leg renders markdown (services/email_markdown.py, which also
    auto-links a bare URL) but ntfy/Slack get the raw text — a bare URL is
    clickable-or-copyable in every leg, brackets-and-parens only in email.

    Returns the notification id when the row was recorded (new or replayed);
    ``None`` only when there is nobody to notify or the feed write itself
    failed.
    """
    user_id = thread.get("user_id")
    if not user_id:
        return None
    subject = subject or "Your centurion needs you"
    session_link = _officer_session_link(thread_id)
    page_body = message_md
    if session_link:
        page_body = f"{message_md}\n\nOpen his log to reply: {session_link}"
    if not dedup_key:
        # Identical text on one day collapses onto one row — the anti-spam
        # role the per-day page budget used to play.
        text_digest = hashlib.sha1(
            f"{subject}\n{message_md}".encode("utf-8")
        ).hexdigest()[:16]
        today = datetime.now(timezone.utc).date().isoformat()
        dedup_key = f"officer_notify:{thread_id}:{text_digest}:{today}"
    project_id = thread.get("project_id")
    try:
        result = await notification_service.record(
            recipient_id=str(user_id),
            category=category,
            severity=severity,
            dedup_key=dedup_key,
            subject=subject,
            body=page_body,
            source_kind="thread",
            source_id=str(thread_id),
            action_params={
                "thread_id": str(thread_id),
                "project_id": str(project_id) if project_id else None,
            },
            payload={
                "thread_id": str(thread_id),
                "project_id": str(project_id) if project_id else None,
                "config_name": str(thread.get("config_name") or "session_base"),
                "title": thread.get("title"),
            },
        )
    except Exception:
        logger.warning(
            "officer notification for thread %s failed",
            str(thread_id)[:8],
            exc_info=True,
        )
        return None
    return result.notification_id


@app.post("/api/agents/threads/{thread_id}/officer/notify")
async def agent_officer_notify(
    request: Request,
    thread_id: str,
    body: OfficerNotifyRequest,
) -> dict[str, Any]:
    """The officer's notify_user contract (centurion.md §6). **Internal** —
    requires ``X-Internal-Key``; ingress strips this path.

    Three urgencies, each a feed row on the Legate's notification center
    (unified notification system):
      * ``log`` — no-op server-side: the officer's transcript already carries
        the line; this exists so the tool has an honest cheap tier.
      * ``digest`` — a ``low``-severity row: in-app only, read at the next
        look. The officer card lists these rows (feed filtered by source).
      * ``page`` — a ``high``-severity row: reaches the Legate now, through
        whatever channels their preferences allow. There is no per-officer
        page budget — the platform throttles (dedup per text per day,
        preferences, quiet hours), not the agent.
    """
    await require_internal(request)
    thread = await postgres_db.get_thread(thread_id)
    if thread is None:
        raise HTTPException(status_code=404, detail="Thread not found")
    officer_meta = _thread_officer_meta(thread)
    if not _officer_meta_enabled(officer_meta):
        raise HTTPException(status_code=409, detail="Thread is not an officer session")

    urgency = (body.urgency or "log").strip().lower()
    if urgency not in ("log", "digest", "page"):
        raise HTTPException(
            status_code=400, detail="urgency must be log, digest, or page"
        )
    message = (body.message or "").strip()
    if not message:
        raise HTTPException(status_code=400, detail="message must not be empty")

    if urgency == "log":
        return {"delivered": "log"}

    # A page is a `high` row (reaches the Legate now); a digest is a `low`
    # row (in-app, read at the next look). Throttling is the platform's job:
    # identical text on one day collapses onto one row (the dedup key), the
    # recipient's preferences and quiet hours apply per channel, and there is
    # no per-officer page budget any more.
    severity = "high" if urgency == "page" else "low"
    notification_id = await _dispatch_officer_page(
        thread,
        thread_id,
        body.subject,
        message,
        category="officer_question",
        severity=severity,
    )
    if notification_id is None:
        raise HTTPException(
            status_code=503,
            detail="The notification could not be recorded — try again",
        )
    return {"delivered": urgency, "notification_id": notification_id}


async def _apply_thread_config_update_locked(
    thread_id: str,
    thread_row: dict[str, Any] | None,
    config_override: dict[str, Any],
    datasource_ids: list[str] | None,
    *,
    request: Request,
    actor: dict[str, Any] | None,
) -> tuple[dict[str, Any], list[str] | None]:
    """Validate → authorize → enrich → persist a thread config change.

    Shared core of the internal live-session PATCH
    (``agent_update_thread_config``) and the owner-facing
    disconnected-session PATCH (live_session_settings.md Slice C) — the two
    callers differ only in auth, connection gating, and response redaction.
    Authorization (datasource selection + capability grants) is keyed to the
    THREAD OWNER in both cases, so an API caller can never exceed what the
    live pane allows.

    Returns ``(config_override, selected_datasource_ids)`` where the fragment
    is enriched with resolved model transport (``base_url``/``api_key`` +
    explicit ``None`` sentinels) — the internal caller returns it verbatim to
    the agent; browser-facing callers MUST redact it. Persistence is always
    redacted. Emits a ``session_config_updated`` security event on success
    (``actor`` is the resolved caller for owner-facing requests, None for
    internal ones — the recorded path distinguishes the two).
    """
    protected_marker = _protected_cloud_mutation_marker(thread_row)
    if protected_marker == "on" and {
        "workspace",
        "officer",
    }.intersection(config_override):
        # A protected session is safe only while its effective runtime remains
        # the supported Container/non-Officer class.  Generic live config
        # mutation is not an atomic protected-runtime transition protocol, so
        # reject both security-relevant blocks before grant resolution, audit,
        # or persistence.  Even a seemingly harmless partial/no-op block is
        # refused: defaults and expert inheritance make a fragment alone an
        # insufficient proof of the resulting class.
        raise HTTPException(
            status_code=409,
            detail={
                "code": "protected_cloud_runtime_class_fixed",
                "message": (
                    "Protected cloud sessions cannot change workspace tier or "
                    "Officer mode."
                ),
            },
        )
    if "officer" in config_override and thread_row and thread_row.get("project_id"):
        post = await postgres_db.get_project_officer(str(thread_row["project_id"]))
        if post and str(post.get("thread_id") or "") == str(thread_id):
            raise HTTPException(
                status_code=409,
                detail=(
                    "The commissioned officer block is owned by the Officer "
                    "Post; use the project Officer Post endpoint so durable "
                    "and runtime configuration change atomically."
                ),
            )
    if thread_row and thread_row.get("execution_lane") == "stateless":
        # Generic config mutation is not the workspace-upgrade protocol. Refuse
        # an already-drifted row and allow only same-tier workspace tuning.
        current_backend = _require_stateless_workspace(thread_row)
        if "officer" in config_override:
            # Runtime PATCH historically accepted this block without the
            # create-time validator. Normalize booleans and reject unknown
            # fields before evaluating the proposed immutable session class.
            normalized_officer = _validated_session_officer_override(config_override)
            config_override["officer"] = normalized_officer or {}

        metadata = thread_metadata_object(thread_row)
        persisted_override = metadata.get("config_override") or {}
        if not isinstance(persisted_override, dict):
            persisted_override = {}
        proposed_override = _deep_merge_dicts(
            persisted_override,
            config_override,
        )
        class_refusal = _stateless_session_class_refusal(proposed_override)
        if class_refusal is not None:
            # Creation materializes the fully resolved class booleans into the
            # request layer, so this merge is authoritative even if the expert
            # or account default changes later. Never persist a fragment that
            # would move a live queue-served thread onto pinned-only wake
            # machinery without an atomic lane-transition protocol.
            raise HTTPException(
                status_code=409,
                detail=(
                    "A stateless session cannot enable pinned-only lifecycle "
                    f"behavior ({class_refusal})"
                ),
            )
        if "workspace" in config_override:
            workspace_patch = config_override.get("workspace")
            if not isinstance(workspace_patch, dict) or (
                "backend" in workspace_patch
                and workspace_patch.get("backend") != current_backend
            ):
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "A stateless session cannot change its workspace tier "
                        "through generic config mutation"
                    ),
                )

    if "tools" in config_override:
        # Runtime updates use the same registry vocabulary as session creation
        # and job creation.  A fragment this boundary will not honour is a 400
        # from here, not a silent discard: the previous closed-group filter
        # replaced `tools` with the four accepted groups and dropped the rest,
        # so a live "turn research off" was acknowledged and never applied.
        # The names are also checked against their own category, because the
        # loader resolves a name against the global registry rather than the
        # key it arrived under.
        accepted_tools = _validated_tool_overrides(config_override)
        if accepted_tools:
            config_override["tools"] = accepted_tools
        else:
            # `tools: {}` only — it asks for nothing, so there is nothing to
            # honour and nothing to report as changed.
            config_override.pop("tools", None)

    if "delegation" in config_override:
        # The gate half of the Delegation toggle (see create_thread). Same
        # validator as create, so the two write paths cannot disagree about
        # what the block means; malformed is a 400, never a silent drop.
        from orchestrator.services.session_create_overrides import (
            SessionOverrideError,
            validate_delegation_override,
        )

        try:
            accepted_delegation = validate_delegation_override(
                config_override["delegation"]
            )
        except SessionOverrideError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        if accepted_delegation:
            config_override["delegation"] = accepted_delegation
        else:
            config_override.pop("delegation", None)

    # Audit summary is computed PRE-enrichment so it names only the keys the
    # caller actually sent (enrichment adds llm.api_key/base_url internally).
    change_summary = _config_change_summary(config_override, datasource_ids)

    # Live datasource change (live_session_settings.md Slice B): authorize
    # the requested full selection exactly like create does — including the
    # lite-tier/repository rule against the thread's CURRENT workspace
    # backend (a live add is create-like; only the attach-time
    # revalidation deliberately passes None) — then fold the resulting
    # datasource tool-category flip into the grant-checked fragment so a
    # datasource_tools-denied principal fails HERE at the PATCH, not at
    # the next attach.
    selected_ds_ids: list[str] | None = None
    selected_ds_revisions: dict[str, int] | None = None
    datasource_selection_provenance: dict[str, Any] | None = None
    grant_fragment = config_override
    if datasource_ids is not None:
        if thread_row is None:
            raise HTTPException(status_code=404, detail="Thread not found")
        requested_ids = [str(v) for v in datasource_ids]
        current_metadata = thread_metadata_object(thread_row)
        try:
            canonical_requested = {str(UUID(value)) for value in requested_ids}
        except (TypeError, ValueError) as exc:
            raise HTTPException(
                status_code=403,
                detail="One or more selected connectors are unavailable",
            ) from exc
        removed_ids = (
            set(current_metadata.get("datasource_ids") or []) - canonical_requested
        )
        if removed_ids:
            removed_rows = await postgres_db.get_datasource_policy_rows(
                list(removed_ids)
            )
            if any(row.get("type") == "credentials" for row in removed_rows):
                raise HTTPException(
                    status_code=409,
                    detail="Credential connectors stay attached for the lifetime of the session",
                )
        target_project_ids = await _thread_project_ids(thread_id)
        if thread_row.get("user_id"):
            owner = await postgres_db.get_user(str(thread_row["user_id"]))
            if owner is None:
                # Same generic denial as create — no enumeration oracle.
                raise HTTPException(
                    status_code=403,
                    detail="One or more selected connectors are unavailable",
                )
            (
                selected_ds_ids,
                selected_ds_revisions,
            ) = await _authorize_thread_datasource_selection(
                owner,
                requested_ids,
                workspace_backend=_thread_workspace_backend(thread_row),
                target_project_ids=target_project_ids,
                effective_work_owner_id=str(thread_row["user_id"]),
            )
        else:
            # Ownerless/system threads have no ambient authority. A live edit
            # may narrow or preserve the already-materialized set, but cannot
            # use the trusted-inheritance seam to add an arbitrary UUID.
            metadata = thread_row.get("metadata") or {}
            if isinstance(metadata, str):
                try:
                    metadata = json.loads(metadata)
                except (json.JSONDecodeError, TypeError):
                    metadata = {}
            persisted_ids = (
                metadata.get("datasource_ids") if isinstance(metadata, dict) else []
            ) or []
            try:
                requested_set = {str(UUID(str(value))) for value in requested_ids}
                persisted_set = {str(UUID(str(value))) for value in persisted_ids}
            except (TypeError, ValueError) as exc:
                raise HTTPException(
                    status_code=403,
                    detail="One or more selected connectors are unavailable",
                ) from exc
            if not requested_set.issubset(persisted_set):
                raise HTTPException(
                    status_code=403,
                    detail="One or more selected connectors are unavailable",
                )
            (
                selected_ds_ids,
                selected_ds_revisions,
            ) = await _authorize_thread_datasource_selection(
                None,
                requested_ids,
                workspace_backend=_thread_workspace_backend(thread_row),
                target_project_ids=target_project_ids,
                trusted_system_inheritance=True,
            )

        resolved_ds = await postgres_db.resolve_datasources_for_thread(
            datasource_ids=selected_ds_ids,
            project_ids=target_project_ids,
        )
        flip = _build_datasource_tool_override(resolved_ds, None)
        # THE FLIP WINS, and the order is load-bearing. It used to be the other
        # way round, safe only because the request's tools were filtered down
        # to four non-connector groups first. Now that every category is
        # honoured, a request could send `tools.sql: []` and mask a
        # datasource_tools violation from the PDP below — while attach applies
        # the flip LAST anyway (_build_datasource_tool_override updates the
        # request's tools with the datasource categories), so the session would
        # get connector tools the grant check never saw. Modelling attach
        # exactly is what keeps this fragment honest.
        grant_fragment = {
            **config_override,
            "tools": {
                **(config_override.get("tools") or {}),
                **flip.get("tools", {}),
            },
        }
        datasource_selection_provenance = await _datasource_selection_provenance(
            datasource_ids=selected_ds_ids,
            policy_revisions=selected_ds_revisions,
            origin="explicit",
            effective_work_owner_id=(
                str(thread_row["user_id"]) if thread_row.get("user_id") else None
            ),
            actor=actor,
            project_ids=target_project_ids,
            creation_path=(
                "live_thread_internal" if actor is None else "live_thread_rest"
            ),
        )

    # Layer 2 (fail loud): a runtime config change must also fit the owner's
    # grants — reject a denied permission_mode/model with 422 instead of
    # persisting a config the session can't run (an API-direct or stale-UI
    # escalation past the user's ceiling; the cockpit greys these out
    # client-side). Ownerless/standalone threads (user_id NULL) aren't
    # subject to a user's grants — skip. Admin owner bypasses.
    # knowledge-base/knowledge/issues/session_permission_mode_grant_denied_ready_timeout.md
    if thread_row and thread_row.get("user_id"):
        await _enforce_session_create_grants(
            grant_fragment,
            user_id=str(thread_row["user_id"]),
            project_ids=(
                [str(thread_row["project_id"])] if thread_row.get("project_id") else []
            ),
        )

    # Enrich endpoint-backed model swaps with base_url + api_key so the
    # persisted override is complete. Without this, a hot-swap to a
    # custom-endpoint model leaves the next session attach pointing at
    # the default OpenAI base.
    llm_section = config_override.get("llm")
    if llm_section and llm_section.get("model"):
        if thread_row:
            user_id = str(thread_row["user_id"]) if thread_row.get("user_id") else None
            project_id = (
                str(thread_row["project_id"]) if thread_row.get("project_id") else None
            )
            resolved_keys = await postgres_db.resolve_api_keys_for_job(
                user_id=user_id, project_id=project_id
            )
            llm_section = dict(llm_section)
            await _inject_model_credentials(
                section=llm_section,
                model_id=llm_section["model"],
                user_id=user_id,
                resolved_keys=resolved_keys,
            )
            # A model swap must fully determine its transport. Any field
            # resolution didn't set becomes an explicit None so the
            # agent-side deep_merge CLEARS the previous model's value
            # instead of inheriting it (e.g. swapping off an
            # endpoint-backed model must not keep its base_url).
            for transport_key in ("provider", "base_url", "api_key"):
                llm_section.setdefault(transport_key, None)
            config_override["llm"] = llm_section

    # Persist WITHOUT secrets — the agent rebuilds its LLM from the enriched
    # dict returned below, and resume re-injects from source. The explicit
    # None transport sentinels stay in the stored copy so the deep-merge
    # clears the previous model's transport; resume re-injection treats them
    # as absent (see _inject_thread_dispatch_credentials).
    ok = await postgres_db.merge_thread_config_override(
        thread_id, redact_config_override(config_override)
    )
    if not ok:
        raise HTTPException(status_code=404, detail="Thread not found")

    # Persist the accepted selection only after every check above passed.
    # The category flip is NOT merged into config_override — the closed
    # session tools vocabulary would drop it anyway; the agent re-fetches
    # GET /api/agents/threads/{id}/workspace and applies the categories
    # directly to its live session config, and every attach path re-derives
    # them from metadata.datasource_ids.
    if selected_ds_ids is not None:
        from shared.credential_connectors import CredentialConnectorAttachedError

        try:
            updated = await postgres_db.set_thread_datasource_ids(
                thread_id,
                selected_ds_ids,
                datasource_policy_revisions=selected_ds_revisions,
                datasource_selection_provenance=datasource_selection_provenance,
            )
        except CredentialConnectorAttachedError as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc
        except DatasourcePolicyConflictError as exc:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Connector policy changed while updating the session; "
                    "retry the request"
                ),
            ) from exc
        if not updated:
            raise HTTPException(status_code=404, detail="Thread not found")

    # Config-change audit (live_session_settings.md Slice C): key paths only,
    # fired after every persist step succeeded. log_security_event never
    # raises, so a broken audit trail can't fail the update it documents.
    await log_security_event(
        postgres_db,
        resource_type="thread",
        event_type="session_config_updated",
        user=actor,
        resource_id=thread_id,
        detail=change_summary,
        request=request,
    )
    if selected_ds_ids is not None:
        # The snapshot policy and pinned merge use the same authorized derived
        # categories. Persisted author overrides still omit this live binding.
        config_override = {
            **config_override,
            "tools": grant_fragment.get("tools", {}),
        }
    return config_override, selected_ds_ids


# =============================================================================
# Persistent Agent — Thread CRUD + WebSocket Proxy
# =============================================================================


@app.get("/api/persistent/threads/{thread_id}")
async def get_thread(thread_id: str, request: Request) -> dict[str, Any]:
    """Get thread status and metadata (auth: owner only).

    Phase 1 of cloud_collaboration_model.md §9 surfaces the thread's
    attached mounts here so the Cockpit "Project files" panel can render
    them without a second round-trip. ``project_ids`` is the derived
    list-of-strings view kept stable for callers that only need scoping.

    Threads created before migration 0202 have ``ssh_handle IS NULL``; mint
    one lazily here on first view rather than showing an empty SSH panel
    forever. Deliberately not done on the list endpoint — minting up to 50
    handles as a side effect of rendering a list is unwanted write
    amplification.

    The mint is guarded (M-1): it's a write on an otherwise read-only view,
    so a write failure here (a read-only replica, a full disk — this
    deployment has actually had one) must not turn the whole thread view
    into a 500 for the sake of one SSH-panel field. Caught broadly since
    ``ensure_thread_ssh_handle`` can raise asyncpg errors or its own
    exhausted-retries ``RuntimeError``; either way the response degrades to
    a null handle (the panel already renders "unavailable" for that).
    """
    user, thread = await require_thread_owner(request, postgres_db, thread_id)
    result = _redact_thread_metadata(dict(thread))
    if not result.get("ssh_handle"):
        try:
            result["ssh_handle"] = await postgres_db.ensure_thread_ssh_handle(thread_id)
        except Exception:
            logger.warning(
                "ensure_thread_ssh_handle failed for thread %s (non-fatal)",
                str(thread_id)[:8],
                exc_info=True,
            )
    mounts = await postgres_db.list_thread_mounts(thread_id)
    result["cloud_session_url"] = _resolve_cloud_session_url(thread, mounts)
    result["mounts"] = [
        {
            "id": str(m["id"]),
            "mount_kind": m["mount_kind"],
            "target_path": m["target_path"],
            "source_kind": m["source_kind"],
            "source_ref": str(m["source_ref"]) if m.get("source_ref") else None,
            "backend_id": m.get("backend_id"),
        }
        for m in mounts
    ]
    result["project_ids"] = [
        str(m["source_ref"])
        for m in mounts
        if m.get("mount_kind") == "project" and m.get("source_ref")
    ]
    return result


@app.get("/api/persistent/threads/{thread_id}/state")
async def get_thread_session_state(
    thread_id: str, request: Request, response: Response
) -> dict[str, Any]:
    """Lane-agnostic, owner-gated current state for a session Cockpit.

    This is the REST twin of the agent's direct ``session.state`` welcome
    frame.  It intentionally reads durable state for *both* execution lanes;
    no lane or pod identity crosses the wire.  Journal-derived fields are
    point-in-time values at ``event_cursor``.  A client must apply the snapshot
    before replaying the journal from ``replay_cursor`` so the latest logical
    turn is rebuilt before any not-yet-flushed agent edge advances it.
    """

    started = time.perf_counter()
    _user, _thread = await require_thread_owner(request, postgres_db, thread_id)
    auth_done = time.perf_counter()

    # Model/temperature/narration are not all first-class thread columns yet.
    # Resolve from the exact thread row captured inside the snapshot's
    # repeatable-read transaction. A later config write then lands above the
    # returned event cursor and SSE replays it, instead of the cursor hiding a
    # scalar resolved from a different metadata revision.
    config_seconds = 0.0

    async def _resolve_snapshot_config(
        snapshot_thread: dict[str, Any], snapshot_metadata: dict[str, Any]
    ) -> dict[str, Any] | None:
        nonlocal config_seconds
        config_started = time.perf_counter()
        try:
            return await _resolve_session_config(snapshot_thread, snapshot_metadata)
        except GrantDenied:
            logger.warning(
                "Session-state config resolve denied for thread %s; using stored "
                "display fields",
                thread_id,
            )
            return None
        finally:
            config_seconds += time.perf_counter() - config_started

    snapshot = await build_session_state_snapshot(
        postgres_db,
        thread_id,
        config_resolver=_resolve_snapshot_config,
    )
    if snapshot is None:
        raise HTTPException(status_code=404, detail="Thread not found")
    # Pending permissions include tool arguments. Never let a browser or an
    # intermediary retain one user's current control state for another read.
    response.headers["Cache-Control"] = "private, no-store"
    finished = time.perf_counter()
    logger.info(
        "session-state timing: thread=%s auth=%.3fs config=%.3fs "
        "snapshot=%.3fs total=%.3fs",
        thread_id,
        auth_done - started,
        config_seconds,
        max(0.0, finished - auth_done - config_seconds),
        finished - started,
    )
    return snapshot


class ThreadControlRequest(BaseModel):
    """Strict public envelope for the durable control-inbox subset."""

    client_request_id: UUID
    method: Literal["mode.set", "narration.set", "workspace.undo"]
    session_runtime_generation: UUID | None = Field(
        None,
        description=(
            "Runtime generation rendered with the current session. Pinned "
            "admission compares it under the thread-row lock."
        ),
    )
    mode: (
        Literal[
            "supervised",
            "auto_accept",
            "autonomous",
            "silent",
            "verbose",
            "auto",
        ]
        | None
    ) = None

    @model_validator(mode="after")
    def validate_method_mode_pair(self) -> "ThreadControlRequest":
        permission_modes = {"supervised", "auto_accept", "autonomous"}
        narration_modes = {"silent", "verbose", "auto"}
        if self.method == "mode.set" and self.mode not in permission_modes:
            raise ValueError("mode.set requires a permission mode")
        if self.method == "narration.set" and self.mode not in narration_modes:
            raise ValueError("narration.set requires a narration mode")
        if self.method == "workspace.undo" and self.mode is not None:
            raise ValueError("workspace.undo does not accept a mode")
        return self

    def control_payload(self) -> dict[str, Any]:
        """Canonical payload used for idempotency and durable admission."""

        return {} if self.method == "workspace.undo" else {"mode": self.mode}


@app.post(
    "/api/persistent/threads/{thread_id}/controls",
    status_code=202,
)
async def submit_thread_control(
    thread_id: str,
    body: ThreadControlRequest,
    request: Request,
) -> dict[str, Any]:
    """Admit an owner-authorized control for the exact serving owner.

    This endpoint serves both execution lanes and deliberately exposes neither
    one. It persists a commit-ordered request, but neither the desired scalar
    nor a journal frame: the current lease owner (or exact reciprocal pinned
    binding) applies the request and journals the result with its own allocator.
    """
    from shared.run_queue import LANE_STATELESS

    started = time.perf_counter()
    user, thread = await require_thread_owner(request, postgres_db, thread_id)
    thread_owner_id = thread.get("user_id")
    policy_user_id = str(thread_owner_id or user["id"])
    control_payload = body.control_payload()
    control_metadata = thread_metadata_object(thread)
    require_control_generation = bool(
        thread.get("execution_lane") == "pinned"
        and (
            protected_cloud_marker_state(control_metadata) != "off"
            or _require_pinned_status_identity()
        )
    )

    try:
        existing = await find_existing_thread_control(
            postgres_db,
            thread_id=thread_id,
            owner_user_id=thread_owner_id,
            client_request_id=body.client_request_id,
            verb=body.method,
            payload=control_payload,
        )
    except ControlAdmissionError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc

    # A new stateless control can create a control-only queue claim just like
    # human input. Refuse unsupported workspace bindings before that durable
    # admission can wake an executor. Exact idempotent retries remain observable
    # even if the thread's lane/tier changed after their commit.
    if existing is None and thread.get("execution_lane") == LANE_STATELESS:
        _require_stateless_workspace(thread)

    if body.method == "mode.set" and existing is None:
        # Same PDP as create/attach/config.update. A stale or direct client
        # cannot persist a permission mode above the owner's current ceiling.
        # A retry of an already committed UUID bypasses mutable policy: a lost
        # 202 must stay observable even if grants changed afterward.
        try:
            await _enforce_session_create_grants(
                {"interactive": {"permission_mode": body.mode}},
                user_id=policy_user_id,
                project_ids=(
                    [str(thread["project_id"])] if thread.get("project_id") else []
                ),
            )
        except HTTPException:
            # Close the concurrent masked-commit race between the preflight
            # and PDP without weakening authorization for a genuinely new id.
            try:
                existing = await find_existing_thread_control(
                    postgres_db,
                    thread_id=thread_id,
                    owner_user_id=thread_owner_id,
                    client_request_id=body.client_request_id,
                    verb=body.method,
                    payload=control_payload,
                )
            except ControlAdmissionError as exc:
                raise HTTPException(status_code=409, detail=str(exc)) from exc
            if existing is None:
                raise

    actor_id = str(user.get("id") or user.get("sub") or "rest_client")
    try:
        admitted = await admit_thread_control(
            postgres_db,
            thread_id=thread_id,
            owner_user_id=thread_owner_id,
            client_request_id=body.client_request_id,
            verb=body.method,
            payload=control_payload,
            requested_by=actor_id,
            expected_runtime_generation=body.session_runtime_generation,
            require_pinned_runtime_generation=require_control_generation,
        )
    except ControlAdmissionNotReady as exc:
        # Registration intentionally keeps the exact pinned-owner capability
        # closed until its writer and first inbox drain are ready.  A control
        # clicked during that window is not a semantic conflict: 425 tells the
        # lane-free client to retry the same UUID after its bounded backoff.
        raise HTTPException(status_code=425, detail=str(exc)) from exc
    except ControlAdmissionError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc

    await log_security_event(
        postgres_db,
        resource_type="thread",
        event_type="session_control_requested",
        user=user,
        resource_id=thread_id,
        detail=f"verb={body.method} request_seq={admitted.request_seq}",
        request=request,
    )
    logger.info(
        "session-control admission: thread=%s verb=%s seq=%d duplicate=%s total=%.3fs",
        thread_id,
        body.method,
        admitted.request_seq,
        admitted.duplicate,
        time.perf_counter() - started,
    )
    return {
        "accepted": True,
        "request_id": str(admitted.id),
        "client_request_id": str(admitted.client_request_id),
        "request_seq": admitted.request_seq,
        "method": admitted.verb,
        "state": admitted.state,
        "duplicate": admitted.duplicate,
        "session_runtime_generation": (
            str(admitted.runtime_generation)
            if admitted.runtime_generation is not None
            else None
        ),
    }


async def _session_tool_grants(thread: dict[str, Any]) -> dict[str, Any] | None:
    """The owner's capability grants, for explaining an ``unavailable``.

    ``None`` means "impose no grant-based restriction" — both for an admin
    (``_resolve_runner_grants`` returns ``None``) and for a lookup failure. A
    read surface must never INVENT a denial: the PDP at attach and dispatch is
    the enforcement, this is only the explanation, and a fabricated
    "unavailable — needs the shell_tools grant" is its own D1 violation.
    """
    try:
        project_ids = [str(thread["project_id"])] if thread.get("project_id") else []
        return await _resolve_runner_grants(
            runner_user_id=str(thread.get("user_id"))
            if thread.get("user_id")
            else None,
            project_ids=project_ids,
        )
    except Exception:
        logger.warning(
            "Tool-group grant lookup failed for thread %s; reporting no "
            "grant-based restrictions",
            thread.get("id"),
        )
        return None


@app.get("/api/persistent/threads/{thread_id}/tool-groups")
async def get_thread_tool_groups(thread_id: str, request: Request) -> dict[str, Any]:
    """What toolset does this session's agent actually have? (auth: owner)

    D6: **the answer comes from the agent.** The orchestrator asks the bound
    pod what it bound and serves that; it does not recompute it. Only the agent
    sees the runtime injection layer (``persistent_session._load_tools_for_backend``
    appends the session-task trio, the product guide, the fleet/catalog/workflow
    lists, ``srw_cloud_status``, the officer pair, the datasource categories),
    ``filter_tools_by_backend``, and ``load_tools``'s per-tool fallback. A
    config-only view over-reports by dozens of names, and the divergence
    between two implementations of one fact is the original bug here.

    ``origin`` is the field that matters, and callers MUST branch on it:

    - ``agent`` — **measured, in full**. A running pod enumerated its bound
      tools and returned the structured report. ``observed_at`` and ``backend``
      are set.
    - ``agent_partial`` — **measured, names only**. The pod answered but its
      image predates ``GET /session/toolset``, so the bound names come from
      ``/status`` with no timestamp, no workspace capabilities and no
      agent-side categorisation. ``degraded_reason`` says so. The names are as
      trustworthy as ``agent``; do NOT render a workspace-tier explanation from
      this answer, and do NOT infer measured-ness from ``observed_at``, which
      is legitimately null here.
    - ``prediction`` — **forecast** from the merged config, because there is no
      agent to ask (a new session, a suspended one, an unreachable pod).
      ``prediction_reason`` says which. Structurally weaker, not merely older:
      it cannot see the three layers listed above. Rendering it as fact is D1
      violated at a new seam.

    ``categories`` answers for ALL of them (25, ``mcp`` included), each with
    ``state`` (``on``/``off``/``unavailable``), ``reason`` when not settable,
    ``settable``, ``decided_by`` (the layer that produced the answer) and
    ``tools``. Measured entries also carry ``configured``, so a caller can see
    the merge and the measurement disagree instead of having to trust one.

    ``off`` is a promise that ticking the box would work, and it is only made
    when it can be kept: on a measurement, a category whose merged config
    grants tools while the agent bound none is ``unavailable``. See
    ``compose_tool_view``.

    ``source`` is unchanged and still describes the PREDICTION's model —
    ``resolved`` / ``legacy`` / ``error``. It says nothing about ``origin``:
    a measured answer is a measured answer whichever path the config took.

    ``tool_groups`` (the closed groups, booleans) is retained for the
    cockpit and is now DERIVED from ``categories`` rather than computed beside
    it, so the endpoint cannot disagree with itself.

    ``enumerate_only`` answers the *write* half of the same question: which
    categories refuse ``tools.<c>: true`` at the write boundary, and the
    registry-derived enumeration a caller must send instead
    (``{"shell": ["cancel_command", ...]}``). Without it the only way for the
    New Session form to offer "shell on" would be a hand-maintained tool-name
    list in the cockpit — a fifth parallel list, in the change that deletes
    four. See :func:`src.core.tool_policy.enumerate_only_members`.

    Deliberately NOT a field on ``GET /api/persistent/threads/{id}``: that
    endpoint is hot and this answer costs a config resolve plus a pod probe.
    """
    user, thread = await require_thread_owner(request, postgres_db, thread_id)
    metadata = thread.get("metadata") or {}
    if isinstance(metadata, str):
        try:
            metadata = json.loads(metadata)
        except (json.JSONDecodeError, TypeError):
            metadata = {}
    request_override = metadata.get("config_override") or None

    base = canonical_config_name(thread.get("config_name") or "session_base")
    if _looks_like_uuid(base):
        # Sentinel / cockpit-conflated expert UUID → the real session base.
        base = "session_base"

    m = await _agent_toolset_measurement(thread)
    grants = await _session_tool_grants(thread)

    from shared.runtime.core.subagent_roster import roster_summary

    source = "resolved"
    configured: dict[str, Any] = {}
    provenance: dict[str, str] = {}
    # What a Delegation tick reaches: the expert's materialised roster, or an
    # empty one the pane can name as such. None only when the resolve failed.
    roster: dict[str, Any] | None = None

    if not _is_experts_db_enabled() or not await _user_experts_enabled():
        source = "legacy"
        configured, provenance = await asyncio.to_thread(
            _legacy_session_tool_policy, base, request_override
        )
        # The legacy path merges a public base only; none carries a roster.
        roster = roster_summary(None)
    else:
        try:
            expert_id = metadata.get("expert_id")
            expert_row = (
                await postgres_db.get_expert_by_id(str(expert_id))
                if expert_id
                else None
            )
            project_id = str(thread["project_id"]) if thread.get("project_id") else None
            project_overrides = None
            if project_id and expert_id:
                link = await postgres_db.get_project_expert_link(
                    project_id=project_id, expert_id=str(expert_id)
                )
                if link:
                    project_overrides = link.get("config_override") or None
                    if isinstance(project_overrides, str):
                        project_overrides = json.loads(project_overrides)
            # Owner-correct, same as _session_tool_grants below: an admin
            # viewing another user's thread must see THAT owner's
            # acknowledged grants, not their own (see _acknowledged_grant_strip
            # and the resume-time owner-vs-caller fix it mirrors).
            grant_strip = await _acknowledged_grant_strip(
                metadata,
                user_id=str(thread["user_id"]) if thread.get("user_id") else None,
                project_id=project_id,
            )
            # The same roster rows the attach prefetches: a DB `$ref` entry
            # the resolve cannot see is dropped, and the pane would then
            # report a roster the agent does bind as missing.
            db_refs = await _prefetch_roster_refs(
                expert_row=expert_row,
                overrides=[project_overrides, request_override],
                user_id=str(thread["user_id"]) if thread.get("user_id") else None,
                project_ids=[project_id] if project_id else [],
            )
            capture: dict[str, Any] = {}
            configured, provenance = await asyncio.to_thread(
                _merged_session_tool_policy,
                base_config_name=base,
                expert_row=expert_row,
                project_overrides=project_overrides,
                request_override=request_override,
                grant_strip=grant_strip,
                db_refs=db_refs,
                capture=capture,
            )
            roster = roster_summary(
                (capture.get("merged_fragment") or {}).get("subagents")
            )
        except Exception:
            logger.exception("Tool-group resolve failed for thread %s", thread_id)
            source = "error"
            if m.categories is None:
                # No measurement AND no resolve: there is nothing honest to
                # report. A resolve error REFUSES the attach (fail closed), so
                # there is no agent answer either.
                return {
                    "thread_id": thread_id,
                    "source": "error",
                    **_origin_fields(m),
                    "tool_groups": None,
                    "categories": None,
                    "subagents": None,
                }

    # Only a MEASURED answer carries backend capabilities: they come from the
    # agent's own report. A prediction has no provisioned workspace to inspect,
    # which is one of the three reasons it over-reports (the live gate saw it
    # over-report by 14 execution tools on a no-shell tier).
    view = compose_tool_view(
        measured=m.categories,
        configured=configured,
        provenance=provenance,
        backend_caps=m.backend,
        grants=grants,
    )
    return {
        "thread_id": thread_id,
        "source": source,
        **_origin_fields(m),
        "enumerate_only": enumerate_only_members(),
        "tool_groups": tool_groups_from_view(view),
        "categories": view,
        "subagents": roster,
    }


class ToolGroupPreviewRequest(BaseModel):
    """What would a session or job created with THIS config bind? (a prediction)"""

    config_name: Optional[str] = None
    expert_id: Optional[str] = None
    project_id: Optional[str] = None
    config_override: Optional[dict[str, Any]] = None
    workspace: Optional[dict[str, Any]] = None
    workspace_preference: Literal["none", "virtual", "sandbox", "vm"] | None = None
    #: Which surface is asking. ``worker`` is the job-create form and defaults
    #: the base to ``worker_base``; ``session`` is the New Session form. Default
    #: stays ``session`` so the shipped cockpit's payloads keep their meaning.
    expert_type: Literal["worker", "session"] = "session"


@app.post("/api/persistent/tool-groups/preview")
async def preview_tool_groups(
    body: ToolGroupPreviewRequest, request: Request
) -> dict[str, Any]:
    """The New Session form's read. **Always a prediction, by construction.**

    There is no agent yet, so this endpoint can never return ``origin:
    "agent"`` — and that is the point of it being a separate route rather than
    a mode of the thread endpoint. D6's consequence is that the creation form
    forecasts while the live pane measures; making the difference structural
    (two routes, one of which cannot ever say "measured") is cheaper to keep
    honest than a flag someone forgets to read.

    ``source`` models the same three agent paths as the thread endpoint and is
    NOT hardcoded: with the experts feature or the per-user kill switch off, a
    created session takes the legacy path, where the compatibility groups are
    APPENDED unless explicitly disabled — the opposite of the resolved path for
    an unset group. Predicting "off" and labelling it ``resolved`` on such a
    deployment would be this series' own defect, rebuilt in the form that
    predicts it.

    Same ``categories`` shape as the thread endpoint, so one renderer serves
    both surfaces.
    """
    user = await require_approved_user(request, postgres_db)
    is_worker = body.expert_type == "worker"
    default_base = "worker_base" if is_worker else "session_base"
    base = canonical_config_name(body.config_name or default_base)
    if _looks_like_uuid(base):
        base = default_base

    expert_row = None
    project_overrides = None
    legacy = not _is_experts_db_enabled() or not await _user_experts_enabled()
    try:
        if body.expert_id and not legacy:
            expert_row = await postgres_db.get_expert_by_id(str(body.expert_id))
            if body.project_id:
                link = await postgres_db.get_project_expert_link(
                    project_id=str(body.project_id), expert_id=str(body.expert_id)
                )
                if link:
                    project_overrides = link.get("config_override") or None
                    if isinstance(project_overrides, str):
                        project_overrides = json.loads(project_overrides)
    except Exception:
        logger.warning("Tool-group preview could not load the expert/project layer")

    from orchestrator.services.manifest_workspace_selection import (
        select_execution_workspace,
    )
    from shared.runtime.core.workspace_selection import bind_execution_workspace

    account = (
        await _resolve_session_account_defaults(str(user["id"]))
        if not is_worker
        else {}
    )
    workspace_config, workspace_selection = await select_execution_workspace(
        postgres_db,
        user,
        project_id=body.project_id,
        role=body.expert_type,
        workspace=body.workspace,
        supplied="workspace" in body.model_fields_set,
        config_override=body.config_override,
        account_defaults=account,
        request=request,
    )
    workspace_source = (
        "project"
        if workspace_selection and workspace_selection.get("project_revision")
        else "request"
        if "workspace" in body.model_fields_set
        or "backend" in ((body.config_override or {}).get("workspace") or {})
        else "default"
    )
    # A creation client can ask to preview its proposed recommendation. It must
    # materialize that choice in the submitted execution; admission never reads it.
    if workspace_source == "default" and body.workspace_preference is not None:
        workspace_config["backend"] = body.workspace_preference
        workspace_source = "recommendation"
    preview_override = bind_execution_workspace(
        body.config_override or {}, workspace_config
    )
    preview_workspace = {
        "backend": workspace_config["backend"],
        "source": workspace_source,
        "binding": workspace_selection["document"]
        if workspace_selection
        else (
            None
            if workspace_config["backend"] == "none"
            else {"template": {"inline": {"backend": workspace_config["backend"]}}}
        ),
    }

    # The legacy branch models ONE agent's behaviour: persistent_session's
    # re-adding of the closed group lists when no disable marker is present.
    # Worker jobs have no such step, so on the worker surface "experts off" only
    # means there is no expert layer to merge — the resolved path already answers
    # that correctly. Routing a worker preview through the session legacy policy
    # would predict appended session groups for a job that cannot hold them.
    use_legacy = legacy and not is_worker
    from shared.runtime.core.subagent_roster import roster_summary

    roster: dict[str, Any] = roster_summary(None)
    try:
        if use_legacy:
            configured, provenance = await asyncio.to_thread(
                _legacy_session_tool_policy, base, preview_override
            )
        else:
            # No grant_strip here: this is a not-yet-created session, so
            # there is no thread and no metadata.config_drift_ack to have
            # acknowledged anything against — unlike the thread endpoint
            # above, omitting it is not a gap to close, it is the correct
            # answer for a config that cannot yet have drifted.
            db_refs = await _prefetch_roster_refs(
                expert_row=expert_row,
                overrides=[project_overrides, body.config_override],
                user_id=str(user["id"]),
                project_ids=[str(body.project_id)] if body.project_id else [],
            )
            capture: dict[str, Any] = {}
            configured, provenance = await asyncio.to_thread(
                _merged_session_tool_policy,
                base_config_name=base,
                expert_row=expert_row,
                project_overrides=project_overrides,
                request_override=preview_override,
                expert_type=body.expert_type,
                db_refs=db_refs,
                capture=capture,
            )
            roster = roster_summary(
                (capture.get("merged_fragment") or {}).get("subagents")
            )
    except Exception:
        logger.exception("Tool-group preview resolve failed")
        raise HTTPException(
            status_code=422,
            detail="This configuration cannot be resolved, so its toolset "
            "cannot be predicted.",
        )

    try:
        grants = await _resolve_runner_grants(
            runner_user_id=str(user["id"]),
            project_ids=[str(body.project_id)] if body.project_id else [],
        )
    except Exception:
        logger.warning("Tool-group preview grant lookup failed")
        grants = None

    view = compose_tool_view(
        measured=None,
        configured=configured,
        provenance=provenance,
        backend_caps={
            "supports_shell": workspace_config["backend"] in ("sandbox", "vm"),
            "supports_file_tools": workspace_config["backend"] != "none",
            "supports_canvas_presentation": workspace_config["backend"] != "none",
        },
        grants=grants,
    )
    return {
        "workspace": preview_workspace,
        "source": "legacy" if use_legacy else "resolved",
        **_origin_fields(
            _unmeasured(
                "no agent exists for an unsaved job"
                if is_worker
                else "no agent exists for an unsaved session"
            )
        ),
        "enumerate_only": enumerate_only_members(),
        "tool_groups": tool_groups_from_view(view),
        "categories": view,
        "subagents": roster,
    }


@app.patch("/api/persistent/threads/{thread_id}")
async def update_thread(
    thread_id: str, body: ThreadUpdateRequest, request: Request
) -> dict[str, str]:
    """Rename a persistent thread (auth: owner only).

    The title was previously settable only at creation and auto-generated
    once by the LLM after the first turn; this lets the user rename a session
    inline from the Cockpit. A user-chosen title naturally blocks the
    auto-titler, which only overwrites empty / "Untitled Session" / "Local
    Session" titles (src/api/persistent_app.py).
    """
    user, thread = await require_thread_owner(request, postgres_db, thread_id)
    title = (body.title or "").strip()
    if not title:
        raise HTTPException(status_code=400, detail="Title cannot be empty")
    if len(title) > 200:
        raise HTTPException(status_code=400, detail="Title too long (max 200)")
    await postgres_db.update_thread_title(thread_id, title)
    return {"status": "updated", "title": title}


async def _thread_turn_in_flight(thread: dict) -> bool:
    """Return idle only after the exact pinned runtime attests it.

    A recycled Pod IP, an old replica, or a failed probe is not an idle
    observation.  Unknown therefore fails closed as ``True``; callers may use
    force-End when they intentionally accept that uncertainty.
    """
    agent_id = thread.get("agent_id")
    if not agent_id:
        return False
    try:
        context = thread.get("runtime_retirement_context") or {}
        if isinstance(context, str):
            context = json.loads(context)
        retirement_token = str(thread.get("runtime_retirement_token") or "")
        if retirement_token and isinstance(context, Mapping):
            captured_agent = context.get("agent")
            if not isinstance(captured_agent, Mapping):
                return True
            captured_agent_pod = context.get("agent_pod")
            if not isinstance(captured_agent_pod, Mapping):
                return True
            binding = PinnedSessionBinding(
                thread_id=str(thread.get("id") or context.get("thread_id") or ""),
                runtime_generation=str(
                    thread.get("runtime_generation") or context.get("generation") or ""
                ),
                agent_id=str(captured_agent.get("id") or ""),
                runtime_attach_token=str(context.get("runtime_attach_token") or ""),
                agent_hostname=str(captured_agent.get("hostname") or ""),
                pod_namespace=str(captured_agent_pod.get("namespace") or ""),
                pod_uid=str(captured_agent.get("pod_uid") or ""),
                pod_ip=str(captured_agent.get("pod_ip") or ""),
                pod_port=int(captured_agent.get("pod_port") or 8001),
                agent_status=str(captured_agent.get("status") or ""),
            )
        else:
            generation = str(thread.get("runtime_generation") or "")
            thread_id = str(thread.get("id") or "")
            if not generation or not thread_id:
                return True
            binding = await postgres_db.get_pinned_session_binding(
                thread_id,
                expected_runtime_generation=generation,
            )
            if binding is None or binding.agent_id != str(agent_id):
                return True
        url = f"http://{binding.pod_ip}:{binding.pod_port}/session/status"
        async with httpx.AsyncClient(timeout=3.0) as client:
            response = await client.post(
                url,
                json={
                    "session_identity_fingerprint": (
                        binding.session_identity_fingerprint
                    )
                },
            )
        if response.status_code != 200:
            return True
        payload = response.json()
        if not (
            isinstance(payload, Mapping)
            and payload.get("recipient_verified") is True
            and payload.get("session_identity_fingerprint")
            == binding.session_identity_fingerprint
            and str(payload.get("thread_id") or "") == binding.thread_id
            and isinstance(payload.get("turn_in_flight"), bool)
        ):
            return True

        if retirement_token:
            current = await postgres_db.get_thread(binding.thread_id)
            current_context = (current or {}).get("runtime_retirement_context") or {}
            if isinstance(current_context, str):
                current_context = json.loads(current_context)
            if not (
                current
                and str(current.get("runtime_generation") or "")
                == binding.runtime_generation
                and str(current.get("runtime_retirement_token") or "")
                == retirement_token
                and isinstance(current_context, Mapping)
                and str(current_context.get("runtime_attach_token") or "")
                == binding.runtime_attach_token
                and str((current_context.get("agent") or {}).get("id") or "")
                == binding.agent_id
            ):
                return True
        else:
            current_binding = await postgres_db.get_pinned_session_binding(
                binding.thread_id,
                expected_runtime_generation=binding.runtime_generation,
            )
            if (
                current_binding is None
                or current_binding.target_key != binding.target_key
            ):
                return True
        return payload["turn_in_flight"]
    except Exception:
        return True


def _stateless_retirement_marker(thread: dict[str, Any]) -> dict[str, Any]:
    from shared.session_retirement import stateless_retirement_authority

    marker = stateless_retirement_authority(thread_metadata_object(thread))
    if marker is None:
        raise RuntimeError("stateless retirement marker is absent")
    return marker


async def _reconcile_stateless_thread_retirement(
    thread_id: str,
    *,
    force: bool,
    permanent: bool,
) -> dict[str, Any]:
    """Converge one already-serialized stateless terminal lifecycle.

    Queue closure is the first durable effect. Claimant quiescence, exact
    remote shell retirement, snapshot/delete, and marker clearance then occur
    in that order. Every ambiguous boundary leaves the ended thread + closed
    queue marker intact so End or soft Resume can retry the same token.
    """

    from orchestrator.services.stateless_session_retirement import (
        ShellRetirementUnavailable,
        retire_stateless_session_shell,
        retire_stateless_workspace_residents,
        verify_stateless_workspace_residents_retired,
    )
    from shared.session_retirement import (
        mark_session_claim_eviction_requested,
        stateless_retirement_release_authorized,
    )

    async def _rebase_stale_terminal_runtime_or_raise(
        *,
        terminal_token: int,
        retired_runtime_incarnation: str,
    ) -> None:
        """Retarget the pending fence, then require a fresh retirement pass."""

        rebased = await postgres_db.rebase_stateless_thread_workspace_retirement(
            thread_id,
            terminal_token=terminal_token,
            retired_runtime_incarnation=retired_runtime_incarnation,
            permanent=permanent,
        )
        if not rebased:
            raise HTTPException(
                status_code=503,
                detail="Terminal workspace successor authority is not yet safe",
            )
        raise HTTPException(
            status_code=503,
            detail="Terminal workspace authority advanced; retry retirement",
        )

    # A transitional/legacy Kubernetes row can lack its immutable Pod UID.
    # There is no safe absence proof for that shape: Pod creation precedes DB
    # binding/runtime publication, so even a backing-less 404 can follow a
    # crash plus force deletion while the partitioned process still runs.
    workspace_absence_proven = False
    preflight_thread = await postgres_db.get_thread(thread_id)
    if preflight_thread is None:
        return {"state": "missing"}
    preflight_metadata = thread_metadata_object(preflight_thread)
    preflight_workspace = preflight_metadata.get("workspace_container") or {}
    preflight_binding = preflight_metadata.get("_workspace_binding") or {}
    if isinstance(preflight_workspace, dict) and isinstance(preflight_binding, dict):
        preflight_backing = str(preflight_binding.get("backing_id") or "")
        preflight_physical = bool(
            preflight_workspace.get("provisioner") == "k8s"
            or preflight_backing.startswith("k8s-")
        )
        preflight_runtime = preflight_workspace.get("_runtime_incarnation")
        settled_present = (
            "_stateless_workspace_retirement_settled" in preflight_metadata
        )
        pending_authority = preflight_metadata.get("_stateless_claim_retirement")
        pending_retains_runtime = bool(
            isinstance(pending_authority, dict)
            and pending_authority.get("runtime_incarnation")
        )
        restore_marker_present = "_snapshot_restore_required" in preflight_workspace
        restore_required = preflight_workspace.get("_snapshot_restore_required", False)
        if restore_marker_present and type(restore_required) is not bool:
            raise HTTPException(
                status_code=503,
                detail="Stateless workspace restore authority is malformed",
            )
        creation_pending = "_runtime_creation" in preflight_workspace
        restore_pending = (
            preflight_thread.get("status") != "ended" and restore_required is True
        )
        # The durable creation marker is the only authority that may bridge a
        # committed Kubernetes create and its exact UID publication. Markerless
        # historical rows remain fail-closed.
        if (
            preflight_physical
            and not preflight_runtime
            and not settled_present
            and not pending_retains_runtime
            and not creation_pending
        ):
            raise HTTPException(
                status_code=503,
                detail=(
                    "Stateless workspace runtime identity is unavailable; "
                    "workspace reconciliation must publish an exact UID first"
                ),
            )
        if creation_pending or restore_pending:
            # Cancellation after the one-shot Pod call may leave a published
            # UID but no Ready binding/fingerprint. Terminal retirement cannot
            # infer those fields or mutate the thread to ended first: doing so
            # would make exact continuation reject the lifecycle forever.
            # A restore retry has a second edge: exact UID continuation can
            # publish Ready while deliberately leaving the snapshot debt for a
            # later extraction pass. Under the already-held distributed
            # lifecycle lock, drive one exact reconciliation pass and then
            # require *both* creation and restore authority to be clear before
            # Begin. If another pass is needed, leave thread and queue lifecycle
            # untouched and let the caller retry End.
            await ensure_session_workspace(
                thread_id,
                db=postgres_db,
                provisioner=container_provisioner,
                suspension=workspace_suspension_service,
                _workspace_lifecycle_lock_held=True,
            )
            preflight_thread = await postgres_db.get_thread(thread_id)
            if preflight_thread is None:
                return {"state": "missing"}
            _, creation_refusal = stateless_session_workspace_check(preflight_thread)
            preflight_metadata = thread_metadata_object(preflight_thread)
            preflight_workspace = preflight_metadata.get("workspace_container") or {}
            preflight_binding = preflight_metadata.get("_workspace_binding") or {}
            post_restore_present = (
                isinstance(preflight_workspace, dict)
                and "_snapshot_restore_required" in preflight_workspace
            )
            post_restore_required = (
                preflight_workspace.get("_snapshot_restore_required", False)
                if isinstance(preflight_workspace, dict)
                else None
            )
            post_restore_malformed = bool(
                post_restore_present and type(post_restore_required) is not bool
            )
            post_restore_pending = bool(
                preflight_thread.get("status") != "ended"
                and post_restore_required is True
            )
            if (
                creation_refusal is not None
                or not isinstance(preflight_workspace, dict)
                or preflight_workspace.get("status") != "ready"
                or "_runtime_creation" in preflight_workspace
                or post_restore_malformed
                or post_restore_pending
            ):
                raise HTTPException(
                    status_code=503,
                    detail=(
                        "Stateless workspace creation and restore must reach "
                        "exact Ready authority before retirement"
                    ),
                )

    async def _begin_retirement(*, requested_force: bool) -> dict[str, Any]:
        try:
            return await postgres_db.begin_stateless_thread_workspace_retirement(
                thread_id,
                force=requested_force,
                permanent=permanent,
                workspace_absence_proven=workspace_absence_proven,
            )
        except RuntimeError as exc:
            raise HTTPException(
                status_code=503,
                detail="Stateless retirement authority is malformed or changed",
            ) from exc

    closure = await _begin_retirement(requested_force=force)
    state = str(closure.get("state") or "")
    if state == "missing":
        return {"state": "missing"}
    if state == "busy":
        raise HTTPException(
            status_code=409,
            detail={"code": "stateless_end_busy", **closure},
        )
    if state in {
        "incompatible",
        "unsafe_missing_queue",
        "needs_runtime_preflight",
    }:
        raise HTTPException(
            status_code=409,
            detail={"code": "stateless_retirement_unsafe", **closure},
        )
    if state == "settled":
        if closure.get("permanent") is not permanent:
            raise HTTPException(
                status_code=503,
                detail="Settled stateless retirement intent is malformed",
            )
        if permanent:
            backing_id = closure.get("backing_id")
            runtime_incarnation = closure.get("runtime_incarnation")
            if isinstance(backing_id, str) and backing_id.startswith("k8s-"):
                # Soft End already proved process zero and removed the exact
                # Pod. Permanent upgrade creates a new terminal-reclaim
                # generation: preserve authority cannot authorize PVC deletion.
                if not runtime_incarnation:
                    raise HTTPException(
                        status_code=503,
                        detail=("Settled workspace runtime authority is unavailable"),
                    )
                cleanup_intent = (
                    await container_provisioner.prepare_workspace_cleanup_intent(
                        WorkspaceOwner.session(thread_id),
                        expected_runtime_incarnation=str(runtime_incarnation),
                        target_disposition="deleted",
                        reclaim_shared_resources=True,
                    )
                )
                if (
                    not isinstance(cleanup_intent, dict)
                    or cleanup_intent.get("resources_captured_at") is None
                    or cleanup_intent.get("reclaim_shared_resources") is not True
                ):
                    raise HTTPException(
                        status_code=503,
                        detail=(
                            "Settled workspace permanent cleanup authority is incomplete"
                        ),
                    )
                cleanup = (
                    await container_provisioner.reconcile_workspace_cleanup_intent(
                        WorkspaceOwner.session(thread_id),
                        expected_runtime_incarnation=str(runtime_incarnation),
                        intent_generation=int(cleanup_intent["intent_generation"]),
                    )
                )
                if (
                    not isinstance(cleanup, WorkspaceCleanupOutcome)
                    or not cleanup.settled
                ):
                    raise HTTPException(
                        status_code=503,
                        detail="Settled workspace permanent cleanup is incomplete",
                    )
        return {
            "state": "settled",
            "thread": await postgres_db.get_thread(thread_id),
            "closure": closure,
        }
    if state != "closed":
        raise HTTPException(
            status_code=503,
            detail="Stateless retirement could not close its queue",
        )
    if closure.get("retry") and closure.get("permanent") is not permanent:
        raise HTTPException(
            status_code=409,
            detail="A different stateless retirement intent is still pending",
        )

    terminal_token = int(closure.get("terminal_token") or 0)
    deadline = time.monotonic() + float(
        os.environ.get("STATELESS_TERMINAL_CLAIM_ACK_TIMEOUT_S", "25")
    )
    while not closure.get("claimant_quiesced"):
        raw_losses = closure.get("claim_losses") or []
        if not isinstance(raw_losses, list) or not raw_losses or terminal_token <= 0:
            raise HTTPException(
                status_code=503,
                detail="Terminal claimant-loss authority is incomplete",
            )
        for raw_loss in raw_losses:
            if not isinstance(raw_loss, dict):
                raise HTTPException(
                    status_code=503,
                    detail="Terminal claimant-loss authority is malformed",
                )
            pod_name = str(raw_loss.get("pod") or "")
            pod_uid = str(raw_loss.get("pod_uid") or "")
            previous_token = int(raw_loss.get("lease_token") or 0)
            if not pod_name or not pod_uid or previous_token <= 0:
                raise HTTPException(
                    status_code=503,
                    detail="Terminal claimant identity is incomplete",
                )
            authority = await agent_provisioner.agent_pod_authority(
                pod_name,
                expected_pod_uid=pod_uid,
            )
            if authority == "exact_terminal":
                await postgres_db.acknowledge_stateless_thread_claimant_absent(
                    thread_id,
                    terminal_token=terminal_token,
                    previous_lease_token=previous_token,
                    previous_leased_by=pod_name,
                    previous_pod_uid=pod_uid,
                )
            elif authority == "exact_live":
                if await mark_session_claim_eviction_requested(
                    postgres_db,
                    thread_id=thread_id,
                    previous_lease_token=previous_token,
                    leased_by=pod_name,
                    pod_uid=pod_uid,
                ):
                    await agent_provisioner.delete_agent_pod_exact(
                        pod_name,
                        expected_pod_uid=pod_uid,
                    )
        closure = await _begin_retirement(requested_force=True)
        if closure.get("claimant_quiesced"):
            break
        if time.monotonic() >= deadline:
            raise HTTPException(
                status_code=503,
                detail="Terminal claimant quiescence is not yet acknowledged",
            )
        await asyncio.sleep(0.25)

    terminal_cloud_mount_cfg: dict[str, Any] | None = None
    if closure.get("resident_cleanup_required") and not closure.get(
        "resident_acknowledged"
    ):
        current = await postgres_db.get_thread(thread_id)
        if current is None:
            return {"state": "missing"}
        metadata = thread_metadata_object(current)
        workspace = metadata.get("workspace_container") or {}
        marker = _stateless_retirement_marker(current)
        runtime_incarnation = marker.get("runtime_incarnation")
        if not runtime_incarnation:
            raise HTTPException(
                status_code=503,
                detail="Resident cleanup runtime identity is unavailable",
            )
        runtime_authority = await container_provisioner.workspace_pod_authority(
            WorkspaceOwner.session(thread_id),
            expected_runtime_incarnation=str(runtime_incarnation),
        )
        if runtime_authority == "exact_terminal":
            # Exact UID plus all containers observed terminated proves both
            # shell and resident processes stopped. API-object absence alone
            # is not proof: a partitioned kubelet may keep the old process
            # running after a force deletion removes the object.
            acknowledged = await postgres_db.acknowledge_stateless_thread_shell_absent(
                thread_id,
                terminal_token=terminal_token,
                runtime_incarnation=str(runtime_incarnation),
            )
            if not acknowledged:
                raise HTTPException(
                    status_code=503,
                    detail="Absent resident retirement proof was not durable",
                )
        elif runtime_authority == "exact_live" and workspace.get("status") in {
            "ready",
            "retiring_process_zero",
        }:
            terminal_cloud_mount_cfg = await _build_agent_cloud_mount(
                current,
                mount_rows=await postgres_db.list_thread_mounts(thread_id),
                metadata=metadata,
                terminal_retirement_token=terminal_token,
            )
            try:
                proof = await retire_stateless_workspace_residents(
                    current,
                    terminal_token=terminal_token,
                    cloud_mount_cfg=terminal_cloud_mount_cfg,
                )
            except ShellRetirementUnavailable as exc:
                cause = exc.__cause__
                logger.warning(
                    "Stateless terminal cleanup remains pending: thread=%s "
                    "stage=resident workspace_status=%s cloud_mount=%s cause=%s",
                    thread_id,
                    workspace.get("status"),
                    terminal_cloud_mount_cfg is not None,
                    (
                        f"{type(cause).__name__}: {str(cause)[:300]}"
                        if cause is not None
                        else type(exc).__name__
                    ),
                )
                raise HTTPException(
                    status_code=503,
                    detail="Workspace resident retirement is not yet acknowledged",
                ) from exc
            # The resident protocol's final command independently proves the
            # exact workspace has no managed-repository credential agents.
            # Persist that existing generic process-zero authority before the
            # resident ACK. Otherwise release_workspace() must repeat the SSH
            # retirement after the terminal shell record has been written and
            # can remain fail-closed forever even though this exact proof was
            # already obtained.
            process_zero_recorded = (
                await postgres_db.record_managed_repository_workspace_process_zero(
                    thread_id,
                    owner_kind="thread",
                    scope="workspace_container",
                    provisioner="k8s",
                    runtime_incarnation=proof.authority.runtime_incarnation,
                )
            )
            if not process_zero_recorded:
                raise HTTPException(
                    status_code=503,
                    detail="Managed repository process-zero proof was not durable",
                )
            acknowledged = (
                await postgres_db.acknowledge_stateless_thread_resident_retirement(
                    thread_id,
                    terminal_token=terminal_token,
                    workspace_generation=proof.authority.workspace_generation,
                    endpoint_generation=proof.authority.workspace_generation,
                    runtime_incarnation=proof.authority.runtime_incarnation,
                    host_key_fingerprint=proof.authority.host_key_fingerprint,
                    proof=proof.as_dict(),
                )
            )
            if not acknowledged:
                raise HTTPException(
                    status_code=503,
                    detail="Workspace resident retirement acknowledgement was ambiguous",
                )
        else:
            raise HTTPException(
                status_code=503,
                detail="Workspace resident runtime authority changed or is ambiguous",
            )
        closure = await _begin_retirement(requested_force=True)

    if closure.get("shell_retirement_required") and not closure.get(
        "remote_acknowledged"
    ):
        current = await postgres_db.get_thread(thread_id)
        if current is None:
            return {"state": "missing"}
        metadata = thread_metadata_object(current)
        workspace = metadata.get("workspace_container") or {}
        marker = _stateless_retirement_marker(current)
        runtime_incarnation = marker.get("runtime_incarnation")
        if not runtime_incarnation:
            raise HTTPException(
                status_code=503,
                detail="Remote shell runtime identity is unavailable",
            )
        runtime_authority = await container_provisioner.workspace_pod_authority(
            WorkspaceOwner.session(thread_id),
            expected_runtime_incarnation=str(runtime_incarnation),
        )
        if runtime_authority == "exact_live" and workspace.get("status") in {
            "ready",
            "retiring_process_zero",
        }:
            if (
                closure.get("resident_cleanup_required")
                and terminal_cloud_mount_cfg is None
            ):
                terminal_cloud_mount_cfg = await _build_agent_cloud_mount(
                    current,
                    mount_rows=await postgres_db.list_thread_mounts(thread_id),
                    metadata=metadata,
                    terminal_retirement_token=terminal_token,
                )
            try:
                authority = await retire_stateless_session_shell(
                    current,
                    terminal_token=terminal_token,
                )
                if closure.get("resident_cleanup_required"):
                    # Shell kill is a second mutation boundary. Re-scan under
                    # the exact retired-T marker so a pane/background process
                    # cannot repopulate the snapshot after the pre-kill proof.
                    await verify_stateless_workspace_residents_retired(
                        current,
                        terminal_token=terminal_token,
                        cloud_mount_cfg=terminal_cloud_mount_cfg,
                    )
            except ShellRetirementUnavailable as exc:
                cause = exc.__cause__
                logger.warning(
                    "Stateless terminal cleanup remains pending: thread=%s "
                    "stage=shell_or_postcheck workspace_status=%s "
                    "cloud_mount=%s cause=%s",
                    thread_id,
                    workspace.get("status"),
                    terminal_cloud_mount_cfg is not None,
                    (
                        f"{type(cause).__name__}: {str(cause)[:300]}"
                        if cause is not None
                        else type(exc).__name__
                    ),
                )
                raise HTTPException(
                    status_code=503,
                    detail="Remote shell retirement is not yet acknowledged",
                ) from exc
            acknowledged = (
                await postgres_db.acknowledge_stateless_thread_shell_retirement(
                    thread_id,
                    terminal_token=terminal_token,
                    workspace_generation=authority.workspace_generation,
                    endpoint_generation=authority.workspace_generation,
                    runtime_incarnation=authority.runtime_incarnation,
                    host_key_fingerprint=authority.host_key_fingerprint,
                )
            )
        elif runtime_authority == "exact_terminal":
            acknowledged = await postgres_db.acknowledge_stateless_thread_shell_absent(
                thread_id,
                terminal_token=terminal_token,
                runtime_incarnation=str(runtime_incarnation),
            )
        else:
            acknowledged = False
        if not acknowledged:
            raise HTTPException(
                status_code=503,
                detail="Remote shell retirement acknowledgement was ambiguous",
            )

    # The remote effects above and workspace destruction below are separate
    # authority boundaries.  Re-lock/re-read the terminal row before *any*
    # snapshot, Pod, Service, or PVC effect and require exact claimant,
    # resident, and shell proofs.  The shared parser also rejects malformed
    # JSON booleans/ACK tuples and post-ACK incarnation drift.
    closure = await _begin_retirement(requested_force=True)
    if str(closure.get("state") or "") != "closed":
        raise HTTPException(
            status_code=503,
            detail="Stateless retirement authority changed before workspace release",
        )

    current = await postgres_db.get_thread(thread_id)
    if current is None:
        return {"state": "missing"}
    metadata = thread_metadata_object(current)
    try:
        release_authority = stateless_retirement_release_authorized(metadata)
    except RuntimeError as exc:
        raise HTTPException(
            status_code=503,
            detail="Stateless retirement proofs are incomplete or malformed",
        ) from exc
    if int(release_authority["terminal_token"]) != terminal_token:
        raise HTTPException(
            status_code=503,
            detail="Stateless retirement token changed before workspace release",
        )
    workspace = metadata.get("workspace_container") or {}
    marker = _stateless_retirement_marker(current)
    binding = metadata.get("_workspace_binding") or {}
    backing_id = str(binding.get("backing_id") or "")
    runtime_incarnation = marker.get("runtime_incarnation")
    runtime_authority = "not_applicable"
    if workspace.get("provisioner") == "k8s" and runtime_incarnation:
        runtime_authority = await container_provisioner.workspace_pod_authority(
            WorkspaceOwner.session(thread_id),
            expected_runtime_incarnation=str(runtime_incarnation),
        )
    physical_workspace = bool(
        workspace.get("provisioner") == "k8s"
        or backing_id.startswith("k8s-")
        or runtime_incarnation
    )
    if physical_workspace and not (
        backing_id.startswith("k8s-pod:") or backing_id.startswith("k8s-pvc:")
    ):
        raise HTTPException(
            status_code=503,
            detail="Stateless workspace backing authority is incomplete",
        )
    requires_snapshot = bool(not permanent and backing_id.startswith("k8s-pod:"))
    raw_snapshot_proof = workspace.get("_snapshot_restore_required", False)
    if type(raw_snapshot_proof) is not bool:
        raise HTTPException(
            status_code=503,
            detail="Stateless snapshot proof is malformed",
        )
    snapshot_already_captured = raw_snapshot_proof is True
    if runtime_authority in {"replacement", "unknown"}:
        raise HTTPException(
            status_code=503,
            detail="Stateless workspace runtime authority changed or is ambiguous",
        )
    if runtime_authority == "exact_absent":
        if requires_snapshot and not snapshot_already_captured:
            raise HTTPException(
                status_code=503,
                detail="Required emptyDir snapshot was not durably captured",
            )
        if permanent:
            cleanup_intent = (
                await container_provisioner.prepare_workspace_cleanup_intent(
                    WorkspaceOwner.session(thread_id),
                    expected_runtime_incarnation=str(runtime_incarnation),
                    target_disposition="deleted",
                    reclaim_shared_resources=True,
                )
            )
            if (
                not isinstance(cleanup_intent, dict)
                or cleanup_intent.get("resources_captured_at") is None
                or cleanup_intent.get("reclaim_shared_resources") is not True
            ):
                raise HTTPException(
                    status_code=503,
                    detail="Stateless absent workspace cleanup authority is incomplete",
                )
            cleanup = await container_provisioner.reconcile_workspace_cleanup_intent(
                WorkspaceOwner.session(thread_id),
                expected_runtime_incarnation=str(runtime_incarnation),
                intent_generation=int(cleanup_intent["intent_generation"]),
            )
            released = isinstance(cleanup, WorkspaceCleanupOutcome) and cleanup.settled
        else:
            released = await container_provisioner.release_absent_workspace(
                WorkspaceOwner.session(thread_id),
                reclaim_volume=False,
                expected_runtime_incarnation=str(runtime_incarnation),
                strict=True,
            )
        if not released:
            raise HTTPException(
                status_code=503,
                detail="Stateless absent workspace cleanup remains incomplete",
            )
    elif physical_workspace:
        if not runtime_incarnation:
            raise HTTPException(
                status_code=503,
                detail="Stateless workspace runtime identity is unavailable",
            )
        if runtime_authority == "exact_terminal":
            if requires_snapshot and not snapshot_already_captured:
                # An emptyDir whose runtime is already terminal cannot be
                # archived now. Do not destroy its object or clear retirement
                # authority without a previously committed snapshot proof.
                raise HTTPException(
                    status_code=503,
                    detail="Required emptyDir snapshot was not durably captured",
                )
            # Persist disposition and exact captured resource identities before
            # any Kubernetes effect. Permanent End cannot reuse preserve-only
            # authority to reclaim PVC/Service state.
            cleanup_intent = (
                await container_provisioner.prepare_workspace_cleanup_intent(
                    WorkspaceOwner.session(thread_id),
                    expected_runtime_incarnation=str(runtime_incarnation),
                    target_disposition="deleted",
                    reclaim_shared_resources=permanent,
                )
            )
            if (
                not isinstance(cleanup_intent, dict)
                or cleanup_intent.get("resources_captured_at") is None
                or bool(cleanup_intent.get("reclaim_shared_resources")) is not permanent
            ):
                raise HTTPException(
                    status_code=503,
                    detail="Terminal workspace cleanup authority is incomplete",
                )
            deletion = await container_provisioner.delete_workspace_with_outcome(
                WorkspaceOwner.session(thread_id),
                expected_runtime_incarnation=str(runtime_incarnation),
                wait_for_exact_absence=True,
                target_disposition="deleted",
                reclaim_shared_resources=permanent,
                cleanup_intent=cleanup_intent,
            )
            if deletion.stale_target_settled:
                await _rebase_stale_terminal_runtime_or_raise(
                    terminal_token=terminal_token,
                    retired_runtime_incarnation=str(runtime_incarnation),
                )
            if not deletion.current_deleted:
                raise HTTPException(
                    status_code=503,
                    detail="Terminal workspace Pod deletion remains incomplete",
                )
            cleanup = await container_provisioner.reconcile_workspace_cleanup_intent(
                WorkspaceOwner.session(thread_id),
                expected_runtime_incarnation=str(runtime_incarnation),
                intent_generation=int(cleanup_intent["intent_generation"]),
            )
            if not isinstance(cleanup, WorkspaceCleanupOutcome) or not cleanup.settled:
                raise HTTPException(
                    status_code=503,
                    detail="Terminal workspace cleanup remains incomplete",
                )
        elif runtime_authority != "exact_live":
            raise HTTPException(
                status_code=503,
                detail="Stateless workspace runtime identity is unavailable",
            )
        else:
            expected_runtime = str(runtime_incarnation)
            expected_fingerprint = (
                str(marker.get("host_key_fingerprint"))
                if marker.get("host_key_fingerprint")
                else None
            )

            # Begin may have pre-admitted the terminal cleanup generation in
            # the same transaction that closed the queue and projected
            # retiring_process_zero. Claim that exact generation and capture
            # its Pod/PVC/Service UIDs before release_workspace reads it.
            # Passing an admitted-but-uncaptured intent directly to the lower
            # deletion boundary correctly fails closed without issuing DELETE.
            try:
                teardown_identity = (
                    await container_provisioner.capture_terminal_workspace_identity(
                        WorkspaceOwner.session(thread_id)
                    )
                )
            except WorkspaceRuntimeAuthorityError as exc:
                raise HTTPException(
                    status_code=503,
                    detail="Live workspace teardown identity is unavailable",
                ) from exc
            if (
                teardown_identity.pod_uid != expected_runtime
                or not teardown_identity.pod_ip
                or teardown_identity.ssh_host_key_fingerprint != expected_fingerprint
            ):
                raise HTTPException(
                    status_code=503,
                    detail="Live workspace teardown identity changed",
                )
            cleanup_intent = (
                await container_provisioner.prepare_workspace_cleanup_intent(
                    WorkspaceOwner.session(thread_id),
                    expected_runtime_incarnation=expected_runtime,
                    target_disposition="deleted",
                    reclaim_shared_resources=permanent,
                    identity=teardown_identity,
                )
            )
            if (
                not isinstance(cleanup_intent, dict)
                or cleanup_intent.get("resources_captured_at") is None
                or bool(cleanup_intent.get("reclaim_shared_resources")) is not permanent
            ):
                raise HTTPException(
                    status_code=503,
                    detail="Live workspace cleanup authority is incomplete",
                )

            async def _snapshot_ack() -> bool:
                return (
                    await postgres_db.mark_stateless_thread_snapshot_restore_required(
                        thread_id,
                        terminal_token=terminal_token,
                    )
                )

            try:
                released = await asyncio.wait_for(
                    container_provisioner.release_workspace(
                        WorkspaceOwner.session(thread_id),
                        reclaim_volume=permanent,
                        require_snapshot=(
                            requires_snapshot and not snapshot_already_captured
                        ),
                        expected_runtime_incarnation=expected_runtime,
                        expected_host_key_fingerprint=expected_fingerprint,
                        on_snapshot_captured=(
                            _snapshot_ack
                            if requires_snapshot and not snapshot_already_captured
                            else None
                        ),
                        capture_snapshot=(
                            requires_snapshot and not snapshot_already_captured
                        ),
                        strict_terminal_snapshot=True,
                        strict=True,
                        teardown_identity=teardown_identity,
                    ),
                    timeout=float(
                        os.environ.get("STATELESS_TERMINAL_RELEASE_TIMEOUT_S", "300")
                    ),
                )
            except asyncio.TimeoutError as exc:
                raise HTTPException(
                    status_code=503,
                    detail="Stateless workspace retirement timed out",
                ) from exc
            if not released:
                raise HTTPException(
                    status_code=503,
                    detail="Stateless workspace retirement remains incomplete",
                )
    elif workspace.get("provisioner") == "k8s":
        # Missing context is not proof that the deterministic pod name is free.
        # A never-provisioned sandbox may finish only after Kubernetes confirms
        # no physical runtime exists; ambiguity keeps the marker retryable.
        released = await container_provisioner.release_absent_workspace(
            WorkspaceOwner.session(thread_id),
            reclaim_volume=permanent,
            strict=True,
        )
        if not released:
            raise HTTPException(
                status_code=503,
                detail="Stateless workspace absence could not be established",
            )

    if (
        not permanent
        and not await postgres_db.finish_stateless_thread_workspace_retirement(
            thread_id
        )
    ):
        raise HTTPException(
            status_code=503,
            detail="Stateless workspace retirement proofs did not settle",
        )
    return {"state": "settled", "thread": current, "closure": closure}


@app.delete("/api/persistent/threads/{thread_id}")
async def end_thread(
    thread_id: str,
    request: Request,
    permanent: bool = False,
    force: bool = False,
) -> dict[str, Any]:
    """End (or permanently delete) a persistent thread (auth: owner only).

    Query params:
        permanent: If true, delete the thread row and all associated messages
                   from the database. If false (default), just mark as ended.
        force: Required to end a session whose agent is mid-turn. Without it
               a live turn returns 409 — a sessions-list cleanup sweep tore
               down an active session mid-turn, destroying its in-memory
               input queue (knowledge-base/knowledge/issues/session_silent_failure_audit.md #11).
    """
    _user, thread = await require_thread_owner(request, postgres_db, thread_id)
    return await _end_thread_flow(thread_id, thread, permanent=permanent, force=force)


async def _end_thread_flow(
    thread_id: str,
    thread: dict[str, Any],
    *,
    permanent: bool,
    force: bool,
    officer_retire_reason: str = "retired",
    officer_post_required: bool = False,
    include_officer_handoff: bool = False,
    expected_runtime_generation: str | None = None,
    expected_agent_id: str | None = None,
    expected_attach_token: str | None = None,
    require_expected_agent_offline: bool = False,
    settle_status: Literal["ended", "suspended"] = "ended",
    local_runtime_quiesced: bool = False,
    retiring_agent_response_pending: bool = False,
) -> dict[str, Any]:
    """The End funnel body — everything ``end_thread`` does after auth.

    Shared by the owner-facing DELETE and the project-admin officer
    decommission endpoint (officer_post.md §5): both must run the same
    stand-down, resource release, and status write, so there is exactly one
    way a thread leaves service. ``officer_retire_reason`` is recorded on
    the post's incarnation entry when the thread holds one ('retired' for a
    direct DELETE, 'decommissioned' via the endpoint). Direct End permits the
    transaction's orphan-only branch; the explicit project endpoint requires
    that its expected thread still holds the post. ``include_officer_handoff``
    is an internal response bridge for that endpoint, never a public request
    field.
    """
    if permanent and settle_status != "ended":
        raise ValueError("permanent retirement cannot settle suspended")
    if retiring_agent_response_pending and not local_runtime_quiesced:
        raise ValueError("retiring agent response requires local quiescence")
    stateless = thread.get("execution_lane") == "stateless"
    initial_status = thread.get("status")
    initial_stateless_authority: dict[str, Any] | None = None

    async def _stand_down(
        authoritative_thread: dict[str, Any],
        *,
        retirement_authority: Mapping[str, Any] | None = None,
        converge_authorized: bool = False,
    ) -> dict[str, Any] | None:
        """Run idempotent End-owned stand-down under durable authority.

        For the first linked Officer transition, ``retirement_authority`` is
        appended in the same database transaction as decommission after the
        transaction's in-flight refusal point. Every other caller authorizes
        before entering this helper. ``converge_authorized`` makes a retry of
        an irrevocable retirement ignore a newly observed Officer-job warning
        rather than returning a force prompt for work that is already ending.
        """

        authoritative_metadata = thread_metadata_object(authoritative_thread)
        officer_meta = (authoritative_metadata.get("config_override") or {}).get(
            "officer"
        ) or {}
        handoff: dict[str, Any] | None = None
        if isinstance(officer_meta, dict) and officer_meta.get("enabled") in (
            True,
            "true",
            "True",
            1,
        ):
            try:
                handoff = await _decommission_officer_post(
                    authoritative_thread,
                    reason=officer_retire_reason,
                    force=force or converge_authorized,
                    allow_orphan_retirement=not officer_post_required,
                    retirement=retirement_authority,
                )
            except OfficerPostLifecycleConflict as exc:
                raise HTTPException(status_code=409, detail=exc.detail) from exc
            # An enabled legacy/orphan thread may own no durable post. It must
            # still be disabled before ordinary End continues, but it may not
            # harvest over another incarnation. Current-post failures are NOT
            # swallowed: the authoritative method raises and End stays
            # visibly retryable.
            if handoff and handoff.get("blocked_by_in_flight"):
                return handoff
            if not handoff:
                disabled = await postgres_db.merge_thread_config_override(
                    thread_id, {"officer": {"enabled": False}}
                )
                if not disabled:
                    raise RuntimeError(
                        f"Officer stand-down could not disable thread {thread_id}"
                    )
        await _conclude_conference_if_any(authoritative_thread)
        return handoff

    async def _delete_auxiliary_state(
        authoritative_thread: dict[str, Any],
    ) -> None:
        """Best-effort external records removed only for permanent End."""

        authoritative_metadata = thread_metadata_object(authoritative_thread)
        authoritative_ws = authoritative_metadata.get("workspace_container") or {}
        if snapshot_service.is_available:
            try:
                fresh = await postgres_db.get_thread(thread_id) or {}
                for key in thread_metadata_object(fresh).get("log_archive_keys") or []:
                    await snapshot_service.delete_blob(str(key))
            except Exception as exc:
                logger.warning(
                    "Log archive cleanup failed for deleted thread %s: %s",
                    thread_id,
                    exc,
                )

        repo_name = authoritative_ws.get("repo_name")
        if repo_name:
            if not await revoke_and_delete_managed_repository(
                postgres_db, gitea_client, repo_name
            ):
                raise RuntimeError("Repository credential revocation is retryable")

        session_handle_str = authoritative_thread.get(
            "main_cloud_session_handle"
        ) or authoritative_thread.get("nc_session_folder")
        if session_handle_str:
            backend = main_cloud_router.for_thread(authoritative_thread)
            if backend.is_initialized:
                try:
                    session_handle = SessionFolderHandle.from_db(
                        session_handle_str, backend=backend.backend_id
                    )
                    await backend.delete_session_folder(session_handle)
                except Exception as exc:
                    logger.warning(
                        "Failed to delete main-cloud session folder for thread %s: %s",
                        thread_id,
                        exc,
                    )

    if not stateless:
        if (
            not force
            and expected_runtime_generation is None
            and not (
                thread.get("runtime_retirement_token") is not None
                and thread.get("runtime_retirement_authorized_at") is not None
            )
            and await _thread_turn_in_flight(thread)
        ):
            # Fast observational no-op for the common non-force refusal.  The
            # locked post-Begin probe below still catches a turn admitted in
            # the narrow interval before the token closes durable admission.
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "turn_in_flight",
                    "message": (
                        "The agent is mid-turn on this session. Retry with "
                        "force=true to end it anyway."
                    ),
                },
            )
        if expected_runtime_generation is not None:
            pre_begin = await postgres_db.get_thread(thread_id)
            identity_mismatch = bool(
                pre_begin is None
                or str(pre_begin.get("runtime_generation") or "")
                != expected_runtime_generation
                or str(pre_begin.get("agent_id") or "") != str(expected_agent_id or "")
                or str(pre_begin.get("runtime_attach_token") or "")
                != str(expected_attach_token or "")
            )
            if (
                not identity_mismatch
                and pre_begin is not None
                and pre_begin.get("runtime_retirement_token") is not None
            ):
                pending_context = pre_begin.get("runtime_retirement_context") or {}
                if isinstance(pending_context, str):
                    try:
                        pending_context = json.loads(pending_context)
                    except (TypeError, ValueError):
                        pending_context = {}
                identity_mismatch = bool(
                    not isinstance(pending_context, Mapping)
                    or str(pending_context.get("generation") or "")
                    != expected_runtime_generation
                    or str(pending_context.get("agent_id") or "")
                    != str(expected_agent_id or "")
                    or str(pending_context.get("runtime_attach_token") or "")
                    != str(expected_attach_token or "")
                    or bool(pre_begin.get("runtime_retirement_permanent"))
                    != bool(permanent)
                    or str(pending_context.get("settle_status") or "") != settle_status
                )
            if identity_mismatch:
                raise HTTPException(
                    status_code=409,
                    detail={"code": "pinned_runtime_identity_mismatch"},
                )
        begin_identity: dict[str, Any] = {}
        if expected_runtime_generation is not None:
            begin_identity = {
                "expected_runtime_generation": expected_runtime_generation,
                "expected_agent_id": expected_agent_id,
                "expected_attach_token": expected_attach_token,
                "require_agent_offline": require_expected_agent_offline,
            }
        retirement = await _begin_pinned_thread_retirement(
            thread_id,
            permanent=permanent,
            settle_status=settle_status,
            **begin_identity,
        )
        state = str(retirement.get("state") or "")
        if state == "missing":
            return {"status": "deleted"}
        if state == "settled" and not permanent:
            return {"status": settle_status}
        if state != "pending":
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "pinned_retirement_conflict",
                    "reason": retirement.get("reason") or state,
                },
            )
        already_authorized = retirement.get("authorized_at") is not None

        async def _abort_hidden_preflight() -> str:
            """Resolve this request's pre-authorization marker exactly.

            ``aborted`` is the only outcome that permits a refusal to be
            reported as an observational no-op. A concurrent authorization is
            irrevocable and must converge as ``ending``; an exact hidden
            marker that somehow survives two CAS attempts is left for the
            bounded stale-preflight reaper and reported as recovery-required.
            """

            token = str(retirement["token"])
            generation = str(retirement["generation"])
            if await postgres_db.abort_pinned_thread_retirement(
                thread_id, token=token, generation=generation
            ):
                return "aborted"
            current = await postgres_db.get_thread(thread_id)
            if current is None:
                return "superseded"
            if (
                str(current.get("runtime_generation") or "") != generation
                or str(current.get("runtime_retirement_token") or "") != token
            ):
                return "superseded"
            if current.get("runtime_retirement_authorized_at") is not None:
                return "authorized"
            if await postgres_db.abort_pinned_thread_retirement(
                thread_id, token=token, generation=generation
            ):
                return "aborted"
            current = await postgres_db.get_thread(thread_id)
            if (
                current is None
                or str(current.get("runtime_generation") or "") != generation
                or str(current.get("runtime_retirement_token") or "") != token
            ):
                return "superseded"
            if current.get("runtime_retirement_authorized_at") is not None:
                return "authorized"
            return "preflight"

        def _ending_response(
            *,
            retry_after_ms: int | None = None,
            retiring_agent_exit_authorized: bool = False,
        ) -> dict[str, Any]:
            response: dict[str, Any] = {
                "status": "ending",
                "retirement_disposition": settle_status,
                "retirement_permanent": bool(permanent),
            }
            if retry_after_ms is not None:
                response["retry_after_ms"] = retry_after_ms
            if retiring_agent_exit_authorized:
                response["retiring_agent_exit_authorized"] = True
                response["session_runtime_retirement_token"] = str(retirement["token"])
            return response

        if expected_runtime_generation is not None:
            captured = retirement.get("context") or {}
            identity_matches = bool(
                str(retirement.get("generation") or "") == expected_runtime_generation
                and str(captured.get("agent_id") or "") == str(expected_agent_id or "")
                and str(captured.get("runtime_attach_token") or "")
                == str(expected_attach_token or "")
            )
            if not identity_matches:
                if not retirement.get("reused") and not already_authorized:
                    abort_outcome = await _abort_hidden_preflight()
                    if abort_outcome == "authorized":
                        return _ending_response(retry_after_ms=250)
                raise HTTPException(
                    status_code=409,
                    detail={"code": "pinned_runtime_identity_mismatch"},
                )

        # The protected-engage producer and every pinned workspace ensure use
        # this same cross-replica lock. Admission was closed *before* waiting,
        # so old work can finish/roll back but no replacement may start.
        async with postgres_db.try_thread_advisory_lock(thread_id) as lock_owner:
            if not lock_owner:
                if already_authorized:
                    return _ending_response(retry_after_ms=250)
                abort_outcome = await _abort_hidden_preflight()
                if abort_outcome == "authorized":
                    return _ending_response(retry_after_ms=250)
                raise HTTPException(
                    status_code=503,
                    detail={
                        "code": (
                            "pinned_retirement_preflight_busy"
                            if abort_outcome in {"aborted", "superseded"}
                            else "pinned_retirement_preflight_recovery_required"
                        ),
                        "message": (
                            "Runtime lifecycle work is still converging; retry End."
                        ),
                    },
                )
            if not await _pinned_retirement_is_current(retirement):
                raise HTTPException(
                    status_code=409, detail="Pinned retirement authority changed"
                )
            context = retirement.get("context")
            context = {} if context is None else context
            captured_agent = (
                context.get("agent") if isinstance(context, Mapping) else None
            )
            probe_thread = {
                "id": thread_id,
                "runtime_generation": retirement.get("generation"),
                "runtime_retirement_token": retirement.get("token"),
                "runtime_retirement_context": context,
                "agent_id": (captured_agent or {}).get("id")
                if isinstance(captured_agent, Mapping)
                else None,
            }
            if (
                not already_authorized
                and not force
                and await _thread_turn_in_flight(probe_thread)
            ):
                abort_outcome = await _abort_hidden_preflight()
                if abort_outcome == "authorized":
                    return _ending_response(retry_after_ms=250)
                if abort_outcome == "preflight":
                    raise HTTPException(
                        status_code=503,
                        detail={
                            "code": "pinned_retirement_preflight_recovery_required"
                        },
                    )
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": "turn_in_flight",
                        "message": (
                            "The agent is mid-turn on this session. Retry with "
                            "force=true to end it anyway."
                        ),
                    },
                )

            authoritative_thread = await postgres_db.get_thread(thread_id)
            if authoritative_thread is None:
                return {"status": "deleted"}
            officer_handoff = None
            authoritative_metadata = thread_metadata_object(authoritative_thread)
            officer_cfg = (authoritative_metadata.get("config_override") or {}).get(
                "officer"
            ) or {}
            linked_officer_authorization = bool(
                not already_authorized
                and settle_status == "ended"
                and isinstance(officer_cfg, Mapping)
                and officer_cfg.get("enabled") in (True, "true", "True", 1)
                and authoritative_thread.get("project_id") is not None
            )

            # A linked Officer's no-force in-flight decision and its durable
            # post mutation share one transaction with authorization. Every
            # other runtime authorizes before any stand-down/conference
            # mutation. Thus an unauthorized marker remains safe for the
            # stale-preflight reaper to clear after a crashed request.
            if linked_officer_authorization:
                try:
                    officer_handoff = await _stand_down(
                        authoritative_thread,
                        retirement_authority=retirement,
                    )
                except BaseException:
                    abort_outcome = await asyncio.shield(_abort_hidden_preflight())
                    if abort_outcome == "authorized":
                        return _ending_response(retry_after_ms=250)
                    raise
                if officer_handoff and officer_handoff.get("blocked_by_in_flight"):
                    abort_outcome = await _abort_hidden_preflight()
                    if abort_outcome == "authorized":
                        return _ending_response(retry_after_ms=250)
                    if abort_outcome == "preflight":
                        raise HTTPException(
                            status_code=503,
                            detail={
                                "code": "pinned_retirement_preflight_recovery_required"
                            },
                        )
                    return _officer_in_flight_decommission_response(officer_handoff)
                already_authorized = True
                retirement["authorized_at"] = True
            elif not already_authorized:
                if not await postgres_db.authorize_pinned_thread_retirement(
                    thread_id,
                    token=str(retirement["token"]),
                    generation=str(retirement["generation"]),
                    settle_status=settle_status,
                ):
                    raise HTTPException(
                        status_code=409,
                        detail={"code": "pinned_retirement_authorization_refused"},
                    )
                retirement["authorized_at"] = True
                already_authorized = True

            # Authorization is append-only. Retries must replay these
            # idempotent obligations instead of skipping them after a crash.
            if settle_status == "ended" and not linked_officer_authorization:
                await _stand_down(
                    authoritative_thread,
                    converge_authorized=already_authorized,
                )
            authoritative_thread = (
                await postgres_db.get_thread(thread_id) or authoritative_thread
            )

            runtime_exposed = _retirement_context_runtime_exposed(retirement)
            local_quiescence = _retirement_has_exact_local_quiescence(
                retirement, authoritative_thread
            )
            if (
                runtime_exposed
                and not local_quiescence
                and _agent_pod_provision_intent_zero_candidate(
                    retirement, authoritative_thread
                )
            ):
                # The provision intent predates the Pod create effect and no
                # session owner ever bound. Observe/delete only its exact
                # attempt-labelled name, then receipt the durable absence.
                recovered_provision_intent = (
                    await _recover_agent_pod_provision_intent_zero(
                        retirement, authoritative_thread
                    )
                )
                if recovered_provision_intent:
                    authoritative_thread = (
                        await postgres_db.get_thread(thread_id) or authoritative_thread
                    )
                    local_quiescence = _retirement_has_exact_local_quiescence(
                        retirement, authoritative_thread
                    )
            if (
                runtime_exposed
                and not local_quiescence
                and _pre_registration_agent_pod_zero_candidate(
                    retirement, authoritative_thread
                )
            ):
                # Begin closed registration before this lifecycle lock was
                # acquired. A complete pre-registration Pod has no session
                # identity that can ACK, so End owns its exact UID stop and
                # atomically clears only that captured marker with the proof.
                recovered_pre_registration = (
                    await _recover_pre_registration_agent_pod_zero(
                        retirement, authoritative_thread
                    )
                )
                if recovered_pre_registration:
                    authoritative_thread = (
                        await postgres_db.get_thread(thread_id) or authoritative_thread
                    )
                    local_quiescence = _retirement_has_exact_local_quiescence(
                        retirement, authoritative_thread
                    )
            prior_soft_settlement = False
            if permanent and runtime_exposed and not local_quiescence:
                prior_soft_settlement = (
                    await postgres_db.pinned_thread_has_prior_soft_settlement(
                        thread_id,
                        runtime_generation=str(retirement["generation"]),
                        retirement_token=str(retirement["token"]),
                    )
                )
            raw_local_quiescence = authoritative_thread.get(
                "runtime_retirement_local_quiescence"
            )
            if isinstance(raw_local_quiescence, str):
                try:
                    raw_local_quiescence = json.loads(raw_local_quiescence)
                except (TypeError, ValueError):
                    raw_local_quiescence = None
            agent_local_quiescence = bool(
                local_quiescence
                and isinstance(raw_local_quiescence, Mapping)
                and raw_local_quiescence.get("quiescence_actor") == "agent"
            )
            context = retirement.get("context")
            context = {} if context is None else context
            captured_agent = (
                context.get("agent") if isinstance(context, Mapping) else None
            )
            captured_agent_pod = (
                context.get("agent_pod") if isinstance(context, Mapping) else None
            )
            captured_actor_shapes_valid = bool(
                all(
                    value is None or isinstance(value, Mapping)
                    for value in (captured_agent, captured_agent_pod)
                )
                and all(
                    not value
                    or (
                        str(value.get(name_key) or "")
                        and str(value.get("pod_uid") or "")
                    )
                    for value, name_key in (
                        (captured_agent, "hostname"),
                        (captured_agent_pod, "pod_name"),
                    )
                    if isinstance(value, Mapping)
                )
            )
            orchestrator_destructive_zero = bool(
                permanent
                and runtime_exposed
                and not local_quiescence
                and not prior_soft_settlement
                and isinstance(context, Mapping)
                and captured_actor_shapes_valid
                and str(context.get("entry_status") or "") == "ended"
                and not context.get("agent_id")
                and not context.get("runtime_attach_token")
                and authoritative_thread.get("agent_id") is None
                and authoritative_thread.get("runtime_attach_token") is None
                and authoritative_thread.get("control_admission_agent_id") is None
                and str(authoritative_thread.get("status") or "") == "ended"
            )
            if runtime_exposed and not (
                local_quiescence
                or prior_soft_settlement
                or orchestrator_destructive_zero
            ):
                # Owner End, offline recovery and a lost response may close
                # admission, but Pod absence/offline status is not proof that
                # tmux/nohup writers in the workspace stopped.  Return the
                # durable in-progress state without staging, snapshotting,
                # revoking or deleting anything.  The exact agent watchdog
                # performs strict local cleanup, appends the acknowledgement,
                # then retries this same immutable retirement.
                if local_runtime_quiesced:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": "pinned_local_quiescence_refused",
                            "message": (
                                "The exact local cleanup acknowledgement was "
                                "not persisted."
                            ),
                        },
                    )
                return {
                    "status": "ending",
                    "retirement_disposition": settle_status,
                    "retirement_permanent": bool(permanent),
                }

            try:
                staged_event: dict[str, Any] | None = None
                authoritative_metadata = thread_metadata_object(authoritative_thread)
                # A permanent delete intentionally discards both the runtime
                # and any pending review.  Do not spend minutes materialising
                # a potentially multi-gigabyte overlay only to delete its
                # thread/event rows immediately afterwards, and do not let an
                # unavailable staging backend wedge an otherwise-authorised
                # permanent deletion.  Soft End/Suspend must finish and
                # durably announce staging before settlement reopens Resume.
                if not permanent and authoritative_metadata.get("protected_cloud"):
                    from orchestrator.services.cloud_staging.stage import (
                        stage_thread_cloud_diff,
                        staging_manifest_key,
                    )

                    ro_row = await postgres_db.get_ro_mount_by_thread(thread_id)
                    receipt_present = (
                        authoritative_thread.get("runtime_retirement_stage_receipt")
                        is not None
                    )
                    receipt_valid, receipt_event = _retirement_stage_event_from_receipt(
                        retirement, authoritative_thread, ro_row
                    )
                    if receipt_present and not receipt_valid:
                        raise RuntimeError(
                            "protected retirement stage receipt is inconsistent"
                        )
                    if receipt_valid:
                        # A previous attempt crossed the sole visibility CAS;
                        # workspace/reader cleanup may already have happened.
                        # Reuse the exact receipt and perform no SSH or S3 IO.
                        staged_event = receipt_event
                    else:
                        stage_authority = _capture_cloud_stage_authority(
                            authoritative_thread, ro_row or {}
                        )
                        if stage_authority is None:
                            captured_ro = (retirement.get("context") or {}).get(
                                "protected_ro"
                            )
                            captured_summary = (
                                captured_ro.get("staged_summary")
                                if isinstance(captured_ro, Mapping)
                                else None
                            )
                            manifest_present = bool(
                                isinstance(captured_summary, dict)
                                and await snapshot_service.get_blob(
                                    staging_manifest_key(thread_id, captured_summary)
                                )
                                is not None
                            )
                            pre_staged = None
                            if manifest_present:
                                pre_staged = await postgres_db.publish_quiesced_retirement_existing_stage_receipt(
                                    thread_id,
                                    expected_runtime_generation=str(
                                        retirement["generation"]
                                    ),
                                    expected_retirement_token=str(retirement["token"]),
                                )
                            if pre_staged is None:
                                # A protected create may be ended before workspace
                                # attach or credential delivery.  An engaging (or
                                # fully probed active) reader grant is an external
                                # resource, not process exposure: exact-revoke its
                                # captured attempt before publishing the distinct
                                # zero-stage receipt.  This deliberately does not
                                # run the rest of cleanup before mandatory staging.
                                await _revoke_never_delivered_protected_reader(
                                    retirement,
                                    authoritative_thread,
                                    ro_row,
                                )
                                never_engaged = await postgres_db.publish_never_engaged_retirement_stage_receipt(
                                    thread_id,
                                    expected_runtime_generation=str(
                                        retirement["generation"]
                                    ),
                                    expected_retirement_token=str(retirement["token"]),
                                )
                                if never_engaged is None:
                                    raise RuntimeError(
                                        "protected retirement lacks exact staging authority"
                                    )
                            authoritative_thread = (
                                await postgres_db.get_thread(thread_id)
                                or authoritative_thread
                            )
                            receipt_valid, receipt_event = (
                                _retirement_stage_event_from_receipt(
                                    retirement,
                                    authoritative_thread,
                                    await postgres_db.get_ro_mount_by_thread(thread_id),
                                )
                            )
                            if not receipt_valid:
                                raise RuntimeError(
                                    (
                                        "pre-staged retirement receipt is inconsistent"
                                        if pre_staged is not None
                                        else "never-engaged retirement receipt is inconsistent"
                                    )
                                )
                            staged_event = receipt_event
                        else:
                            if str(
                                stage_authority.get("runtime_retirement_token") or ""
                            ) != str(retirement["token"]):
                                raise RuntimeError(
                                    "protected retirement lacks exact staging authority"
                                )
                            stage_result = await stage_thread_cloud_diff(
                                thread_id=thread_id,
                                postgres_db=postgres_db,
                                snapshot_service=snapshot_service,
                                authority=stage_authority,
                                vm_provisioner=vm_provisioner,
                            )
                            if stage_result is None or stage_result.get("skipped") in {
                                "authority_changed",
                                "no_active_mount",
                                "no_workspace",
                            }:
                                raise RuntimeError(
                                    "protected retirement staging remains retryable"
                                )
                            publication = stage_result.get("publication") or {}
                            if not isinstance(
                                publication.get("retirement_stage_receipt"), dict
                            ):
                                raise RuntimeError(
                                    "protected retirement staging has no durable receipt"
                                )
                            if isinstance(stage_result.get("event"), dict):
                                staged_event = dict(stage_result["event"])
                raw_agent_workspace_claim = (
                    context.get("agent_workspace_claim")
                    if isinstance(context, Mapping)
                    else None
                )
                agent_workspace_exit_handoff = bool(
                    permanent
                    and retiring_agent_response_pending
                    and runtime_exposed
                    and local_quiescence
                    and raw_agent_workspace_claim not in (None, {})
                )
                await _cleanup_pinned_thread_retirement(
                    retirement,
                    cleanup_agent_pod=(
                        not runtime_exposed
                        or (
                            permanent
                            and not retiring_agent_response_pending
                            and (
                                agent_local_quiescence
                                or prior_soft_settlement
                                or orchestrator_destructive_zero
                            )
                        )
                    ),
                    defer_agent_workspace_claim_until_caller_exit=(
                        agent_workspace_exit_handoff
                    ),
                )
                if agent_workspace_exit_handoff:
                    return _ending_response(retiring_agent_exit_authorized=True)
                if permanent:
                    await _delete_auxiliary_state(authoritative_thread)
                    await postgres_db.delete_thread(
                        thread_id,
                        expected_runtime_retirement_token=str(retirement["token"]),
                        expected_runtime_generation=str(retirement["generation"]),
                    )
                else:
                    settled = await postgres_db.settle_pinned_thread_retirement(
                        thread_id,
                        token=str(retirement["token"]),
                        generation=str(retirement["generation"]),
                        final_status=settle_status,
                        staged_event=staged_event,
                    )
                    if not settled:
                        raise RuntimeError("Pinned retirement settlement CAS failed")
                    if not await _complete_retiring_soft_warm_binding_release(
                        retirement
                    ):
                        # Settlement already moved the exact receipt to
                        # ``releasing``. The leader can retry that durable
                        # finalizer obligation, but this request must not claim
                        # the warm pool slot is available yet.
                        raise RuntimeError(
                            "Pinned retirement warm release remains retryable"
                        )
            except HTTPException:
                raise
            except Exception as exc:
                logger.exception(
                    "Pinned retirement remains retryable for thread %s", thread_id
                )
                raise HTTPException(
                    status_code=503,
                    detail={
                        "code": "pinned_retirement_retry_pending",
                        "message": "Runtime cleanup is incomplete; retry End.",
                    },
                ) from exc

        result: dict[str, Any] = {"status": "deleted" if permanent else settle_status}
        if include_officer_handoff:
            result["_officer_handoff"] = officer_handoff
        return result

    # Every stateless tier uses the queue lifecycle, including lite sessions.
    # The validator keeps VM/unknown tiers refused while admitting only the
    # narrowed sandbox and lite authority shapes.
    _require_stateless_end_workspace(thread)
    initial_stateless_authority = (
        await postgres_db.get_stateless_thread_lifecycle_authority(thread_id)
    )
    if initial_stateless_authority is None:
        raise HTTPException(status_code=409, detail="Thread lifecycle changed")
    try:
        async with postgres_db.stateless_session_workspace_ensure_lock(
            thread_id, wait=True
        ) as cleanup_owner:
            if not cleanup_owner:
                raise HTTPException(
                    status_code=503,
                    detail="Stateless workspace lifecycle lock unavailable",
                )
            fresh_thread = await postgres_db.get_thread(thread_id)
            if fresh_thread is None:
                return {"status": "deleted"}
            _require_stateless_end_workspace(fresh_thread)
            fresh_authority = (
                await postgres_db.get_stateless_thread_lifecycle_authority(thread_id)
            )
            if fresh_authority != initial_stateless_authority:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Thread lifecycle generation changed while waiting for "
                        "cleanup ownership"
                    ),
                )
            fresh_metadata = thread_metadata_object(fresh_thread)
            marker_pending = bool(
                "_stateless_workspace_retirement_pending" in fresh_metadata
            )
            fresh_status = fresh_thread.get("status")
            if (
                fresh_status != initial_status
                and not (permanent and fresh_status == "ended")
                and not marker_pending
            ):
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Thread lifecycle changed while waiting for cleanup ownership"
                    ),
                )

            result = await _reconcile_stateless_thread_retirement(
                thread_id,
                force=force,
                permanent=permanent,
            )
            if result.get("state") == "missing":
                return {"status": "deleted"}

            # These side effects are serialized after the fresh-state check;
            # a stale End can no longer mutate a thread that End->Resume reopened.
            await _stand_down(fresh_thread)
            if permanent:
                closure = result.get("closure") or {}
                terminal_thread = result.get("thread") or fresh_thread
                # The final transcript is the source of a separately leased
                # session-turn memory obligation. Retirement may remove the
                # runtime workspace, but permanent deletion must retain the
                # DB transcript/config until that obligation is terminal.
                # ``delete_thread`` repeats this under its row locks.
                if await postgres_db.has_unfinished_session_memory_effects(thread_id):
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            "Final-memory extraction is still pending; retry "
                            "permanent deletion after it settles"
                        ),
                    )
                terminal_metadata = thread_metadata_object(terminal_thread)
                terminal_binding = terminal_metadata.get("_workspace_binding") or {}
                terminal_workspace = terminal_metadata.get("workspace_container") or {}
                terminal_backing_id = (
                    closure.get("backing_id")
                    if isinstance(closure, dict) and closure.get("backing_id")
                    else (
                        terminal_binding.get("backing_id")
                        if isinstance(terminal_binding, dict)
                        else None
                    )
                )
                terminal_snapshot_exists = bool(
                    isinstance(closure, dict)
                    and (
                        closure.get("snapshot_restore_required") is True
                        or (
                            isinstance(terminal_workspace, dict)
                            and terminal_workspace.get("_snapshot_restore_required")
                            is True
                        )
                        or (str(terminal_backing_id or "").startswith("k8s-pod:"))
                    )
                )
                if terminal_snapshot_exists and not snapshot_service.is_available:
                    raise HTTPException(
                        status_code=503,
                        detail="Terminal workspace snapshot cleanup is unavailable",
                    )
                if (
                    snapshot_service.is_available
                    and not await snapshot_service.delete_snapshot(
                        thread_id,
                        entity_type="threads",
                    )
                ):
                    # The thread/queue tombstone remains retryable. Never
                    # delete the only ownership row while its terminal S3
                    # prefix may survive indefinitely.
                    raise HTTPException(
                        status_code=503,
                        detail="Terminal workspace snapshot cleanup is incomplete",
                    )
                if declared_thread_workspace_backend(terminal_thread) == "virtual":
                    from orchestrator.services.thread_uploads import (
                        purge_attested_stateless_virtual_workspace,
                    )

                    if not await purge_attested_stateless_virtual_workspace(
                        terminal_thread
                    ):
                        raise HTTPException(
                            status_code=503,
                            detail=("Terminal virtual workspace cleanup is incomplete"),
                        )
                from orchestrator.services.stateless_workspace_history_cleanup import (
                    reclaim_stateless_workspace_history,
                )

                if not await reclaim_stateless_workspace_history(
                    postgres_db, container_provisioner, thread_id
                ):
                    raise HTTPException(
                        status_code=503,
                        detail="Historical workspace permanent cleanup is incomplete",
                    )
                await _delete_auxiliary_state(fresh_thread)
                await postgres_db.delete_thread(thread_id)
                return {"status": "deleted"}
            return {"status": "ended"}
    except asyncio.TimeoutError as exc:
        raise HTTPException(
            status_code=503,
            detail="Stateless workspace lifecycle lock acquisition timed out",
        ) from exc


# Resume-time session-folder provisioning is fire-and-forget so /resume stays
# fast — but the agent reads its cloud config within ~150ms of attach, while
# provisioning needs several WebDAV round-trips (~5s measured). The attach won
# that race every time, so the agent read NULL handle columns, got
# ``cloud_sync_degraded``, and ran with ``workspace_sync = None`` for the
# session's WHOLE life (persistent_app.py has no rebuild path). Registering the
# task lets the attach paths await it instead of racing it.
# knowledge-history/done/session_resume_cloud_sync_race_late_provision.md
_late_cloud_setup_tasks: dict[str, "asyncio.Task[None]"] = {}

# Ceiling on how long an attach waits for in-flight session-folder
# provisioning. Comfortably above the ~5s observed cost, low enough that a
# wedged cloud delays a resume rather than hanging it — on timeout we fall
# through to the pre-fix behaviour (attach, possibly degraded).
LATE_CLOUD_SETUP_ATTACH_TIMEOUT_S = 15


def _register_late_cloud_setup(thread_id: str, task: "asyncio.Task[None]") -> None:
    """Publish an in-flight session-folder provisioning task for the attach
    paths to await (see ``_await_late_cloud_setup``).

    Mirrors ``_schedule_protected_engage``'s slot discipline: the done-callback
    only clears the slot while it is still ours, so a newer registration for
    the same thread can't be clobbered by a stale callback.
    """
    _late_cloud_setup_tasks[thread_id] = task

    def _done(finished: "asyncio.Task[None]") -> None:
        if _late_cloud_setup_tasks.get(thread_id) is finished:
            _late_cloud_setup_tasks.pop(thread_id, None)

    task.add_done_callback(_done)


async def _await_late_cloud_setup(thread_id: str) -> None:
    """Block until this thread's in-flight session-folder provisioning lands.

    Call this BEFORE binding an agent and OUTSIDE the thread advisory lock —
    it can take seconds, and holding the lock across it would stall the fresh
    pod's own ``POST /api/agents/register``.

    A no-op when nothing is registered for ``thread_id`` in this process:
    provisioning already finished, was never needed, or ran on the other HA
    replica. The cross-replica case doesn't strand the agent — the replica
    that schedules the task is also the one that attaches, so the handle is
    persisted before the attach POST goes out and every later reader (either
    replica) sees it through the DB.
    """
    task = _late_cloud_setup_tasks.get(thread_id)
    if task is None:
        return
    try:
        await asyncio.wait_for(
            asyncio.shield(task), timeout=LATE_CLOUD_SETUP_ATTACH_TIMEOUT_S
        )
    except Exception as e:
        logger.warning(
            "Thread %s: awaiting in-flight cloud session-folder provisioning "
            "failed/timed out (%s); attaching anyway — the session may start "
            "with cloud sync degraded.",
            thread_id,
            e,
        )


class ThreadResumeRequest(BaseModel):
    """Optional body for POST /resume. ``acknowledge`` carries the drift item
    ids the user accepted losing."""

    acknowledge: list[str] | None = None


async def _thread_config_drift(
    thread: dict[str, Any],
    metadata: dict[str, Any],
    *,
    owner: dict[str, Any] | None,
) -> list[DriftItem]:
    """Everything in this thread's stored config that is no longer usable.

    Runs the same classifiers the enforcers wrap, so the dialog can never
    promise something different from what attach will do.

    ``owner`` MUST be the thread's own owner row (looked up from
    ``thread["user_id"]``), never the caller. ``require_thread_owner`` lets
    admins act on threads they do not own, and admins pass every classify_*
    check — passing the caller through would silently report no drift for
    someone else's drifted thread, resume it anyway with no ack recorded,
    and leave the real owner permanently stuck (attach enforces against the
    true owner and refuses, and the cockpit only offers Resume while status
    is ``ended``). ``None`` means a userless internal/system thread: trusted
    exactly like :func:`_revalidate_thread_project_ids` /
    :func:`_revalidate_thread_datasource_selection` treat one, since there is
    no per-user membership or grant that could have drifted.
    """
    thread_id = str(thread["id"])
    if owner is None:
        return []
    project_ids = await _thread_project_ids(thread_id)
    project_verdicts = await _classify_thread_project_ids(owner, project_ids)
    allowed_project_ids = [v.project_id for v in project_verdicts if not v.denied]

    datasource_verdicts, _revisions = await classify_datasource_selection(
        postgres_db,
        owner,
        str(owner["id"]),
        metadata.get("datasource_ids"),
        allowed_project_ids,
        None,
        allow_admin_explicit_override=True,
    )

    # workspace_tier / corrupt_revision cannot be acknowledged away (no user
    # action makes either safe), so collect_config_drift below never turns
    # either into a DriftItem — but both still deny at attach. Resuming past
    # them would return 200 and hang at attach, the exact failure shape this
    # feature exists to remove. Refuse here, before any grant probing or
    # status mutation, and without naming which item (same non-enumeration
    # reasoning as the generic denial raised elsewhere on this path).
    if blocking_denials(datasource_verdicts, project_verdicts):
        raise HTTPException(
            status_code=403,
            detail=(
                "This session's configuration cannot be verified and cannot "
                "be resumed. Its connector or project data is invalid rather "
                "than merely unavailable."
            ),
        )

    # Grants are enforced inside the session resolve; run it purely to harvest
    # the violations it would raise at attach.
    status: dict[str, Any] = {}
    try:
        await _resolve_session_config(thread, metadata, status=status)
    except GrantDenied:
        # Expected: this is exactly the signal we came here to harvest.
        pass
    except Exception as exc:
        # We could not determine whether grants drifted. Reporting "no drift"
        # would let the session resume on an unknown state; fail closed with
        # the same generic denial the endpoint used before this feature.
        logger.exception(
            "Thread %s: grant probe failed during drift collection; "
            "refusing to resume on an unknown state",
            thread_id,
        )
        raise HTTPException(
            status_code=403,
            detail="Session configuration could not be verified",
        ) from exc
    grant_violations = status.get("grant_violations") or []

    deleted_ids = [
        v.datasource_id
        for v in datasource_verdicts
        if v.denied and v.reason == "deleted"
    ]
    tombstones = await postgres_db.get_datasource_tombstones(deleted_ids)

    return await collect_config_drift(
        postgres_db,
        thread,
        owner=owner,
        project_ids=project_verdicts,
        datasource_ids=datasource_verdicts,
        grant_violations=grant_violations,
        tombstones=tombstones,
    )


@app.post("/api/persistent/threads/{thread_id}/resume")
async def resume_thread(
    thread_id: str,
    request: Request,
    body: ThreadResumeRequest | None = None,
) -> dict[str, Any]:
    """Resume an ended thread (auth: owner only).

    Resets thread status to 'created' and clears the stale agent_id so that
    a new agent can pick it up. The frontend navigates to the chat page after
    calling this, where the orchestrator will provision or wait for an agent.

    Drifted config (deleted/revoked connectors or projects, withdrawn grants)
    is reported as 428 rather than silently denied; the caller re-POSTs with
    ``acknowledge`` naming the drift ids it accepts losing. See
    knowledge-history/done/session_config_drift_resume.md.
    """
    user, thread = await require_thread_owner(request, postgres_db, thread_id)
    require_srw_runtime(thread)
    from shared.run_queue import LANE_PINNED, LANE_STATELESS

    execution_lane = thread.get("execution_lane")
    if execution_lane == LANE_STATELESS:
        # Resume is topology-neutral for a queue-served thread: validate the
        # workspace/class before mutating, then reset lifecycle state without
        # binding or provisioning a dedicated agent below.
        _require_stateless_workspace(thread)
    elif execution_lane != LANE_PINNED:
        # Unknown future lanes must never inherit either current control plane.
        raise HTTPException(
            status_code=409,
            detail="Session execution lane does not support resume",
        )
    if thread.get("status") != "ended":
        if (
            execution_lane == LANE_PINNED
            and thread.get("runtime_retirement_token") is not None
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "session_ending",
                    "message": (
                        "This session is still finishing protected runtime "
                        "cleanup. Resume becomes available after settlement."
                    ),
                },
            )
        raise HTTPException(
            status_code=409,
            detail={
                "code": "session_not_ended",
                "message": "This session has already resumed.",
            },
        )

    metadata = thread.get("metadata") or {}
    if isinstance(metadata, str):
        try:
            metadata = json.loads(metadata)
        except (json.JSONDecodeError, TypeError):
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "session_metadata_malformed",
                    "message": "This session's stored state is invalid.",
                },
            )
    protected_marker = protected_cloud_marker_state(metadata)
    if protected_marker == "malformed":
        raise HTTPException(
            status_code=409,
            detail={
                "code": "protected_cloud_malformed",
                "message": "Protected cloud session state is invalid.",
            },
        )
    if protected_marker == "on" and _thread_workspace_backend(thread) != "sandbox":
        raise HTTPException(
            status_code=409,
            detail={
                "code": "protected_cloud_unsupported_workspace",
                "message": "Protected cloud sessions require the Container tier.",
            },
        )
    # A legacy ended row may predate create-time materialization of the
    # effective Officer class.  Resolve and reject it before any drift ACK or
    # lifecycle write so a failed resume remains exactly ended.
    await _require_supported_protected_session_class(thread, metadata)
    # Drift must be computed as the THREAD OWNER, never the caller (`user`):
    # require_thread_owner lets admins through for threads they do not own,
    # and admins pass every classify_* check — see _thread_config_drift's
    # docstring for the failure this produced. Same owner lookup and
    # fail-closed-on-missing-row as _revalidate_thread_project_ids.
    owner_id = thread.get("user_id")
    if owner_id:
        owner = await postgres_db.get_user(str(owner_id))
        if owner is None:
            raise HTTPException(
                status_code=403,
                detail="Session configuration could not be verified",
            )
    else:
        owner = None
    # Validation stays ahead of mutation: a thread that cannot resume must not
    # be left half-resumed. Compute drift and raise 428 BEFORE touching the
    # thread's status, same discipline the old revalidate-and-raise calls had.
    drift = await _thread_config_drift(thread, metadata, owner=owner)
    # The ack is durable (spec §3.2): a PRIOR resume already persisted it to
    # metadata.config_drift_ack (below), so it must count here too, not just
    # whatever this particular request body happens to carry — otherwise an
    # item the user already accepted losing is re-reported as outstanding on
    # every subsequent resume. Union, never replace: a genuinely NEW drift
    # id is in neither set, so it still blocks.
    stored_ack = acknowledged_drift_ids(thread.get("metadata"))
    acknowledged = (set(body.acknowledge or []) if body else set()) | stored_ack
    outstanding = {item.id for item in drift} - acknowledged
    if outstanding:
        # Subset, not equality: an item that RECOVERED between prompt and
        # confirm must not force a pointless re-prompt, while an item that
        # newly drifted is never silently acknowledged.
        raise HTTPException(
            status_code=428,
            detail={
                "code": "config_drift",
                "detail": (
                    "Parts of this session's configuration are no longer available"
                ),
                "drift": [
                    {
                        "id": item.id,
                        "kind": item.kind,
                        "reason": item.reason,
                        "label": item.label,
                    }
                    for item in drift
                ],
            },
        )

    if drift:
        await postgres_db.record_thread_config_drift_ack(
            thread_id, {item.id: item.reason for item in drift}
        )

    if execution_lane == LANE_STATELESS:
        try:
            async with postgres_db.stateless_session_workspace_ensure_lock(
                thread_id, wait=True
            ) as resume_owner:
                if not resume_owner:
                    raise HTTPException(
                        status_code=503,
                        detail="Stateless workspace lifecycle lock unavailable",
                    )
                locked_thread = await postgres_db.get_thread(thread_id)
                if not locked_thread:
                    raise HTTPException(status_code=404, detail="Thread not found")
                _require_stateless_workspace(locked_thread)
                locked_metadata = thread_metadata_object(locked_thread)
                if locked_thread.get("status") != "ended":
                    raise HTTPException(
                        status_code=409,
                        detail="Thread lifecycle changed before resume",
                    )
                if "_stateless_workspace_retirement_pending" in locked_metadata:
                    try:
                        marker = _stateless_retirement_marker(locked_thread)
                    except RuntimeError as exc:
                        raise HTTPException(
                            status_code=503,
                            detail="Stateless retirement authority is malformed",
                        ) from exc
                    if marker.get("permanent") is True:
                        raise HTTPException(
                            status_code=409,
                            detail="A permanent thread deletion is still in progress",
                        )
                # Reconcile every ended stateless row, not only explicit
                # in-progress markers. Legacy/pre-protocol rows may be ended
                # while a Ready workspace and shell still exist; reopening one
                # without a terminal ACK would bypass the lifecycle fence.
                await _reconcile_stateless_thread_retirement(
                    thread_id,
                    force=True,
                    permanent=False,
                )
                locked_thread = await postgres_db.get_thread(thread_id)
                if not locked_thread:
                    raise HTTPException(status_code=404, detail="Thread not found")
                locked_metadata = thread_metadata_object(locked_thread)
                if "_stateless_workspace_retirement_pending" in locked_metadata:
                    raise HTTPException(
                        status_code=503,
                        detail="Stateless workspace retirement remains incomplete",
                    )
                if not await postgres_db.resume_thread(thread_id):
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            "Thread could not be resumed while workspace cleanup is active"
                        ),
                    )
                thread = await postgres_db.get_thread(thread_id) or locked_thread
                metadata = thread_metadata_object(thread)
        except asyncio.TimeoutError as exc:
            raise HTTPException(
                status_code=503,
                detail="Stateless workspace lifecycle lock acquisition timed out",
            ) from exc
    elif not await postgres_db.resume_thread(thread_id):
        raise HTTPException(
            status_code=409,
            detail="Thread could not be resumed while workspace cleanup is active",
        )

    # The pre-resume owner snapshot is terminal by construction. Every
    # provisioning decision below must use the exact row reopened by the
    # explicit ended->created transaction.
    thread = await postgres_db.get_thread(thread_id)
    resume_runtime_authority = thread_runtime_authority(thread)
    if resume_runtime_authority is None:
        raise HTTPException(
            status_code=409, detail=thread_runtime_refusal_detail(thread)
        )
    metadata = thread_metadata_object(thread)

    async def _resume_runtime_is_current() -> bool:
        return same_thread_runtime_authority(
            await postgres_db.get_thread(thread_id), resume_runtime_authority
        )

    # Reopening a conference re-establishes the officer's hold (centurion.md
    # §4) — the single-writer rule spans the meeting's whole lifetime, not
    # just its first sitting.
    if _thread_is_conference(thread) and thread.get("project_id"):
        await _hold_officer_for_conference(str(thread["project_id"]), thread_id)

    # F-I2: the Slice A reconciler revokes cloud_ro_mounts grants of ended
    # threads, so an end -> resume cycle would otherwise leave a
    # protected-marked thread permanently mount-less. Re-engage here
    # whenever there's no ACTIVE grant on record — via the same registry
    # ``_schedule_protected_engage`` uses at create, so a concurrent attach
    # can await this task exactly like it would the create-time one.
    if (
        protected_cloud_marker_state(metadata) == "on"
        and _is_protected_cloud_mode_enabled()
    ):
        ro_row = await postgres_db.get_ro_mount_by_thread(thread_id)
        if not ro_row or ro_row.get("status") != "active":
            resume_mount_rows = await postgres_db.list_thread_mounts(thread_id)
            _schedule_protected_engage(
                thread_id,
                user_id=str(user["id"]),
                mount_rows=resume_mount_rows,
                runtime_generation=resume_runtime_authority.generation,
            )

    # Provision cloud session folder if missing (e.g. session was created
    # before the cloud backend was initialized), or retry the share alone
    # if the folder exists but no share_handle was recorded — this unstucks
    # threads where folder creation raced the user's first browser login.
    existing_session_handle = thread.get("main_cloud_session_handle") or thread.get(
        "nc_session_folder"
    )
    needs_share_only = bool(existing_session_handle) and not thread.get(
        "main_cloud_share_handle"
    )
    # Phase 4: if the thread already has a working mount, skip the
    # late-provision branch — the mount is the user-visible cloud surface
    # and a session folder on top would be redundant. The share-retry
    # branch is untouched: it only fires on existing folders, so it
    # remains the recovery path for old session folders that lost their
    # share record.
    try:
        existing_mounts = await postgres_db.list_thread_mounts(thread_id)
    except Exception as e:
        existing_mounts = []
        logger.warning(
            "Thread %s: failed to read thread_mounts during resume late-provision "
            "check (%s); proceeding with default policy.",
            thread_id,
            e,
        )
    needs_full_provision = (
        not existing_session_handle
        and not thread.get("nc_session_folder")
        and not _should_skip_session_folder(existing_mounts)
    )
    if protected_cloud_marker_state(metadata) == "on":
        # Protected sessions use the project reader + overlay exclusively.
        # Never provision/share the legacy live session folder on resume.
        needs_full_provision = False
        needs_share_only = False

    if needs_full_provision or needs_share_only:

        async def _late_cloud_setup(
            tid: str, usr: dict, existing_handle: str | None
        ) -> None:
            if not await _resume_runtime_is_current():
                return
            # This thread already exists and carries its origin backend in
            # main_cloud_backend. Dispatch via for_thread so a
            # later active-backend swap can't re-provision it on the wrong
            # cloud (Issue 16). Mirrors the delete path above (~:12339).
            backend = main_cloud_router.for_thread(thread)
            if not backend.is_initialized and backend.is_configured:
                await backend.ensure_initialized()
                if not await _resume_runtime_is_current():
                    return
            if not backend.is_initialized:
                return
            try:
                if existing_handle:
                    session_handle = SessionFolderHandle.from_db(
                        existing_handle, backend=backend.backend_id
                    )
                else:
                    session_handle = await backend.ensure_session_folder(
                        session_id=tid[:8]
                    )
                    if not await _resume_runtime_is_current():
                        return
                share_handle = None
                resolved_user_id = await resolve_user_identity_cached(
                    postgres_db, usr, backend
                )
                if not await _resume_runtime_is_current():
                    return
                if resolved_user_id:
                    share_handle = await backend.share_session_folder(
                        session_handle, resolved_user_id
                    )
                    if not await _resume_runtime_is_current():
                        return
                if not share_handle and existing_handle:
                    # Share still failed (user hasn't signed into cloud yet).
                    # Don't persist — leaving share_handle NULL lets the next
                    # resume retry once autoprovision has materialised them.
                    return
                if not await postgres_db.update_thread_main_cloud(
                    tid,
                    backend_id=backend.backend_id,
                    backend_instance_id=str(backend.backend_instance_id),
                    session_handle=session_handle.to_db(),
                    share_handle=share_handle.to_db() if share_handle else None,
                    expected_runtime_generation=resume_runtime_authority.generation,
                ):
                    return
                logger.info(
                    "Thread %s: %s cloud session folder",
                    tid,
                    "shared previously-unshared"
                    if existing_handle
                    else "late-provisioned",
                )
            except Exception as e:
                logger.warning(
                    "Thread %s: late cloud folder provisioning failed: %s", tid, e
                )

        _setup_task = asyncio.create_task(
            _late_cloud_setup(thread_id, user, existing_session_handle)
        )
        if needs_full_provision:
            # Only a FULL provision decides whether the agent can resolve a
            # sync target at all, so only that case is worth making the attach
            # wait. The share-only retry leaves both handle columns untouched
            # — gating on it would add its cloud user-lookup cost to every
            # resume of a thread whose share never landed (i.e. every thread
            # whose owner has not signed into the cloud yet) for no change in
            # what the agent can resolve.
            _register_late_cloud_setup(thread_id, _setup_task)

    # Only the exact pinned lane receives a registered agent. Queue-served
    # sessions restore/recreate their workspace below and wait for user input
    # to create the next run_queue turn.
    if execution_lane == LANE_PINNED and agent_provisioner.is_available:
        config_name = canonical_config_name(thread.get("config_name", "session_base"))

        async def _reprovision(tid: str, cfg: str) -> None:
            """Bind an agent to the resumed thread. Fire-and-forget.

            The whole body is guarded because this runs as its own task after
            the handler returned 200. An exception here — a config_name the
            provisioner boundary refuses, a K8s outage — is otherwise dropped
            by asyncio and the session never becomes ready and never fails.
            Same recording shape as services/provision_or_assign.py.
            """
            try:
                # Let any in-flight session-folder provisioning land before an
                # agent is bound — the agent reads its cloud config within ~150ms
                # of attach and never re-reads. Outside the advisory lock below:
                # this can take seconds and the fresh pod's /register needs that
                # same lock.
                # knowledge-history/done/session_resume_cloud_sync_race_late_provision.md
                await _await_late_cloud_setup(tid)
                if not await _resume_runtime_is_current():
                    return
                if not await _await_protected_cloud_runtime_ready(tid):
                    return
                if not await _resume_runtime_is_current():
                    return

                # Serialise concurrent provisioning attempts for the same
                # thread (knowledge-base/knowledge/issues/persistent_thread_double_provisioning_race.md).
                # A concurrent /prepare or /resume on the same thread blocks
                # here; the second arrival observes the binding written by
                # the first and exits. Lifecycle SSE events for the cockpit's
                # resume progress card come from /api/sessions/{tid}/prepare,
                # which the cockpit drives in parallel with this endpoint.
                async with postgres_db.thread_advisory_lock(tid):
                    cur = await postgres_db.get_thread(tid)
                    if not _thread_uses_pinned_execution(
                        cur
                    ) or not same_thread_runtime_authority(
                        cur, resume_runtime_authority
                    ):
                        logger.warning(
                            "Thread %s: resume reprovision refused for execution lane %r",
                            tid,
                            cur.get("execution_lane") if cur else None,
                        )
                        return
                    if cur and cur.get("agent_id"):
                        logger.info(
                            "Thread %s: already bound to agent %s — "
                            "skipping duplicate reprovision.",
                            tid,
                            cur["agent_id"],
                        )
                        return

                    # Try idle pool agent first (instant attach, no pod boot).
                    idle_agent = await _find_idle_persistent_agent()
                    cur = await postgres_db.get_thread(tid)
                    if not same_thread_runtime_authority(cur, resume_runtime_authority):
                        return
                    if idle_agent:
                        # config_override lives in metadata (no top-level column) and
                        # is stripped of secrets at rest — re-inject from source so the
                        # attach payload carries the agent's keys. Needed in addition
                        # to the workspace-endpoint re-inject because datasource
                        # sessions make `co` truthy, suppressing the agent's
                        # fetch-fallback (persistent_app.py).
                        md = cur.get("metadata") or {}
                        if isinstance(md, str):
                            try:
                                md = json.loads(md)
                            except (json.JSONDecodeError, TypeError):
                                md = {}
                        co = (
                            (md.get("config_override") or {})
                            if isinstance(md, dict)
                            else {}
                        )
                        pids = await _thread_project_ids(tid)
                        include_kb_profile = await _thread_has_knowledge_scope(
                            project_ids=pids,
                            datasource_ids=(
                                md.get("datasource_ids")
                                if isinstance(md, dict)
                                else None
                            ),
                        )
                        co = await _inject_thread_dispatch_credentials(
                            co,
                            user_id=str(cur["user_id"]) if cur.get("user_id") else None,
                            project_id=str(cur["project_id"])
                            if cur.get("project_id")
                            else None,
                            include_kb_profile=include_kb_profile,
                        )
                        # The attach boundary owns the authoritative datasource
                        # re-read. Passing a pre-resolved payload here recreated
                        # credentials from a stale A selection after an A -> B/[]
                        # live edit. Canonical project IDs come from thread_mounts,
                        # never the obsolete thread.project_ids field.
                        ok = await _send_session_attach(
                            idle_agent,
                            tid,
                            co,
                            pids,
                            datasources=None,
                            config_name=cfg,
                            expected_runtime_generation=(
                                resume_runtime_authority.generation
                            ),
                        )
                        if ok:
                            logger.info(
                                "Thread %s: resumed via idle pool agent %s",
                                tid,
                                idle_agent["hostname"],
                            )
                            return

                        # The attach attempt crossed await points.  Do not trust
                        # the snapshot from before it: a lane transition or a
                        # sibling bind must suppress the dedicated-pod fallback.
                        cur = await postgres_db.get_thread(tid)
                        if not _thread_uses_pinned_execution(
                            cur
                        ) or not same_thread_runtime_authority(
                            cur, resume_runtime_authority
                        ):
                            logger.warning(
                                "Thread %s: resume pod fallback refused for "
                                "execution lane %r",
                                tid,
                                cur.get("execution_lane") if cur else None,
                            )
                            return
                        if cur.get("agent_id"):
                            logger.info(
                                "Thread %s: attach reservation lost to agent %s; "
                                "skipping duplicate pod fallback",
                                tid,
                                cur["agent_id"],
                            )
                            return

                    # No idle agent — create a dedicated session pod.
                    pod_name = await agent_provisioner.provision_agent(
                        purpose="session",
                        thread_id=tid,
                        config_name=cfg,
                        expected_runtime_generation=(
                            resume_runtime_authority.generation
                        ),
                    )
                    if pod_name:
                        return

                    logger.error(
                        "Thread %s: resume failed — no idle agents and pod provisioning failed",
                        tid,
                    )
            except Exception as exc:
                logger.exception("Thread %s: resume reprovision failed: %s", tid, exc)
                await _emit_session_provisioning_failure(
                    tid,
                    str(thread.get("user_id") or "") or None,
                    resume_runtime_authority,
                    str(exc),
                )

        asyncio.create_task(_reprovision(thread_id, config_name))
    elif execution_lane == LANE_PINNED and persistent_provisioner.is_available:
        config_name = canonical_config_name(thread.get("config_name", "session_base"))

        async def _reprovision_legacy(tid: str, cfg: str) -> None:
            """Legacy dedicated-pod resume. Fire-and-forget, so guarded whole.

            Same reasoning as ``_reprovision`` above: a raise inside a detached
            task is swallowed and the session hangs in "provisioning" forever.
            """
            try:
                if not await _resume_runtime_is_current():
                    return
                if not await _await_protected_cloud_runtime_ready(tid):
                    return
                if not await _resume_runtime_is_current():
                    return
                cur = await postgres_db.get_thread(tid)
                if not _thread_uses_pinned_execution(
                    cur
                ) or not same_thread_runtime_authority(cur, resume_runtime_authority):
                    logger.warning(
                        "Thread %s: legacy resume provisioning refused for "
                        "execution lane %r",
                        tid,
                        cur.get("execution_lane") if cur else None,
                    )
                    return
                result = await persistent_provisioner.create_agent_pod(
                    tid,
                    config_name=cfg,
                    expected_runtime_generation=resume_runtime_authority.generation,
                )
                if not await _resume_runtime_is_current():
                    return
                if not result.usable:
                    logger.warning(
                        "Thread %s: legacy persistent resume is %s (%s)",
                        tid,
                        result.status.value,
                        result.failure_class or "no-detail",
                    )
                    await _emit_session_provisioning_failure(
                        tid,
                        str(thread.get("user_id") or "") or None,
                        resume_runtime_authority,
                        f"legacy persistent resume {result.status.value}"
                        f" ({result.failure_class or 'no-detail'})",
                    )
            except Exception as exc:
                logger.exception(
                    "Thread %s: legacy resume reprovision failed: %s", tid, exc
                )
                await _emit_session_provisioning_failure(
                    tid,
                    str(thread.get("user_id") or "") or None,
                    resume_runtime_authority,
                    str(exc),
                )

        asyncio.create_task(_reprovision_legacy(thread_id, config_name))

    # Ensure the session workspace is provisioned/restored (idempotent): restores
    # a suspended workspace, recreates a failed/missing one. Fire-and-forget so
    # resume stays fast — the agent tolerates a not-yet-ready workspace and the
    # periodic reconcile retries on failure. Queue-served sessions share the
    # input/poll single-flight so a rapid resume + input cannot spawn competing
    # create/adopt operations.
    if execution_lane == LANE_STATELESS:
        _schedule_stateless_workspace_ensure(thread_id)
    else:

        async def _ensure_resumed_workspace() -> None:
            if not await _resume_runtime_is_current():
                return
            await ensure_session_workspace(
                thread_id,
                db=postgres_db,
                provisioner=container_provisioner,
                suspension=workspace_suspension_service,
                expected_runtime_generation=resume_runtime_authority.generation,
            )

        asyncio.create_task(_ensure_resumed_workspace())

    return {"status": "created", "thread_id": thread_id}


class ThreadRewindRequest(BaseModel):
    """Body for POST /api/agents/threads/{id}/rewind (detached sessions)."""

    message_id: str
    mode: str = "conversation"


@app.post("/api/agents/threads/{thread_id}/rewind")
async def rewind_thread_detached(
    thread_id: str,
    request: Request,
    body: ThreadRewindRequest,
) -> dict[str, Any]:
    """Rewind a DETACHED session's transcript (auth: owner only).

    knowledge-base/knowledge/features/session_rewind.md §Flow — detached. Conversation mode
    only: file restore needs the agent that holds the workspace, so live
    sessions rewind through the session WebSocket instead, and code modes
    here answer 400 ("resume first"). A bound agent means the in-memory
    authority is live and a DB-only sweep would diverge it → 409.
    """
    user, thread = await require_thread_owner(request, postgres_db, thread_id)
    from shared.run_queue import LANE_STATELESS

    if thread.get("execution_lane") == LANE_STATELESS:
        # Stateless threads intentionally have agent_id=NULL even while their
        # session_turn is queued/leased.  This detached DB-only workflow has no
        # queue/turn fence and can race a live claimant, so fail closed until
        # rewind is modeled as a durable stateless control request.
        raise HTTPException(
            status_code=409,
            detail="Stateless session rewind requires a connected session",
        )
    # mark_orphaned_threads_ended and agent_update_thread_status's ended
    # branch both leave a stale agent_id on real ended threads — status must
    # gate the check too, mirroring update_thread_config's established
    # "connected" predicate, or every ended thread would 409 forever.
    if thread.get("agent_id") and thread.get("status") not in ("suspended", "ended"):
        raise HTTPException(
            status_code=409,
            detail="Session is live — rewind from the session connection",
        )
    if body.mode != "conversation":
        raise HTTPException(
            status_code=400,
            detail="File restore needs a running session — resume it first, "
            "then rewind from the chat",
        )
    row = await postgres_db.get_live_thread_message(thread_id, body.message_id)
    if row is None:
        raise HTTPException(
            status_code=404,
            detail="Message not found (it may already be rewound)",
        )
    if row["role"] != "human":
        raise HTTPException(
            status_code=400, detail="Rewind targets must be user messages"
        )
    result = await postgres_db.apply_thread_rewind(
        thread_id, from_seq=row["seq"], actor=str(user["id"])
    )
    return {
        "rewind_id": result["rewind_id"],
        "swept": result["swept"],
        "prompt": row["content"] or "",
    }


@app.get("/api/persistent/threads/{thread_id}/citations")
async def get_thread_citations(
    thread_id: str,
    request: Request,
    limit: int = Query(default=200, ge=1, le=500),
    offset: int = Query(default=0, ge=0),
) -> dict[str, Any]:
    """List citations created in a persistent session, for inline ``[N]`` rendering.

    The citation engine stores a session's citations with ``job_id = thread_id``
    (it maps ``CitationContext.session_id`` → ``job_id``), so the thread UUID *is*
    the ``job_id`` — there is no separate thread column. Owner-only (the by-job
    endpoint 404s for a thread since no ``jobs`` row exists). The marker the agent
    emits is the citation ``id``; the cockpit renumbers for display and resolves
    each ``[id]`` to a row returned here.
    """
    await require_thread_owner(request, postgres_db, thread_id)
    try:
        async with vector_db.acquire() as conn:
            count_row = await conn.fetchrow(
                "SELECT COUNT(*) AS total FROM citations WHERE job_id = $1::uuid",
                thread_id,
            )
            total = count_row["total"] if count_row else 0
            rows = await conn.fetch(
                """SELECT c.id, LEFT(c.claim, 300) AS claim, c.source_id,
                       s.name AS source_name, s.type::text AS source_type,
                       s.identifier AS source_identifier,
                       c.verification_status::text AS verification_status,
                       c.confidence::text AS confidence,
                       c.created_at, s.metadata
                FROM citations c
                JOIN sources s ON c.source_id = s.id
                WHERE c.job_id = $1::uuid
                ORDER BY c.id ASC
                LIMIT $2 OFFSET $3""",
                thread_id,
                limit,
                offset,
            )
            citations = []
            for r in rows:
                d = dict(r)
                # Cloud-document citations (cite_document with a snapshot-anchor)
                # can offer "view original" (/snapshot) + on-view drift (/drift);
                # web citations have neither. Surface the two flags so the cockpit
                # only renders those controls where they apply. The raw metadata
                # isn't returned (internal blob keys / anchor URLs).
                cloud = citations_operations._source_cloud_meta(d.pop("metadata", None))
                d["has_cloud_anchor"] = bool(cloud)
                d["has_snapshot"] = bool(cloud.get("snapshot_blob_key"))
                citations.append(d)
            return {
                "citations": citations,
                "total": total,
                "thread_id": thread_id,
            }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


def _stamp_tool_categories(messages: list[dict[str, Any]]) -> None:
    """Annotate replayed tool calls with their registry category, in place.

    The live SSE ``tool.started`` frame carries ``category`` (see graph.py's
    ``_get_tool_category``), but the stored ``thread_messages.tool_calls`` JSONB
    never did. Without this the cockpit's folded-chip summary buckets every
    replayed call as "other", so one turn reads
    "19× citations · 12× searches" while streaming and "38× steps" after a
    reload — same turn, same data, different answer.

    Derived at read time rather than persisted so that re-categorising a tool
    doesn't need a backfill of historical rows. Unknown tools (renamed, removed,
    or from another deployment) simply get no category and fall back to the
    cockpit's "other" bucket, which is the honest answer.
    """
    for m in messages:
        for tc in m.get("tool_calls") or []:
            category = TOOL_REGISTRY.get(tc.get("name") or "", {}).get("category")
            if category:
                tc["category"] = category


@app.get("/api/persistent/threads/{thread_id}/messages")
async def get_thread_messages_history(
    thread_id: str,
    request: Request,
    limit: Optional[int] = None,
    before: Optional[str] = None,
    after: Optional[str] = None,
    offset: int = 0,
) -> dict[str, Any]:
    """Load message history for a persistent thread, ascending (chronological).

    Default (no params) returns the **entire** conversation — the cockpit caches
    the full thread client-side and windows the render itself, so the display
    must not be truncated. Cursor paging (mutually exclusive, ISO-8601):

    - ``before=<ts>``: backfill — newest messages at-or-before the cursor, up to
      ``limit``.
    - ``after=<ts>``:  catch-up — messages at-or-after the cursor, up to ``limit``.

    A bare ``limit`` with no cursor keeps the legacy oldest-first paged read
    (``offset`` honored) used by the MCP inspection tool. Returns
    ``{messages, total, has_more, thread_id}``.
    """
    user, thread = await require_thread_owner(request, postgres_db, thread_id)

    def _parse_cursor(value: Optional[str]) -> Optional[datetime]:
        if not value:
            return None
        try:
            return datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError:
            raise HTTPException(
                status_code=400, detail=f"Invalid ISO-8601 timestamp: {value!r}"
            )

    before_dt = _parse_cursor(before)
    after_dt = _parse_cursor(after)
    if before_dt is not None and after_dt is not None:
        raise HTTPException(
            status_code=400, detail="Pass at most one of 'before' / 'after'"
        )

    capped_limit = min(limit, 500) if limit is not None else None

    if before_dt is not None or after_dt is not None:
        messages, has_more = await postgres_db.get_thread_messages_page(
            thread_id=thread_id,
            before=before_dt,
            after=after_dt,
            limit=capped_limit,
        )
        # A cursor window carries no cheap true total; no consumer reads it here.
        total = len(messages)
    else:
        messages = await postgres_db.get_thread_messages_history(
            thread_id=thread_id,
            limit=capped_limit,
            offset=offset,
        )
        # Legacy paged read: a full page implies there may be more.
        has_more = capped_limit is not None and len(messages) == capped_limit
        # `total` is otherwise unread (the cockpit uses only `.messages`,
        # persistent-chat.service.ts:748; the MCP tool doesn't read it). Skip the
        # per-open COUNT(*): a full load (no limit) returns the whole thread so
        # len(messages) IS the total; charge the COUNT only for the explicit
        # limit/offset paged read where a paginating client may want it.
        if capped_limit is None:
            total = len(messages)
        else:
            total = await postgres_db.get_thread_message_count(thread_id)

    _stamp_tool_categories(messages)

    return {
        "messages": messages,
        "total": total,
        "has_more": has_more,
        "thread_id": thread_id,
    }


# =============================================================================
# Headless persistent sessions — Phase 2 SSE + REST transport
# =============================================================================
#
# SSE replaces the WebSocket as the primary server→client path; the existing
# /ws/persistent/{thread_id} stays as a fallback. Per
# knowledge-base/knowledge/features/headless_persistent_sessions.md.
#
# The per-turn input lock guards against duplicate POSTs from concurrent
# cockpit tabs racing on the same turn. Single-instance orchestrator, so a
# module-level dict is enough; entries auto-clean 5 min after release.

_thread_turn_locks: dict[tuple[str, int], asyncio.Lock] = {}
_thread_turn_inflight: dict[str, int] = {}


def _ensure_thread_turn_lock(thread_id: str, turn_id: int) -> asyncio.Lock:
    """Get or create the lock for (thread_id, turn_id). Concurrent callers
    landing on the same tuple share the same Lock object."""
    key = (thread_id, turn_id)
    lock = _thread_turn_locks.get(key)
    if lock is None:
        lock = asyncio.Lock()
        _thread_turn_locks[key] = lock
    return lock


def _schedule_turn_lock_cleanup(thread_id: str, turn_id: int) -> None:
    """Remove the lock entry 5 minutes after release. Memory-leak guard
    for long-lived sessions accumulating per-turn locks."""

    async def _later() -> None:
        await asyncio.sleep(300)
        _thread_turn_locks.pop((thread_id, turn_id), None)
        if _thread_turn_inflight.get(thread_id) == turn_id:
            _thread_turn_inflight.pop(thread_id, None)

    asyncio.create_task(_later(), name=f"turn-lock-cleanup-{thread_id[:8]}")


async def _resolve_thread_for_forwarding(
    thread_id: str, user: dict
) -> tuple[dict, PinnedSessionBinding]:
    """Resolve one owner-visible thread and its exact pinned runtime binding.

    Stateless callers branch before this helper.  All agent/endpoint fields in
    the result come from one reciprocal DB snapshot rather than independent
    thread and agent reads.  A suspended pinned workspace is restored before
    that final snapshot.
    """
    thread = await postgres_db.get_thread(thread_id)
    if not thread:
        raise HTTPException(status_code=404, detail="Thread not found")
    # Fail-closed for orphans (user_id IS NULL); admins bypass.
    if not user.get("is_admin") and str(thread.get("user_id") or "") != str(user["id"]):
        raise HTTPException(status_code=403, detail="Not your thread")
    if not _thread_accepts_runtime(thread):
        raise HTTPException(
            status_code=409, detail=thread_runtime_refusal_detail(thread)
        )
    if thread.get("execution_lane") != "pinned":
        raise HTTPException(
            status_code=409,
            detail="Thread execution lane does not support direct forwarding",
        )

    async def _refresh_runtime_authority() -> dict[str, Any]:
        current = await postgres_db.get_thread(thread_id)
        if not _thread_accepts_runtime(current):
            raise HTTPException(
                status_code=409, detail=thread_runtime_refusal_detail(current)
            )
        if not user.get("is_admin") and str(current.get("user_id") or "") != str(
            user["id"]
        ):
            raise HTTPException(status_code=403, detail="Not your thread")
        if current.get("execution_lane") != "pinned":
            raise HTTPException(
                status_code=409,
                detail="Thread execution lane does not support direct forwarding",
            )
        marker = protected_cloud_marker_state(thread_metadata_object(current))
        if marker == "malformed":
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "protected_cloud_malformed",
                    "message": "Protected cloud session state is invalid.",
                },
            )
        if marker == "on":
            state, code = await _protected_cloud_delivery_state(
                current, thread_metadata_object(current)
            )
            if state != "ready":
                raise HTTPException(
                    status_code=425,
                    detail={
                        "code": "protected_cloud_not_ready",
                        "state": state,
                        "reason": code,
                    },
                )
        return current

    thread = await _refresh_runtime_authority()

    # Restore suspended workspace before forwarding (mirrors persistent_ws_proxy)
    metadata = thread.get("metadata") or {}
    if isinstance(metadata, str):
        try:
            metadata = json.loads(metadata)
        except (json.JSONDecodeError, TypeError):
            metadata = {}
    ws_ctx = metadata.get("workspace_container") or {}
    if ws_ctx.get("status") == "suspended" and workspace_suspension_service.is_enabled:
        logger.info("Restoring suspended workspace for thread %s", thread_id)
        ok = await workspace_suspension_service.restore_thread_workspace(thread_id)
        if not ok:
            raise HTTPException(
                status_code=503,
                detail="Failed to restore suspended workspace",
            )
        thread = await _refresh_runtime_authority()

    runtime_authority = thread_runtime_authority(thread)
    if runtime_authority is None:  # _refresh_runtime_authority proves this
        raise HTTPException(
            status_code=409, detail=thread_runtime_refusal_detail(thread)
        )
    binding = await postgres_db.get_pinned_session_binding(
        thread_id,
        expected_runtime_generation=runtime_authority.generation,
    )
    if binding is None:
        raise HTTPException(
            status_code=409,
            detail=pinned_binding_invalid_detail(runtime_authority),
        )
    _require_forwardable_pinned_binding(binding)
    return thread, binding


def _require_forwardable_pinned_binding(binding: PinnedSessionBinding) -> None:
    """Require a currently live agent status without freezing status equality."""

    if binding.agent_status not in {"ready", "working", "session"}:
        raise HTTPException(status_code=425, detail="session not ready")


def _binding_runtime_authority(
    binding: PinnedSessionBinding,
) -> ThreadRuntimeAuthority:
    return ThreadRuntimeAuthority(
        thread_id=binding.thread_id,
        generation=binding.runtime_generation,
    )


async def _revalidate_pinned_forwarding_binding(
    binding: PinnedSessionBinding,
) -> PinnedSessionBinding:
    """Re-read and compare every immutable DB/routing coordinate."""

    current = await postgres_db.get_pinned_session_binding(
        binding.thread_id,
        expected_runtime_generation=binding.runtime_generation,
    )
    if current is None or current.target_key != binding.target_key:
        raise HTTPException(
            status_code=409,
            detail=pinned_binding_invalid_detail(_binding_runtime_authority(binding)),
        )
    _require_forwardable_pinned_binding(current)
    return current


async def _forward_to_agent(
    binding: PinnedSessionBinding,
    path: str,
    payload: dict,
    timeout: float = 30.0,
) -> dict[str, Any]:
    """POST to one exact pinned Pod after a client-boundary DB reread."""

    identity_fingerprint = binding.session_identity_fingerprint
    forwarded_payload = dict(payload)
    supplied_fingerprint = forwarded_payload.get("session_identity_fingerprint")
    if supplied_fingerprint not in (None, identity_fingerprint):
        raise ValueError("forwarded session identity does not match its binding")
    forwarded_payload["session_identity_fingerprint"] = identity_fingerprint
    agent_url = f"http://{binding.pod_ip}:{binding.pod_port}{path}"
    try:
        async with httpx.AsyncClient(timeout=timeout) as client:
            # Client/pool entry may await.  Re-read after it so no stale target
            # receives an effect merely because it was authoritative before
            # transport setup.  The endpoint validates the fingerprint again
            # across the final network race.
            await _revalidate_pinned_forwarding_binding(binding)
            response = await client.post(agent_url, json=forwarded_payload)
    except HTTPException:
        raise
    except Exception as e:
        logger.warning(
            "Agent forward failed: %s %s -> %s",
            path,
            binding.agent_id,
            e,
        )
        raise HTTPException(status_code=503, detail=f"Agent unreachable: {e}") from e
    try:
        response_body = response.json()
    except Exception:
        response_body = None
    if (
        response.status_code == 409
        and isinstance(response_body, dict)
        and response_body.get("error") == "session_identity_mismatch"
    ):
        raise HTTPException(
            status_code=409,
            detail=pinned_binding_invalid_detail(_binding_runtime_authority(binding)),
        )
    if response.status_code == 503:
        if (
            isinstance(response_body, dict)
            and response_body.get("error") == "runtime_terminating"
        ):
            raise HTTPException(
                status_code=503,
                detail={
                    "error": "runtime_terminating",
                    "retryable": True,
                    "message": "The runtime is terminating; retry on its replacement.",
                },
                headers={"Retry-After": response.headers.get("Retry-After", "5")},
            )
    if response.status_code >= 500:
        raise HTTPException(
            status_code=502,
            detail=f"Agent error: {response.status_code} {response.text[:200]}",
        )
    if response.status_code >= 400:
        raise HTTPException(
            status_code=response.status_code,
            detail=response.text[:200],
        )
    return (
        response_body
        if isinstance(response_body, dict)
        else {"raw": response.text[:500]}
    )


async def _no_cursor_replay_start(conn, thread_id: str, epoch: int) -> int:
    """Replay floor (exclusive) for an SSE attach that carries no cursor.

    A fresh client — opening the session on a second device, or any client
    with no cached cursor for this thread — has already painted the thread's
    completed turns from REST history. Replaying the whole epoch from seq 0
    would re-deliver each completed turn as a *live* copy the cockpit reducer
    can't reconcile (history turns are keyed by message id, replayed turns by
    turn_id), so the last assistant turn renders twice, split by a spurious
    "SESSION RESUMED" divider — the cold-attach twin of the gone_beyond_horizon
    duplicate render.

    Anchor instead just past the last turn-terminal event (``turn.completed`` /
    ``turn.error``, both of which persist their turn to ``thread_messages``), so
    the replay carries only the in-flight, not-yet-persisted turn. Returns 0
    when no turn has finished yet (first turn still streaming) so that turn —
    absent from REST history — still replays from the start.
    """
    anchor = await conn.fetchval(
        "SELECT COALESCE(MAX(seq), 0) FROM thread_events "
        "WHERE thread_id = $1 AND epoch = $2 "
        "AND kind IN ('turn.completed', 'turn.error')",
        thread_id,
        epoch,
    )
    return int(anchor or 0)


# How much *accumulated idle time* (seconds with no new rows) a live SSE stream
# tolerates before it re-reads `events_epoch` to detect a mid-stream bump. The
# epoch is bumped when an agent (re-)attaches; a generator opened before the
# bump would otherwise poll the dead old epoch forever, delivering nothing but
# keepalive pings that fool the client watchdog into thinking the stream is
# healthy (the "stale → refresh to fix" zombie). Read as a module global so
# tests can monkeypatch it to 0 to force a re-check on the first empty poll.
THREAD_EVENTS_EPOCH_RECHECK_S: float = float(
    os.environ.get("THREAD_EVENTS_EPOCH_RECHECK_S", "2.0")
)
THREAD_CLIENT_PRESENCE_RENEW_S: float = max(
    1.0,
    float(
        os.environ.get(
            "THREAD_CLIENT_PRESENCE_RENEW_S",
            str(DEFAULT_PRESENCE_RENEW_SECONDS),
        )
    ),
)
THREAD_CLIENT_PRESENCE_TTL_S: float = max(
    THREAD_CLIENT_PRESENCE_RENEW_S * 2.0,
    float(
        os.environ.get(
            "THREAD_CLIENT_PRESENCE_TTL_S",
            str(DEFAULT_PRESENCE_TTL_SECONDS),
        )
    ),
)


@app.get("/api/persistent/threads/{thread_id}/stream")
async def thread_event_stream(thread_id: str, request: Request) -> StreamingResponse:
    """SSE: stream this thread's event log with replay-from-cursor.

    The client sends `Last-Event-ID: <epoch>:<seq>` to resume from a known
    point. If the cursor's epoch doesn't match the server, or its seq is
    older than retention, the server emits a single `gone_beyond_horizon`
    event and closes — the client must drop its cursor and re-sync.

    Otherwise: replay everything since the cursor, then switch to live
    mode (200ms poll, adaptive backoff to 1s after 5 empty polls).
    """
    user, thread = await require_thread_owner(request, postgres_db, thread_id)

    # The existing owner-gated SSE connection is the lane-agnostic client
    # attachment signal. No lane field crosses the wire. Pinned streams keep
    # their exact behavior; a stateless stream must establish its durable TTL
    # before the browser can believe it is attached.
    track_presence = thread.get("execution_lane") == "stateless"
    if track_presence:
        try:
            presence = await refresh_thread_presence(
                postgres_db,
                thread_id=thread_id,
                ttl_seconds=THREAD_CLIENT_PRESENCE_TTL_S,
                establish=True,
            )
        except Exception as exc:
            logger.warning(
                "thread_event_stream presence establish failed (thread=%s): %s",
                thread_id,
                exc,
            )
            raise HTTPException(
                status_code=503,
                detail="Session presence is temporarily unavailable",
            ) from exc
        if not presence.served:
            # The row changed lane or disappeared after the owner lookup. A
            # reconnect re-runs authorization and resolves the current lane.
            raise HTTPException(status_code=409, detail="Session lane changed")

    server_epoch = int(thread.get("events_epoch") or 0)

    # Parse Last-Event-ID. Format: "<epoch>:<seq>". Missing/malformed → no
    # cursor, so the replay floor is computed by _no_cursor_replay_start below
    # (anchored past the last completed turn, not seq 0).
    #
    # EventSource doesn't let the browser set custom request headers, so the
    # cockpit hands us the cached cursor via `?last_event_id=` for the
    # initial connection. On automatic reconnect, the browser appends the
    # `Last-Event-ID` header from the latest `id:` line we yielded — that
    # path is fully native and doesn't need the query param.
    last_event_id = (
        request.headers.get("Last-Event-ID")
        or request.headers.get("last-event-id")
        or request.query_params.get("last_event_id")
    )
    cursor_epoch: Optional[int] = None
    cursor_seq: Optional[int] = None
    if last_event_id:
        try:
            e_str, s_str = last_event_id.split(":", 1)
            cursor_epoch = int(e_str)
            cursor_seq = int(s_str)
        except (ValueError, AttributeError):
            cursor_epoch = None
            cursor_seq = None

    async def event_stream():
        # Kickstart: flush a comment immediately so the browser EventSource
        # fires `onopen` at once and buffering intermediaries (Cloudflare
        # Tunnel, Traefik) don't hold the response headers / idle-timeout the
        # connection waiting for the first body byte. Without this, a connect
        # whose cursor is already at the tail sends nothing until the ~20s
        # keepalive ping below — stalling the SSE receive path ~20s. Comments
        # (lines starting with `:`) are ignored by EventSource, so this is
        # side-effect-free on the client.
        yield ": open\n\n"

        next_presence_renew = time.monotonic() + THREAD_CLIENT_PRESENCE_RENEW_S

        # Mismatched epoch → force re-sync.
        if cursor_epoch is not None and cursor_epoch != server_epoch:
            async with postgres_db.acquire() as conn:
                tail = await conn.fetchval(
                    "SELECT COALESCE(MAX(seq), 0) FROM thread_events "
                    "WHERE thread_id = $1 AND epoch = $2",
                    thread_id,
                    server_epoch,
                )
            payload = json.dumps(
                {
                    "method": "gone_beyond_horizon",
                    "params": {
                        "epoch": server_epoch,
                        "server_seq": int(tail or 0),
                        "reason": "epoch_mismatch",
                    },
                }
            )
            yield f"id: {server_epoch}:0\nevent: gone_beyond_horizon\ndata: {payload}\n\n"
            return

        # Retention floor for the current epoch.
        async with postgres_db.acquire() as conn:
            min_seq = await conn.fetchval(
                "SELECT MIN(seq) FROM thread_events "
                "WHERE thread_id = $1 AND epoch = $2",
                thread_id,
                server_epoch,
            )
        min_seq = int(min_seq) if min_seq is not None else 0

        # Cursor older than retention → also force re-sync.
        if cursor_seq is not None and min_seq > 0 and cursor_seq < min_seq - 1:
            async with postgres_db.acquire() as conn:
                tail = await conn.fetchval(
                    "SELECT COALESCE(MAX(seq), 0) FROM thread_events "
                    "WHERE thread_id = $1 AND epoch = $2",
                    thread_id,
                    server_epoch,
                )
            payload = json.dumps(
                {
                    "method": "gone_beyond_horizon",
                    "params": {
                        "epoch": server_epoch,
                        "server_seq": int(tail or 0),
                        "retention_min_seq": min_seq,
                        "reason": "cursor_older_than_retention",
                    },
                }
            )
            yield f"id: {server_epoch}:0\nevent: gone_beyond_horizon\ndata: {payload}\n\n"
            return

        # Replay floor. With a cursor, resume right after it. Without one, a
        # fresh attach has already loaded completed turns from REST history, so
        # anchor past the last completed turn instead of replaying the whole
        # epoch from 0 (which doubles the last assistant turn + shows a spurious
        # "SESSION RESUMED" divider — see _no_cursor_replay_start).
        if cursor_seq is not None:
            last_sent_seq = cursor_seq
        else:
            async with postgres_db.acquire() as conn:
                last_sent_seq = await _no_cursor_replay_start(
                    conn, thread_id, server_epoch
                )
        empty_polls = 0
        idle_keepalive_at = 0.0
        epoch_idle = 0.0
        cancelled = False
        try:
            while not cancelled:
                if await request.is_disconnected():
                    break
                if track_presence and time.monotonic() >= next_presence_renew:
                    # A long-lived stream does not retain authorization from
                    # its opening handshake forever. Re-run the same BFF-cookie
                    # owner gate before every attested renewal; expiry or an
                    # ownership change closes the stream and writes no TTL.
                    _renew_user, renew_thread = await require_thread_owner(
                        request, postgres_db, thread_id
                    )
                    if renew_thread.get("execution_lane") != "stateless":
                        return
                    presence = await refresh_thread_presence(
                        postgres_db,
                        thread_id=thread_id,
                        ttl_seconds=THREAD_CLIENT_PRESENCE_TTL_S,
                        establish=False,
                    )
                    if not presence.served:
                        # Lane change/deletion: close. EventSource reconnects
                        # through require_thread_owner and current DB truth.
                        return
                    next_presence_renew = (
                        time.monotonic() + THREAD_CLIENT_PRESENCE_RENEW_S
                    )
                async with postgres_db.acquire() as conn:
                    rows = await conn.fetch(
                        "SELECT seq, kind, payload "
                        "FROM thread_events "
                        "WHERE thread_id = $1 AND epoch = $2 AND seq > $3 "
                        "ORDER BY seq ASC "
                        "LIMIT 500",
                        thread_id,
                        server_epoch,
                        last_sent_seq,
                    )
                    # Zombie-epoch guard: after enough accumulated idle time
                    # with no new rows, re-read events_epoch on the SAME
                    # connection (no extra acquire). If an agent re-attached and
                    # bumped the epoch, this generator has been polling a dead
                    # epoch — terminate deterministically so the client
                    # re-anchors, instead of feeding it pings forever.
                    if not rows and epoch_idle >= THREAD_EVENTS_EPOCH_RECHECK_S:
                        epoch_idle = 0.0
                        current_epoch = await conn.fetchval(
                            "SELECT events_epoch FROM threads WHERE id = $1",
                            thread_id,
                        )
                        if current_epoch is None:
                            # Thread deleted mid-stream — terminate silently;
                            # the client's reconnect hits require_thread_owner
                            # → 404 and it drops the thread.
                            return
                        if int(current_epoch) != server_epoch:
                            new_epoch = int(current_epoch)
                            # Anchor past the last completed turn of the NEW
                            # epoch, not its tail: the bump lands mid-turn and
                            # the client's history reload only carries completed
                            # turns, so a tail anchor would drop the in-flight
                            # turn's already-journaled frames.
                            anchor = await _no_cursor_replay_start(
                                conn, thread_id, new_epoch
                            )
                            logger.info(
                                "thread_event_stream epoch bump %d→%d "
                                "(thread=%s), re-anchoring client to seq %d",
                                server_epoch,
                                new_epoch,
                                thread_id,
                                anchor,
                            )
                            payload = json.dumps(
                                {
                                    "method": "gone_beyond_horizon",
                                    "params": {
                                        "epoch": new_epoch,
                                        "server_seq": anchor,
                                        "reason": "epoch_bumped_mid_stream",
                                    },
                                }
                            )
                            # The `id:` line carries the new epoch's floor so a
                            # browser-native reconnect (bypassing the app
                            # handler) converges to the same replay start
                            # instead of replaying the new epoch from :0.
                            yield (
                                f"id: {new_epoch}:{anchor}\n"
                                f"event: gone_beyond_horizon\n"
                                f"data: {payload}\n\n"
                            )
                            return
                if rows:
                    empty_polls = 0
                    epoch_idle = 0.0
                    for row in rows:
                        seq = int(row["seq"])
                        # row["payload"] is a JSONB column — asyncpg may
                        # return it as str or already-parsed dict depending
                        # on codec registration.
                        raw_payload = row["payload"]
                        if isinstance(raw_payload, str):
                            payload_obj = json.loads(raw_payload)
                        else:
                            payload_obj = raw_payload
                        frame = {
                            "method": row["kind"],
                            "params": payload_obj,
                        }
                        body = json.dumps(frame)
                        yield f"id: {server_epoch}:{seq}\ndata: {body}\n\n"
                        last_sent_seq = seq
                    idle_keepalive_at = 0.0
                else:
                    # Adaptive backoff: 200ms × 5 empty polls, then 1s.
                    empty_polls += 1
                    wait = 1.0 if empty_polls >= 5 else 0.2
                    epoch_idle += wait
                    # Typed `ping` event every ~20s of idle. A bare `:`
                    # comment would keep the socket warm but never fire
                    # `onmessage` in the browser, leaving silent network
                    # drops undetectable client-side. A typed event with no
                    # `id:` line lets the cockpit watchdog observe liveness
                    # without advancing the replay cursor.
                    idle_keepalive_at += wait
                    if idle_keepalive_at >= 20.0:
                        yield "event: ping\ndata: {}\n\n"
                        idle_keepalive_at = 0.0
                    try:
                        await asyncio.sleep(wait)
                    except asyncio.CancelledError:
                        cancelled = True
                        break
        except asyncio.CancelledError:
            return
        except Exception as e:
            logger.warning("thread_event_stream error (thread=%s): %s", thread_id, e)
            return

    return StreamingResponse(
        event_stream(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )


class ThreadInputRequest(BaseModel):
    """Body for POST /api/persistent/threads/{thread_id}/input."""

    content: str
    turn_id: Optional[int] = None


async def _load_thread_for_owner(thread_id: str, user: dict) -> dict:
    """Load a thread under the same owner gate ``_resolve_thread_for_forwarding``
    applies (404 unknown; fail-closed 403 for orphans and non-owners; admin
    bypass) — WITHOUT its agent-resolution / workspace-restore side effects.

    Used by the stateless-lane branches: queue-lane threads have no bound
    agent, so the forwarding resolver's 503 would mask the lane entirely.
    """
    thread = await postgres_db.get_thread(thread_id)
    if not thread:
        raise HTTPException(status_code=404, detail="Thread not found")
    if not user.get("is_admin") and str(thread.get("user_id") or "") != str(user["id"]):
        raise HTTPException(status_code=403, detail="Not your thread")
    return thread


async def _thread_input_stateless(thread: dict, content: str) -> dict[str, Any]:
    """Admit one user turn for a stateless-lane thread (stateless_agents.md
    §5.3.1): persist the message, advance the input watermark, and queue the
    unit — all in ONE transaction, so "message durable ⟺ watermark advanced"
    can never tear and a signal can never be lost.

    The message row is indistinguishable from the agent's accept-time persist
    of a plain-text human message (``src/api/persistent_app._accept_user_input``
    → ``src/database/postgres_db.save_thread_message``): same ``msg_`` id mint
    with the agent's own uuid5 row-id coercion, ``role='human'``,
    ``turn_number = total_turns + 1``, all other columns at their NULL
    defaults, and the same ``threads`` last_activity/total_turns bump.

    Admission is ``record_input_seq`` — the input-during-anything path: it
    creates a fresh ``'queued'`` row, revives ``'done'``, merges the watermark
    into ``'queued'``, bumps ONLY the watermark on ``'leased'`` (the running
    turn's completion re-queues via ``input_seq > consumed_seq``), and records
    input on ``'parked'`` without reviving it (explicit unpark only). No
    separate ``enqueue_unit`` call is needed: every branch leaves the unit
    queued, leased-with-watermark, or deliberately parked.
    """
    from shared.row_identity import _coerce_row_id
    from orchestrator.services.stateless_queue_state import queue_block
    from shared.run_queue import (
        LANE_STATELESS,
        UNIT_KIND_SESSION_TURN,
        queue_depth_for,
        queue_state_for,
        record_input_seq,
    )

    # The unlocked preflight provides a fast refusal. The locked copy below is
    # authoritative against lane/tier/lifecycle changes before message commit.
    _require_stateless_workspace(thread)

    thread_id = str(thread["id"])
    # Mirror the agent's accept-time mint exactly; the row id is the same
    # deterministic uuid5 the agent-side coercion would derive from this raw
    # id, so a later executor re-persist upserts onto this row (ON CONFLICT
    # (id)) instead of duplicating the user bubble.
    raw_msg_id = f"msg_{uuid4().hex[:24]}"
    row_id = _coerce_row_id(raw_msg_id)

    async with postgres_db.acquire() as conn:
        async with conn.transaction():
            locked_thread = await conn.fetchrow(
                "SELECT id, user_id, execution_lane, agent_id, status, "
                "       total_turns, metadata "
                "FROM threads WHERE id = $1 FOR UPDATE",
                thread_id,
            )
            if (
                locked_thread is None
                or str(locked_thread["execution_lane"] or "") != LANE_STATELESS
                or locked_thread["agent_id"] is not None
            ):
                raise HTTPException(
                    status_code=409,
                    detail="Thread is no longer eligible for stateless admission",
                )
            locked_thread_dict = dict(locked_thread)
            locked_backend = _require_stateless_workspace(locked_thread_dict)
            locked_status = str(locked_thread["status"] or "")
            if locked_status not in {
                "created",
                "active",
                "awaiting_user",
                "suspended",
            }:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Thread is not currently accepting stateless input "
                        f"(status={locked_status or 'unknown'})"
                    ),
                )
            needs_workspace_ensure = locked_backend == "sandbox"
            if locked_status == "suspended":
                # Wake and enqueue are one lifecycle transaction. Workspace
                # restore remains a post-commit side effect, but no claimant
                # can observe a runnable queue paired with a still-suspended
                # thread (the claim/credential boundary correctly refuses
                # suspended rows).
                woke = await conn.fetchval(
                    "UPDATE threads SET status = 'created', "
                    "agent_id = NULL, control_admission_agent_id = NULL, "
                    "awaiting_user_since = NULL, extend_count = 0 "
                    "WHERE id = $1::uuid AND execution_lane = 'stateless' "
                    "AND status = 'suspended' RETURNING id",
                    thread_id,
                )
                if woke is None:
                    raise RuntimeError(
                        "stateless suspended-input wake lost thread authority"
                    )
            turn_number = int(locked_thread["total_turns"] or 0) + 1
            fair_key = (
                str(locked_thread["user_id"])
                if locked_thread["user_id"] is not None
                else None
            )
            seq = await conn.fetchval(
                """
                INSERT INTO thread_messages (id, thread_id, role, content, turn_number)
                VALUES ($1, $2, 'human', $3, $4)
                RETURNING seq
                """,
                row_id,
                thread_id,
                content,
                turn_number,
            )
            # Same activity bump the agent's save_thread_message performs.
            await conn.execute(
                """
                UPDATE threads
                SET last_activity = CURRENT_TIMESTAMP,
                    total_turns   = GREATEST(total_turns, COALESCE($2, 0))
                WHERE id = $1
                """,
                thread_id,
                turn_number,
            )
            state = await record_input_seq(
                conn,
                unit_id=thread_id,
                unit_kind=UNIT_KIND_SESSION_TURN,
                input_seq=int(seq),
                fair_key=fair_key,
            )

        if needs_workspace_ensure:
            # Queue admission commits before this side effect. The claimant may
            # arrive first, but its internal workspace poll independently
            # suppresses cached Ready credentials until the exact Pod UID is
            # live. Always schedule sandbox reconciliation: a DB-Ready row can
            # be stale even though its lifecycle string looks terminally good.
            _schedule_stateless_workspace_ensure(thread_id)
        # Post-commit watermark read (same conn): §5.3.1 response parity —
        # queue_depth comes from unconsumed watermarks, not a process queue.
        wm = await queue_depth_for(conn, unit_id=thread_id)
        queue_state = await queue_state_for(conn, unit_id=thread_id)

    queue_depth = 1 if (wm is not None and wm.has_pending_input) else 0
    # Lifecycle block (stateless_turn_resilience.md step 2): the SAME shape
    # /connection and GET …/queue return, so a parked unit is never mistaken
    # for a busy pool by the client.
    lifecycle = queue_block(queue_state, thread.get("metadata"))
    logger.info(
        "run_queue enqueue: thread=%s turn=%d input_seq=%d state=%s",
        thread_id,
        turn_number,
        int(seq),
        state,
    )
    return {
        "accepted": True,
        "turn_id": turn_number,
        "queue": {
            "state": state,
            "queue_depth": queue_depth,
            "message_id": raw_msg_id,
            "input_seq": int(seq),
            "park_reason": lifecycle["park_reason"],
            "parked_at": lifecycle["parked_at"],
            "retryable": lifecycle["retryable"],
            "attempts": lifecycle["attempts"],
            "pending_input": lifecycle["pending_input"],
        },
    }


@app.post("/api/persistent/threads/{thread_id}/input")
async def thread_input(
    thread_id: str, body: ThreadInputRequest, request: Request
) -> dict[str, Any]:
    """Submit user input to a thread. Per-turn lock returns 409 on dupes."""
    from shared.run_queue import LANE_STATELESS

    user = await require_approved_user(request, postgres_db)

    # Stateless-lane admission (stateless_agents.md §5.3.1) resolves BEFORE
    # agent forwarding — queue-lane threads have no bound agent, so
    # _resolve_thread_for_forwarding would 503 on them. Owner gate identical
    # to the resolver's; the pinned path below is untouched (its resolver
    # re-loads the thread and re-applies the same checks).
    lane_thread = await _load_thread_for_owner(thread_id, user)
    if lane_thread.get("execution_lane") == LANE_STATELESS:
        if not body.content or not isinstance(body.content, str):
            raise HTTPException(
                status_code=400, detail="content must be a non-empty string"
            )
        # The per-turn in-process lock below is deliberately SKIPPED on this
        # lane: the run_queue itself serializes turns (input during a leased
        # turn only advances the watermark; one row per unit dedups the
        # queue), and the lock dict is per-process state — replica-unsafe
        # under the 2-replica topology anyway. body.turn_id is ignored: the
        # queue lane derives the turn number from DB truth (total_turns + 1).
        return await _thread_input_stateless(lane_thread, body.content)

    thread, binding = await _resolve_thread_for_forwarding(thread_id, user)

    if not body.content or not isinstance(body.content, str):
        raise HTTPException(
            status_code=400, detail="content must be a non-empty string"
        )

    # Turn id defaults to the thread's current total_turns + 1. Reject
    # arbitrarily-large values to bound the lock dict.
    total_turns = int(thread.get("total_turns") or 0)
    if body.turn_id is None:
        turn_id = total_turns + 1
    else:
        turn_id = body.turn_id
        if turn_id < 0 or turn_id > total_turns + 5:
            raise HTTPException(
                status_code=400,
                detail=f"turn_id out of range "
                f"(thread at turn {total_turns}, max accepted "
                f"{total_turns + 5})",
            )

    lock = _ensure_thread_turn_lock(thread_id, turn_id)
    if lock.locked():
        in_flight = _thread_turn_inflight.get(thread_id, turn_id)
        return JSONResponse(
            status_code=409,
            content={
                "error": "turn_in_flight",
                "turn_id": in_flight,
                "thread_id": thread_id,
            },
        )
    async with lock:
        _thread_turn_inflight[thread_id] = turn_id
        try:
            # Waiting for another tab's turn lock is an authority boundary.
            # Refuse a same-G Pod/attach/endpoint rotation before constructing
            # the HTTP client; _forward_to_agent performs the final reread
            # after client entry as well.
            await _revalidate_pinned_forwarding_binding(binding)
            result = await _forward_to_agent(
                binding,
                "/api/input",
                {"content": body.content, "turn_id": turn_id},
            )
        finally:
            _schedule_turn_lock_cleanup(thread_id, turn_id)
    return {
        "accepted": True,
        "turn_id": turn_id,
        "agent": result,
    }


@app.get("/api/persistent/threads/{thread_id}/queue")
async def thread_queue_state(thread_id: str, request: Request) -> dict[str, Any]:
    """Owner read of the unit's queue lifecycle
    (stateless_turn_resilience.md step 2) — the same ``queue`` block that
    ``/input`` and ``/connection`` carry, for polling while a turn is awaited.
    A thread that never enqueued (pinned lane, or no turn yet) reports
    ``state='none'``.
    """
    from orchestrator.services.stateless_queue_state import queue_block_for_thread

    try:
        UUID(str(thread_id))
    except (ValueError, TypeError):
        raise HTTPException(status_code=404, detail="Thread not found") from None
    _user, thread = await require_thread_owner(request, postgres_db, thread_id)
    async with postgres_db.acquire() as conn:
        block = await queue_block_for_thread(conn, thread)
    return {"thread_id": thread_id, "queue": block}


@app.post("/api/persistent/threads/{thread_id}/queue/retry")
async def thread_queue_retry(thread_id: str, request: Request) -> dict[str, Any]:
    """Owner verb: revive a parked, retryable unit
    (stateless_turn_resilience.md step 2). ``parked`` + retryable →
    ``unpark_unit`` (attempts reset, park_reason cleared) → 200
    ``{state:'queued'}``; 409 ``{code}`` under stop markers / a claim-loss
    hold / a non-retryable reason; 404 when not parked. Audited. The admin
    verb ``POST /api/admin/run-queue/{unit_id}/unpark`` remains the
    operator path for the non-retryable reasons.
    """
    from orchestrator.services.stateless_queue_state import park_retry_refusal
    from shared.run_queue import STATE_PARKED, queue_state_for, unpark_unit

    try:
        UUID(str(thread_id))
    except (ValueError, TypeError):
        raise HTTPException(status_code=404, detail="Thread not found") from None
    user, _thread = await require_thread_owner(request, postgres_db, thread_id)
    async with postgres_db.acquire() as conn:
        async with conn.transaction():
            authority = await conn.fetchrow(
                "SELECT execution_lane, metadata FROM threads "
                "WHERE id = $1::uuid FOR UPDATE",
                thread_id,
            )
            if authority is None:
                raise HTTPException(status_code=404, detail="Thread not found")
            queue_state = await queue_state_for(conn, unit_id=thread_id)
            if queue_state is None or queue_state.get("state") != STATE_PARKED:
                raise HTTPException(status_code=404, detail="Unit is not parked")
            park_reason = queue_state.get("park_reason")
            refusal = park_retry_refusal(park_reason, authority["metadata"])
            if refusal is not None:
                raise HTTPException(
                    status_code=409,
                    detail={"code": refusal, "park_reason": park_reason},
                )
            ok = await unpark_unit(conn, unit_id=thread_id)
    if not ok:
        raise HTTPException(status_code=404, detail="Unit is not parked")
    attempts = int(queue_state.get("attempts") or 0)
    logger.info(
        "run_queue retry (owner): unit=%s park_reason=%s attempts=%d",
        thread_id,
        park_reason,
        attempts,
    )
    await log_security_event(
        postgres_db,
        resource_type="thread",
        event_type="queue_retry",
        user=user,
        resource_id=thread_id,
        detail=f"owner unpark park_reason={park_reason} attempts={attempts}",
        request=request,
    )
    return {
        "thread_id": thread_id,
        "unit_id": thread_id,
        "state": "queued",
        "park_reason": park_reason,
    }


class ThreadInterruptRequest(BaseModel):
    """Optional correlated envelope; an empty body is pinned back-compat."""

    model_config = ConfigDict(extra="forbid")

    client_request_id: UUID | None = None
    target_turn_id: int | None = Field(
        default=None,
        ge=1,
        le=2_147_483_647,
        strict=True,
    )

    @model_validator(mode="after")
    def validate_complete_envelope(self) -> "ThreadInterruptRequest":
        if (self.client_request_id is None) != (self.target_turn_id is None):
            raise ValueError(
                "client_request_id and target_turn_id must be supplied together"
            )
        return self


@app.post(
    "/api/persistent/threads/{thread_id}/interrupt",
    responses={202: {"description": "Stateless interrupt admitted"}},
)
async def thread_interrupt(
    thread_id: str,
    request: Request,
    body: ThreadInterruptRequest | None = None,
) -> Any:
    """Interrupt one exact in-flight turn without exposing its execution lane.

    Pinned sessions retain their direct agent forward. Every forwarded body is
    bound to the exact runtime fingerprint; an otherwise-empty legacy command
    still targets the active turn observed by that runtime. A correlated
    client is forwarded intact so the agent can reject a retry aimed at an
    older turn. Stateless sessions commit an exact-lease request for the
    serving executor and return admission only — that owner applies the verb
    and journals the authoritative ack.
    """
    from shared.run_queue import LANE_STATELESS

    user, lane_thread = await require_thread_owner(request, postgres_db, thread_id)
    correlated = body is not None and body.client_request_id is not None
    if correlated and body is not None and body.target_turn_id is not None:
        try:
            existing = await find_existing_thread_interrupt(
                postgres_db,
                thread_id=thread_id,
                owner_user_id=lane_thread.get("user_id"),
                client_request_id=body.client_request_id,
                target_turn_id=body.target_turn_id,
            )
        except InterruptAdmissionError as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc
        if existing is not None:
            return JSONResponse(
                status_code=202,
                content={
                    "accepted": True,
                    "request_id": str(existing.id),
                    "client_request_id": str(existing.client_request_id),
                    "target_turn_id": existing.target_turn_id,
                    "state": existing.state,
                    "duplicate": True,
                },
            )
    if lane_thread.get("execution_lane") == LANE_STATELESS:
        if not correlated or body is None or body.target_turn_id is None:
            # Stateless interrupt did not exist for legacy clients. Refuse an
            # uncorrelated command rather than letting it strike whichever
            # lease/turn happens to be current.
            raise HTTPException(
                status_code=422,
                detail=(
                    "client_request_id and target_turn_id are required for "
                    "stateless interrupt"
                ),
            )
        try:
            admitted = await admit_thread_interrupt(
                postgres_db,
                thread_id=thread_id,
                owner_user_id=lane_thread.get("user_id"),
                client_request_id=body.client_request_id,
                target_turn_id=body.target_turn_id,
                requested_by=str(user.get("id") or user.get("sub") or "rest_client"),
            )
        except InterruptAdmissionError as exc:
            raise HTTPException(status_code=409, detail=str(exc)) from exc

        logger.info(
            "session-interrupt admission: thread=%s turn=%d token=%d duplicate=%s",
            thread_id,
            admitted.target_turn_id,
            admitted.accepted_lease_token,
            admitted.duplicate,
        )
        return JSONResponse(
            status_code=202,
            content={
                "accepted": True,
                "request_id": str(admitted.id),
                "client_request_id": str(admitted.client_request_id),
                "target_turn_id": admitted.target_turn_id,
                "state": admitted.state,
                "duplicate": admitted.duplicate,
            },
        )

    _, binding = await _resolve_thread_for_forwarding(thread_id, user)
    payload: dict[str, Any] = {}
    if correlated and body is not None and body.target_turn_id is not None:
        payload = {
            "client_request_id": str(body.client_request_id),
            "target_turn_id": body.target_turn_id,
        }
    result = await _forward_to_agent(binding, "/api/interrupt", payload)
    return {"accepted": True, "agent": result}


async def _resolve_background_push_workspace(thread: dict[str, Any]) -> dict[str, Any]:
    """Reuse the existing attested workspace/cloud credential assembly."""
    backend = _require_stateless_workspace(thread)
    thread_id = str(thread["id"])
    payload = await _agent_get_thread_workspace_locked(thread_id)
    generation = payload.get("workspace_generation")
    if not generation or payload.get("protected_cloud"):
        raise HTTPException(status_code=409, detail="Background workspace unavailable")
    if backend == "virtual":
        override = _inject_lite_workspace_config(
            {"workspace": {"backend": "virtual"}}, prefix=f"threads/{thread_id}/"
        )
        workspace = {**override["workspace"], "workspace_generation": generation}
    elif (
        backend == "sandbox"
        and payload.get("workspace_provisioner") == "k8s"
        and payload.get("status") == "ready"
    ):
        workspace = {
            "backend": backend,
            "host": payload.get("pod_ip"),
            "port": payload.get("pod_port"),
            "key_path": payload.get("ssh_key_path"),
            "workspace_generation": generation,
            "runtime_incarnation": payload.get("workspace_runtime_incarnation"),
            "host_key_fingerprint": payload.get("workspace_ssh_host_key_fingerprint"),
        }
        if not all(
            workspace.get(key)
            for key in ("host", "runtime_incarnation", "host_key_fingerprint")
        ):
            raise HTTPException(
                status_code=409, detail="Background workspace unavailable"
            )
    else:
        raise HTTPException(status_code=409, detail="Background workspace unavailable")
    return {"workspace": workspace, "cloud_sync": payload.get("cloud_sync")}


class ThreadApproveRequest(BaseModel):
    """Body for POST /api/persistent/threads/{id}/approve/{approval_id}."""

    decision: str  # "approve" or "deny"


@app.post("/api/persistent/threads/{thread_id}/approve/{approval_id}")
async def thread_approve(
    thread_id: str,
    approval_id: str,
    body: ThreadApproveRequest,
    request: Request,
) -> dict[str, Any]:
    """Resolve a pending permission gate by updating thread_permission_requests
    directly. The DB trigger fires NOTIFY → the agent's LISTEN wakes its
    permission_check. No agent forwarding hop — this endpoint is the
    canonical resolution path for magic-link approvals and MCP clients
    alike. The cockpit WS approve method does the same UPDATE inside the
    agent for back-compat.

    Returns:
        200 — request resolved (status flipped)
        400 — invalid decision
        403 — not thread owner
        404 — approval_id not found, or wrong thread, or no pending request
        409 — request already decided (idempotent re-clicks land here)
    """
    user, thread = await require_thread_owner(request, postgres_db, thread_id)
    decided_by = str(user.get("id") or user.get("sub") or "rest_client")
    outcome = await _decide_permission_request(
        thread_id, approval_id, body.decision, decided_by=decided_by
    )
    await notification_service.resolve_source(
        "permission_request", approval_id, resolved_by=f"user:{decided_by}"
    )
    return outcome


async def _decide_permission_request(
    thread_id: str, approval_id: str, decision: str, *, decided_by: str
) -> dict[str, Any]:
    """The one UPDATE that decides a permission gate — shared by the REST
    endpoint and the notification's approve/deny actions. Raises the
    endpoint's HTTP errors: 400 bad decision, 404 unknown, 409 decided."""
    if decision == "approve":
        new_status = "approved"
    elif decision == "deny":
        new_status = "denied"
    else:
        raise HTTPException(
            status_code=400,
            detail="decision must be 'approve' or 'deny'",
        )

    async with postgres_db.acquire() as conn:
        # Lookup-then-update so we can distinguish 404 (wrong id/thread)
        # from 409 (already decided).
        existing = await conn.fetchrow(
            "SELECT id, status, tool_call_id FROM thread_permission_requests "
            "WHERE id = $1 AND thread_id = $2",
            approval_id,
            thread_id,
        )
        if existing is None:
            raise HTTPException(
                status_code=404,
                detail="Permission request not found for this thread",
            )
        if existing["status"] != "pending":
            raise HTTPException(
                status_code=409,
                detail=f"Already {existing['status']}",
            )
        row = await conn.fetchrow(
            "UPDATE thread_permission_requests "
            "SET status = $2, decided_at = now(), decided_by = $3 "
            "WHERE id = $1 AND status = 'pending' "
            "RETURNING id, status, tool_call_id",
            approval_id,
            new_status,
            decided_by,
        )
    if row is None:
        # Lost the race — somebody else just decided this. Idempotency.
        raise HTTPException(
            status_code=409,
            detail="Already decided (race lost)",
        )
    return {
        "accepted": True,
        "decision": decision,
        "approval_id": str(row["id"]),
        "status": row["status"],
        "tool_call_id": row["tool_call_id"],
    }


async def thread_events_prune_sweeper(
    shutdown_event: asyncio.Event,
) -> None:
    """Background task that prunes the thread_events log on retention.

    Runs every THREAD_EVENTS_PRUNE_INTERVAL_S (default 300s). Two queries:
      - DELETE rows for threads in 'ended' status older than 24h.
      - DELETE rows for threads NOT in 'ended' older than 7 days.
      - Preserve any event that is still the only durable receipt for a
        pending session-control or exact-turn interrupt request; crash
        recovery terminalizes it first.

    Best-effort. Survives transient DB errors by logging and continuing.
    """
    interval_s = int(os.environ.get("THREAD_EVENTS_PRUNE_INTERVAL_S", "300"))
    logger.info("Thread-events prune sweeper started (interval=%ds)", interval_s)
    while not shutdown_event.is_set():
        try:
            async with postgres_db.acquire() as conn:
                ended_deleted = await conn.fetchval(
                    "WITH deleted AS ("
                    "  DELETE FROM thread_events "
                    "  WHERE thread_id IN ("
                    "    SELECT id FROM threads WHERE status = 'ended'"
                    "  ) "
                    "  AND created_at < now() - interval '24 hours' "
                    "  AND NOT EXISTS ("
                    "    SELECT 1 FROM thread_control_requests request "
                    "    WHERE request.id = thread_events.control_request_id "
                    "      AND request.outcome IS NULL"
                    "  ) "
                    "  AND NOT EXISTS ("
                    "    SELECT 1 FROM thread_interrupt_requests request "
                    "    WHERE request.id = thread_events.interrupt_request_id "
                    "      AND (request.outcome IS NULL "
                    "           OR (request.outcome = 'applied' "
                    "               AND NOT (COALESCE(request.result, '{}'::jsonb) "
                    "                        ? 'consumed_input_seq')))"
                    "  ) "
                    "  RETURNING 1"
                    ") SELECT COUNT(*) FROM deleted"
                )
                active_deleted = await conn.fetchval(
                    "WITH deleted AS ("
                    "  DELETE FROM thread_events "
                    "  WHERE thread_id IN ("
                    "    SELECT id FROM threads WHERE status <> 'ended'"
                    "  ) "
                    "  AND created_at < now() - interval '7 days' "
                    "  AND NOT EXISTS ("
                    "    SELECT 1 FROM thread_control_requests request "
                    "    WHERE request.id = thread_events.control_request_id "
                    "      AND request.outcome IS NULL"
                    "  ) "
                    "  AND NOT EXISTS ("
                    "    SELECT 1 FROM thread_interrupt_requests request "
                    "    WHERE request.id = thread_events.interrupt_request_id "
                    "      AND (request.outcome IS NULL "
                    "           OR (request.outcome = 'applied' "
                    "               AND NOT (COALESCE(request.result, '{}'::jsonb) "
                    "                        ? 'consumed_input_seq')))"
                    "  ) "
                    "  RETURNING 1"
                    ") SELECT COUNT(*) FROM deleted"
                )
            if (ended_deleted or 0) + (active_deleted or 0) > 0:
                logger.info(
                    "thread_events prune: ended=%d active=%d",
                    int(ended_deleted or 0),
                    int(active_deleted or 0),
                )
        except Exception as e:
            logger.warning("thread_events prune error (non-fatal): %s", e)
        try:
            await asyncio.wait_for(shutdown_event.wait(), timeout=float(interval_s))
            break
        except asyncio.TimeoutError:
            pass
    logger.info("Thread-events prune sweeper stopped")


async def security_events_prune_sweeper(shutdown_event: asyncio.Event) -> None:
    """Background task that prunes the security_events audit log on retention.

    Runs hourly (SECURITY_EVENTS_PRUNE_INTERVAL_S, default 3600). Deletes
    rows older than SECURITY_EVENTS_RETENTION_DAYS (default 90). Bounds
    table growth — writes happen on the post-auth 403 path, so any flood
    is tied to a real account, but retention still caps the worst case.
    Best-effort: survives transient DB errors by logging and continuing.
    """
    interval_s = int(os.environ.get("SECURITY_EVENTS_PRUNE_INTERVAL_S", "3600"))
    retention_days = int(os.environ.get("SECURITY_EVENTS_RETENTION_DAYS", "90"))
    logger.info(
        "Security-events prune sweeper started (interval=%ds, retention=%dd)",
        interval_s,
        retention_days,
    )
    while not shutdown_event.is_set():
        try:
            deleted = await postgres_db.prune_security_events(retention_days)
            if deleted:
                logger.info("security_events prune: deleted=%d", deleted)
        except Exception as e:
            logger.warning("security_events prune error (non-fatal): %s", e)
        try:
            await asyncio.wait_for(shutdown_event.wait(), timeout=float(interval_s))
            break
        except asyncio.TimeoutError:
            pass
    logger.info("Security-events prune sweeper stopped")


async def ssh_attachments_prune_sweeper(shutdown_event: asyncio.Event) -> None:
    """Background task that prunes the ssh_attachments audit log on retention.

    Runs hourly (SSH_ATTACHMENTS_PRUNE_INTERVAL_S, default 3600). Deletes
    rows older than SSH_ATTACHMENTS_RETENTION_DAYS (default 90). thread_id
    on this table is ON DELETE SET NULL rather than CASCADE (see 0204's
    header), so ending a session no longer prunes its attach history —
    this sweeper is what bounds the table's growth instead.

    Not leader-gated, matching security_events_prune_task: a delete-by-age
    is idempotent, so two replicas racing it is harmless — the second finds
    nothing. Best-effort: survives transient DB errors by logging and
    continuing.
    """
    interval_s = int(os.environ.get("SSH_ATTACHMENTS_PRUNE_INTERVAL_S", "3600"))
    retention_days = int(os.environ.get("SSH_ATTACHMENTS_RETENTION_DAYS", "90"))
    logger.info(
        "SSH-attachments prune sweeper started (interval=%ds, retention=%dd)",
        interval_s,
        retention_days,
    )
    while not shutdown_event.is_set():
        try:
            deleted = await postgres_db.prune_ssh_attachments(retention_days)
            if deleted:
                logger.info("ssh_attachments prune: deleted=%d", deleted)
        except Exception as e:
            logger.warning("ssh_attachments prune error (non-fatal): %s", e)
        try:
            await asyncio.wait_for(shutdown_event.wait(), timeout=float(interval_s))
            break
        except asyncio.TimeoutError:
            pass
    logger.info("SSH-attachments prune sweeper stopped")


# =============================================================================
# Headless persistent sessions — Phase 4 magic-link routes + watcher
# =============================================================================
#
# Email magic-links land at /magic/approve/{token}. GET renders a
# confirmation page (read-only, prefetch-safe). POST consumes the token
# and UPDATEs thread_permission_requests via the same trigger path as
# the cockpit WS approve handler.
#
# Background watcher (thread_permission_notify_sweeper) detects pending
# requests older than 30s with no notification on record and dispatches
# the email via services.headless_notifications.


# Phase 5: per-thread cap on /magic/extend clicks. 4 × 60min = 4h total
# awaiting_user before unconditional suspension. Configurable via env for
# ops tuning during incident response.
_MAGIC_EXTEND_CAP: int = int(os.environ.get("HEADLESS_EXTEND_CAP", "4"))


def _magic_link_confirmation_page(
    *,
    tool_name: str,
    tool_args_preview: str,
    intended_decision: Optional[str],
    token: str,
    extend_status: Optional[str] = None,
    extends_remaining: Optional[int] = None,
) -> str:
    """Render the GET landing page. Single button POSTs back to the same
    URL with the actual decision; this is what prevents email-link
    prefetchers (Outlook Safe Links, Gmail) from auto-consuming tokens.

    Phase 5: a second form lets the user POST /magic/extend/{token} to
    bump the attention-sleep clock by 60 min without consuming the
    approval token. extend_status (when set) drives an inline toast:
    'extended' on success, 'cap_reached' when extend_count >= cap,
    'not_awaiting' when the thread is no longer in awaiting_user.
    """
    safe_args = (
        tool_args_preview.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )
    safe_tool = tool_name.replace("&", "&amp;").replace("<", "&lt;")
    if intended_decision == "approved":
        button_label = "Confirm: Approve"
        button_color = _BRAND["success"]
    elif intended_decision == "denied":
        button_label = "Confirm: Deny"
        button_color = _BRAND["danger"]
    else:
        button_label = "Confirm decision"
        button_color = _BRAND["accent-color"]

    quoted_token = urllib.parse.quote(token, safe="")

    # Extend banner copy — friendly, action-specific.
    extend_banner_html = ""
    if extend_status == "extended":
        remaining_str = (
            f" — {extends_remaining} extends remaining"
            if extends_remaining is not None
            else ""
        )
        extend_banner_html = (
            f'<div style="background: {_BRAND["surface-0"]}; border: 1px solid {_BRAND["success"]}; '
            "padding: 10px 12px; margin: 0 0 12px 0; "
            f'color: {_BRAND["success"]}; font-size: 13px;">Window extended by 60 minutes'
            f"{remaining_str}.</div>"
        )
    elif extend_status == "cap_reached":
        extend_banner_html = (
            f'<div style="background: {_BRAND["surface-0"]}; border: 1px solid {_BRAND["text-secondary"]}; '
            "padding: 10px 12px; margin: 0 0 12px 0; "
            f'color: {_BRAND["text-secondary"]}; font-size: 13px;">Extend limit reached — please '
            "approve, deny, or open the cockpit.</div>"
        )
    elif extend_status == "not_awaiting":
        extend_banner_html = (
            f'<div style="background: {_BRAND["surface-0"]}; border: 1px solid {_BRAND["accent-color"]}; '
            "padding: 10px 12px; margin: 0 0 12px 0; "
            f'color: {_BRAND["accent-color"]}; font-size: 13px;">No extend needed — the agent '
            "is already active.</div>"
        )

    # Disable the extend button if we already know the cap was hit.
    #
    # The disabled look MUST be merged into the button's own style attribute.
    # HTML keeps the FIRST style= on an element and ignores every later one,
    # so emitting a second one meant the cap_reached branch -- and only that
    # branch -- rendered a button with opacity/cursor and none of the brand
    # colours, border or type scale.
    _extend_cap_reached = extend_status == "cap_reached"
    extend_disabled_attr = " disabled" if _extend_cap_reached else ""
    extend_button_style = (
        f"background: transparent; color: {_BRAND['accent-color']}; "
        f"padding: 10px 20px; border: 1px solid {_BRAND['accent-color']}; "
        f"font-weight: 600; font-size: 14px; "
        + (
            "opacity: 0.5; cursor: not-allowed;"
            if _extend_cap_reached
            else "cursor: pointer;"
        )
    )

    return f"""<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>SRW — Confirm Decision</title></head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: {_BRAND["app-bg"]}; color: {_BRAND["text-primary"]}; padding: 40px 20px;">
  <div style="max-width: 600px; margin: 0 auto; background: {_BRAND["panel-bg"]}; border: 1px solid {_BRAND["border-color"]}; overflow: hidden;">
    <div style="background: {_BRAND["surface-0"]}; padding: 16px 20px; border-bottom: 1px solid {_BRAND["border-color"]};">
      <h2 style="margin: 0; color: {_BRAND["accent-color"]}; font-size: 16px;">Confirm tool decision</h2>
    </div>
    <div style="padding: 20px; font-size: 14px; line-height: 1.6;">
      {extend_banner_html}
      <p>The agent wants to call <code style="background: {_BRAND["surface-0"]}; padding: 2px 6px;">{safe_tool}</code> with these arguments:</p>
      <pre style="background: {_BRAND["surface-0"]}; padding: 12px; overflow-x: auto; font-size: 12px; color: {_BRAND["success"]};">{safe_args}</pre>
    </div>
    <div style="background: {_BRAND["surface-0"]}; padding: 16px 20px; border-top: 1px solid {_BRAND["border-color"]}; text-align: center;">
      <form method="POST" action="/magic/approve/{quoted_token}" style="display: inline;">
        <button type="submit" style="background: {button_color}; color: {_BRAND["on-accent"]}; padding: 10px 28px; border: 0; cursor: pointer; font-weight: 600; font-size: 14px;">{button_label}</button>
      </form>
      <form method="POST" action="/magic/extend/{quoted_token}" style="display: inline; margin-left: 8px;">
        <button type="submit"{extend_disabled_attr} style="{extend_button_style}">I'm reviewing — extend 60min</button>
      </form>
      <p style="margin: 16px 0 0 0; color: {_BRAND["text-secondary"]}; font-size: 12px;">Approve link is single-use and expires in 30 minutes.</p>
    </div>
  </div>
</body></html>"""


def _magic_link_result_page(
    *,
    title: str,
    body: str,
    cockpit_url: str,
    is_error: bool = False,
) -> str:
    accent = _BRAND["danger"] if is_error else _BRAND["success"]
    return f"""<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>SRW — {title}</title></head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: {_BRAND["app-bg"]}; color: {_BRAND["text-primary"]}; padding: 40px 20px;">
  <div style="max-width: 600px; margin: 0 auto; background: {_BRAND["panel-bg"]}; border: 1px solid {_BRAND["border-color"]}; overflow: hidden;">
    <div style="background: {_BRAND["surface-0"]}; padding: 16px 20px; border-bottom: 1px solid {_BRAND["border-color"]};">
      <h2 style="margin: 0; color: {accent}; font-size: 16px;">{title}</h2>
    </div>
    <div style="padding: 20px; font-size: 14px; line-height: 1.6;">
      <p>{body}</p>
      <p style="margin-top: 16px;"><a href="{cockpit_url}" style="color: {_BRAND["accent-color"]};">Open the cockpit</a></p>
    </div>
  </div>
</body></html>"""


@app.get("/magic/approve/{token}")
async def magic_link_get(token: str) -> HTMLResponse:
    """Show a confirmation page for the magic-link token.

    Does NOT consume the token (POST does). This separation is critical:
    email link previewers (Outlook Safe Links, Gmail) auto-fetch URLs
    server-side; a GET-executes link would be consumed by a bot before
    the human ever clicks.
    """
    cockpit_external_url = email_service.cockpit_url or "http://localhost:4200"

    row = await headless_notifications.validate_magic_link(postgres_db, token)
    if row is None:
        return HTMLResponse(
            _magic_link_result_page(
                title="Link expired or already used",
                body=(
                    "This approval link is no longer valid. It may have "
                    "expired, been used already, or been invalidated by a "
                    "newer approval. Open the cockpit to see the current "
                    "state."
                ),
                cockpit_url=cockpit_external_url,
                is_error=True,
            ),
            status_code=404,
        )

    # Fetch tool details for the confirmation page.
    async with postgres_db.acquire() as conn:
        permission_row = await conn.fetchrow(
            "SELECT id, tool_name, tool_args, status "
            "FROM thread_permission_requests WHERE id = $1",
            row["approval_id"],
        )

    if permission_row is None or permission_row["status"] != "pending":
        return HTMLResponse(
            _magic_link_result_page(
                title="Already decided",
                body=(
                    "The agent's request has already been resolved. No "
                    "further action is needed."
                ),
                cockpit_url=cockpit_external_url,
            ),
            status_code=409,
        )

    tool_args = permission_row["tool_args"]
    if isinstance(tool_args, str):
        try:
            tool_args = json.loads(tool_args)
        except Exception:
            tool_args = {}
    elif tool_args is None:
        tool_args = {}
    args_preview = json.dumps(tool_args, indent=2, default=str)
    if len(args_preview) > 600:
        args_preview = args_preview[:600] + "\n… (truncated)"

    page = _magic_link_confirmation_page(
        tool_name=permission_row["tool_name"],
        tool_args_preview=args_preview,
        intended_decision=row.get("intended_decision"),
        token=token,
    )
    return HTMLResponse(page)


@app.post("/magic/approve/{token}")
async def magic_link_post(token: str) -> HTMLResponse:
    """Consume the token and resolve the permission request.

    CAS UPDATE on magic_link_tokens (single-use) + a second UPDATE on
    thread_permission_requests (which the agent's LISTEN picks up via
    the existing trigger). Distinguishes 404 (invalid) from 409 (token
    already used or request already decided) for clean UX on double-clicks.
    """
    cockpit_external_url = email_service.cockpit_url or "http://localhost:4200"

    row = await headless_notifications.validate_magic_link(postgres_db, token)
    if row is None:
        return HTMLResponse(
            _magic_link_result_page(
                title="Link expired or already used",
                body=(
                    "This approval link is no longer valid. It may have "
                    "expired or been used already."
                ),
                cockpit_url=cockpit_external_url,
                is_error=True,
            ),
            status_code=404,
        )

    decision = row.get("intended_decision") or "approved"

    consumed = await headless_notifications.consume_magic_link(
        postgres_db, str(row["id"]), decision
    )
    if consumed is None:
        return HTMLResponse(
            _magic_link_result_page(
                title="Already used",
                body=(
                    "This link has already been used. The agent's request "
                    "is being processed."
                ),
                cockpit_url=cockpit_external_url,
            ),
            status_code=409,
        )

    # Resolve the permission request. CAS-style UPDATE so we don't race
    # with the cockpit having already decided it.
    decided_by_label = "magic_link"
    if consumed.get("user_id"):
        decided_by_label = f"user:{consumed['user_id']}"
    async with postgres_db.acquire() as conn:
        permission_row = await conn.fetchrow(
            "UPDATE thread_permission_requests "
            "SET status = $2, decided_at = now(), decided_by = $3 "
            "WHERE id = $1 AND status = 'pending' "
            "RETURNING id, status, tool_call_id, tool_name, thread_id",
            consumed["approval_id"],
            decision,
            decided_by_label,
        )

    if permission_row is None:
        return HTMLResponse(
            _magic_link_result_page(
                title="Already decided",
                body=(
                    "The agent's request was already resolved by another "
                    "approval path (cockpit click, REST, or expired). "
                    "Your action was not needed."
                ),
                cockpit_url=cockpit_external_url,
            ),
            status_code=409,
        )

    # Phase 5: if attention sleep fired since the email was sent, wake through
    # the thread's existing execution plane. Pinned sessions retain workspace
    # restore + agent-pod re-creation. Stateless sessions retain their exact
    # queued/leased turn and converge the workspace without binding a pod. The
    # permission-row id is the wake task's freshness fence.
    asyncio.create_task(
        _phase5_wake_if_suspended(
            str(permission_row["thread_id"]),
            permission_request_id=str(permission_row["id"]),
        ),
        name=f"phase5-wake-{str(permission_row['thread_id'])[:8]}",
    )

    pretty = "approved" if decision == "approved" else "denied"
    return HTMLResponse(
        _magic_link_result_page(
            title=f"Tool {pretty}",
            body=(
                f"The agent's request to call "
                f"<code>{permission_row['tool_name']}</code> has been "
                f"{pretty}. The agent will resume shortly."
            ),
            cockpit_url=cockpit_external_url,
        )
    )


@app.post("/magic/extend/{token}")
async def magic_link_extend(token: str) -> HTMLResponse:
    """Extend the attention-sleep window for the thread bound to this token.

    Validates the token (same hash + expiry + single-use checks as
    /magic/approve) but does NOT consume it — the user is signaling
    "I'm still reviewing" without making the approve decision. Bumps
    threads.awaiting_user_since forward by 60 minutes per click, capped
    at HEADLESS_EXTEND_CAP (default 4 = 4h total ceiling).

    Re-renders the confirmation page with a toast so the user can still
    click approve/deny on the same screen. Status_code 200 throughout —
    the page itself carries the success/cap/not-awaiting signal.

    Why a separate route and not "extend ↔ approve same POST": the
    approve handler consumes the token (single-use CAS). If extend
    shared that path, every extend click would burn the approval token
    and the user couldn't approve afterward.
    """
    cockpit_external_url = email_service.cockpit_url or "http://localhost:4200"

    row = await headless_notifications.validate_magic_link(postgres_db, token)
    if row is None:
        return HTMLResponse(
            _magic_link_result_page(
                title="Link expired or already used",
                body=(
                    "This link is no longer valid. Open the cockpit to "
                    "review the agent's current state."
                ),
                cockpit_url=cockpit_external_url,
                is_error=True,
            ),
            status_code=404,
        )

    thread_id = row.get("thread_id")
    if thread_id is None:
        return HTMLResponse(
            _magic_link_result_page(
                title="Cannot extend",
                body="This link is not bound to a thread.",
                cockpit_url=cockpit_external_url,
                is_error=True,
            ),
            status_code=400,
        )

    # Bump awaiting_user_since iff the thread is still in awaiting_user
    # and extend_count < cap. The CAS UPDATE returns the new row state so
    # we can show the right banner. status='active' or 'suspended' means
    # there's nothing to extend — the agent has either woken up already
    # or moved beyond awaiting_user.
    async with postgres_db.acquire() as conn:
        updated = await conn.fetchrow(
            "UPDATE threads "
            "SET awaiting_user_since = now(), "
            "    extend_count = extend_count + 1 "
            "WHERE id = $1 "
            "  AND status = 'awaiting_user' "
            "  AND extend_count < $2 "
            "RETURNING extend_count",
            str(thread_id),
            _MAGIC_EXTEND_CAP,
        )

    if updated is None:
        # Distinguish cap_reached from not_awaiting for the banner copy.
        async with postgres_db.acquire() as conn:
            row_state = await conn.fetchrow(
                "SELECT status, extend_count FROM threads WHERE id = $1",
                str(thread_id),
            )
        if row_state is None:
            extend_status = "not_awaiting"
        elif row_state["status"] != "awaiting_user":
            extend_status = "not_awaiting"
        elif row_state["extend_count"] >= _MAGIC_EXTEND_CAP:
            extend_status = "cap_reached"
        else:
            # Edge case — concurrent change between our UPDATE and SELECT.
            # Render not_awaiting which is the gentler banner.
            extend_status = "not_awaiting"
        extends_remaining = None
    else:
        extend_status = "extended"
        extends_remaining = max(0, _MAGIC_EXTEND_CAP - int(updated["extend_count"]))

    # Re-render the confirmation page with the banner. Load the permission
    # row again (status may have changed underneath us).
    approval_id = row.get("approval_id")
    if approval_id is not None:
        async with postgres_db.acquire() as conn:
            permission_row = await conn.fetchrow(
                "SELECT tool_name, tool_args, status FROM "
                "thread_permission_requests WHERE id = $1",
                approval_id,
            )
    else:
        permission_row = None

    if permission_row is None or permission_row["status"] != "pending":
        return HTMLResponse(
            _magic_link_result_page(
                title="Already decided",
                body=(
                    "The agent's request has been resolved. No further "
                    "action is needed."
                ),
                cockpit_url=cockpit_external_url,
            ),
            status_code=200,
        )

    tool_args = permission_row["tool_args"]
    if isinstance(tool_args, str):
        try:
            tool_args = json.loads(tool_args)
        except Exception:
            tool_args = {}
    elif tool_args is None:
        tool_args = {}
    args_preview = json.dumps(tool_args, indent=2, default=str)
    if len(args_preview) > 600:
        args_preview = args_preview[:600] + "\n… (truncated)"

    page = _magic_link_confirmation_page(
        tool_name=permission_row["tool_name"],
        tool_args_preview=args_preview,
        intended_decision=row.get("intended_decision"),
        token=token,
        extend_status=extend_status,
        extends_remaining=extends_remaining,
    )
    return HTMLResponse(page)


async def _phase5_wake_stateless_if_suspended(
    thread_id: str,
    *,
    permission_request_id: str | None,
) -> None:
    """Wake one queue-served permission continuation without binding a pod.

    A magic-link task can run well after its originating request was resolved.
    Revalidate every authority under the global ``threads -> run_queue`` lock
    order: exact stateless lane/class/tier, no pinned-agent binding, the exact
    terminal permission row, and a queued/leased session turn whose human input
    is still unconsumed.  ``done`` is deliberately not revived: no durable
    permission-continuation watermark exists yet, so a done row would hit the
    executor's skip-if-answered edge and falsely claim the tool resumed.

    The queue row itself is left untouched.  A live lease keeps ownership; a
    queued retry keeps its token/fairness/affinity.  Workspace convergence uses
    the owner-keyed session provisioner, which restores a Kubernetes sandbox,
    refreshes a virtual binding, and is a no-op for ``none``.  It never creates
    a persistent agent pod.
    """
    from shared.run_queue import (
        LANE_STATELESS,
        STATE_LEASED,
        STATE_QUEUED,
        UNIT_KIND_SESSION_TURN,
    )

    if permission_request_id is None:
        logger.warning(
            "magic-link wake: refusing unfenced stateless wake for thread %s",
            thread_id,
        )
        return

    should_ensure_workspace = False
    async with postgres_db.acquire() as conn:
        async with conn.transaction():
            locked_thread = await conn.fetchrow(
                "SELECT id, execution_lane, agent_id, status, metadata "
                "FROM threads WHERE id = $1::uuid FOR UPDATE",
                thread_id,
            )
            if locked_thread is None:
                return
            thread = dict(locked_thread)
            if (
                thread.get("execution_lane") != LANE_STATELESS
                or thread.get("agent_id") is not None
            ):
                logger.warning(
                    "magic-link wake: stateless authority moved for thread %s "
                    "(lane=%r agent_id=%r)",
                    thread_id,
                    thread.get("execution_lane"),
                    thread.get("agent_id"),
                )
                return
            try:
                _require_stateless_workspace(thread)
            except HTTPException as exc:
                logger.warning(
                    "magic-link wake: refusing stateless workspace/class for "
                    "thread %s: %s",
                    thread_id,
                    exc.detail,
                )
                return

            # Keep the repository-wide threads -> run_queue lock order.  The
            # lock makes the pending-input test atomic with a concurrent claim,
            # completion, release or reaper steal.
            queue = await conn.fetchrow(
                "SELECT state, input_seq, consumed_seq "
                "FROM run_queue "
                "WHERE unit_id = $1::uuid AND unit_kind = $2 "
                "FOR UPDATE",
                thread_id,
                UNIT_KIND_SESSION_TURN,
            )
            if queue is None:
                logger.warning(
                    "magic-link wake: no session queue authority for thread %s",
                    thread_id,
                )
                return
            queue_state = str(queue["state"] or "")
            input_seq = queue["input_seq"]
            consumed_seq = queue["consumed_seq"]
            has_unconsumed_input = input_seq is not None and (
                consumed_seq is None or int(input_seq) > int(consumed_seq)
            )
            if (
                queue_state not in {STATE_QUEUED, STATE_LEASED}
                or not has_unconsumed_input
            ):
                logger.warning(
                    "magic-link wake: refusing stale stateless continuation for "
                    "thread %s (queue_state=%s input_seq=%r consumed_seq=%r)",
                    thread_id,
                    queue_state,
                    input_seq,
                    consumed_seq,
                )
                return

            decision = await conn.fetchval(
                "SELECT status FROM thread_permission_requests "
                "WHERE id = $2::uuid AND thread_id = $1::uuid "
                "  AND status IN ('approved', 'denied')",
                thread_id,
                permission_request_id,
            )
            if decision not in {"approved", "denied"}:
                logger.warning(
                    "magic-link wake: exact permission fence rejected thread %s "
                    "request %s",
                    thread_id,
                    permission_request_id,
                )
                return

            thread_status = str(thread.get("status") or "")
            if thread_status not in {"active", "awaiting_user", "suspended"}:
                logger.warning(
                    "magic-link wake: thread %s is not resumable (status=%r)",
                    thread_id,
                    thread_status,
                )
                return

            if thread_status in {"awaiting_user", "suspended"}:
                updated = await conn.fetchval(
                    "UPDATE threads "
                    "SET status = 'active', "
                    "    awaiting_user_since = NULL, "
                    "    extend_count = 0, "
                    "    control_admission_agent_id = NULL "
                    "WHERE id = $1::uuid "
                    "  AND execution_lane = $2 "
                    "  AND agent_id IS NULL "
                    "  AND status IN ('suspended', 'awaiting_user') "
                    "RETURNING id",
                    thread_id,
                    LANE_STATELESS,
                )
                if updated is None:
                    return
            should_ensure_workspace = True

    if not should_ensure_workspace:
        return
    # Queue/lifecycle admission commits before this potentially slow side
    # effect.  A claimant may arrive first, but its attach path polls the same
    # durable workspace lifecycle until it is ready.
    await ensure_session_workspace(
        thread_id,
        db=postgres_db,
        provisioner=container_provisioner,
        suspension=workspace_suspension_service,
    )
    logger.info(
        "magic-link wake: stateless permission continuation admitted for "
        "thread %s request %s",
        thread_id,
        permission_request_id,
    )


async def _phase5_wake_if_suspended(
    thread_id: str,
    *,
    permission_request_id: str | None = None,
) -> None:
    """Wake a suspended thread after a magic-link decision.

    Fire-and-forget — the HTTP response has already returned. Stateless
    sessions delegate to the queue-fenced, topology-neutral helper above.
    Pinned sessions preserve the historical resume pattern: restore from S3,
    then spawn the agent pod if the persistent provisioner is wired.
    """
    try:
        thread = await postgres_db.get_thread(thread_id)
        if not thread:
            return
        if thread.get("execution_lane") == "stateless":
            await _phase5_wake_stateless_if_suspended(
                thread_id,
                permission_request_id=permission_request_id,
            )
            return
        if not _thread_uses_pinned_execution(thread):
            logger.warning(
                "magic-link wake: refusing pinned wake for thread %s on "
                "execution lane %r",
                thread_id,
                thread.get("execution_lane"),
            )
            return
        wake_authority = thread_runtime_authority(thread)
        if wake_authority is None:
            return
        metadata = thread.get("metadata") or {}
        if isinstance(metadata, str):
            try:
                metadata = json.loads(metadata)
            except (json.JSONDecodeError, TypeError):
                metadata = {}
        recycle = (metadata.get("agent_pod") or {}).get("recycle") or {}
        if isinstance(recycle, dict) and recycle.get("phase") not in {
            None,
            "",
            "complete",
            "cancelled",
        }:
            if _persistent_thread_recycler is not None:
                await _persistent_thread_recycler.request_and_reconcile(
                    thread_id=thread_id,
                    reason="resume_during_recycle",
                    expected_build_sha=persistent_provisioner.expected_build_sha,
                    expected_project_id=(
                        str(thread.get("project_id"))
                        if thread.get("project_id")
                        else None
                    ),
                )
            return
        ws_ctx = metadata.get("workspace_container") or {}
        ws_status = ws_ctx.get("status")
        if ws_status == "suspended" and workspace_suspension_service.is_enabled:
            logger.info(
                "magic-link wake: restoring suspended workspace for thread %s",
                thread_id,
            )
            restored = await ensure_session_workspace(
                thread_id,
                db=postgres_db,
                provisioner=container_provisioner,
                suspension=workspace_suspension_service,
                expected_runtime_generation=wake_authority.generation,
            )
            if restored is None or restored.outcome is EnsureOutcome.FAILED:
                logger.warning(
                    "magic-link wake: workspace restore failed or lost authority "
                    "for thread %s",
                    thread_id,
                )
                return

        # Publish wake only to the exact post-suspension generation. A G2
        # restore delayed across another End/Resume cannot wake G3.
        async with postgres_db.acquire() as conn:
            woke = await conn.fetchval(
                "UPDATE threads "
                "SET status = 'active', "
                "    awaiting_user_since = NULL, "
                "    extend_count = 0, "
                "    control_admission_agent_id = NULL "
                "WHERE id = $1::uuid "
                "  AND execution_lane='pinned' "
                "  AND runtime_generation=$2::uuid "
                "  AND runtime_retirement_token IS NULL "
                "  AND status IN ('suspended', 'awaiting_user') "
                "RETURNING id",
                thread_id,
                wake_authority.generation,
            )
        if woke is None and not same_thread_runtime_authority(
            await postgres_db.get_thread(thread_id), wake_authority
        ):
            return

        # Agent pod may also have been deleted on suspension
        # (workspace_suspension.py:502-504). Re-provision if a persistent
        # provisioner is configured. fire-and-forget — the agent's boot
        # will restore the LangGraph checkpoint and re-enter permission_check
        # for the same tool_call_id, where the select-first guard picks up
        # the decision we just UPDATEd.
        current = await postgres_db.get_thread(thread_id)
        if not same_thread_runtime_authority(current, wake_authority):
            return
        if persistent_provisioner is not None and not current.get("agent_id"):
            config_name = canonical_config_name(
                thread.get("config_name", "session_base")
            )

            async def _create_after_magic_link() -> None:
                # This closure sits lexically inside the wake handler's
                # try/except, but it is scheduled as its own task — so that
                # handler NEVER sees anything raised here. Its own guard is the
                # only thing between a raise and a silently vanished wake.
                try:
                    result = await persistent_provisioner.create_agent_pod(
                        thread_id,
                        config_name=config_name,
                        expected_runtime_generation=wake_authority.generation,
                    )
                    if not result.usable:
                        logger.warning(
                            "magic-link persistent provisioning for thread %s "
                            "is %s (%s)",
                            thread_id,
                            result.status.value,
                            result.failure_class or "no-detail",
                        )
                        await _emit_session_provisioning_failure(
                            thread_id,
                            str(thread.get("user_id") or "") or None,
                            wake_authority,
                            f"magic-link wake provisioning {result.status.value}"
                            f" ({result.failure_class or 'no-detail'})",
                        )
                except Exception as exc:
                    logger.exception(
                        "magic-link persistent provisioning for thread %s raised: %s",
                        thread_id,
                        exc,
                    )
                    await _emit_session_provisioning_failure(
                        thread_id,
                        str(thread.get("user_id") or "") or None,
                        wake_authority,
                        str(exc),
                    )

            asyncio.create_task(
                _create_after_magic_link(),
                name=f"phase5-create-agent-{thread_id[:8]}",
            )
    except Exception as e:
        logger.warning(
            "magic-link wake task failed for thread %s: %s",
            thread_id,
            e,
        )


async def thread_permission_notify_sweeper(
    shutdown_event: asyncio.Event,
) -> None:
    """Background task: a permission request that has waited longer than
    HEADLESS_NOTIFY_AGE_S without a decision becomes a ``session_permission``
    feed row for the thread owner — ``high``, so the mail (with the two magic
    links) goes out now, and the row resolves when the gate is decided by any
    path. In-session gates are answered within seconds through the agent's
    LISTEN, so only abandoned ones ever get here.

    Runs every HEADLESS_NOTIFY_INTERVAL_S (default 30s). Idempotent: the
    feed row is keyed on the request id, and rows already recorded are
    filtered out so the magic-link tokens are minted once.

    Best-effort. Survives transient errors by logging and continuing.
    """
    interval_s = int(os.environ.get("HEADLESS_NOTIFY_INTERVAL_S", "30"))
    age_threshold_s = int(os.environ.get("HEADLESS_NOTIFY_AGE_S", "30"))
    logger.info(
        "Headless permission-notify sweeper started (interval=%ds, age_threshold=%ds)",
        interval_s,
        age_threshold_s,
    )
    cockpit_external_url = email_service.cockpit_url or "http://localhost:4200"

    while not shutdown_event.is_set():
        try:
            async with postgres_db.acquire() as conn:
                rows = await conn.fetch(
                    "SELECT r.id, r.thread_id, r.tool_name, r.tool_args, "
                    "       r.requested_at, t.user_id, t.title "
                    "FROM thread_permission_requests r "
                    "JOIN threads t ON t.id = r.thread_id "
                    "WHERE r.status = 'pending' "
                    "  AND r.requested_at < now() - ($1::int * interval '1 second') "
                    "  AND NOT EXISTS ("
                    "    SELECT 1 FROM notifications n "
                    "    WHERE n.source_kind = 'permission_request' "
                    "      AND n.source_id = r.id::text"
                    "  ) "
                    "ORDER BY r.requested_at ASC "
                    "LIMIT 50",
                    age_threshold_s,
                )
            for row in rows:
                try:
                    result = await headless_notifications.record_permission_pending(
                        postgres_db,
                        notification_service,
                        row=dict(row),
                        cockpit_external_url=cockpit_external_url,
                    )
                    if result.get("status") == "recorded":
                        logger.info(
                            "Recorded permission-pending notification "
                            "(thread=%s req=%s)",
                            str(row["thread_id"])[:8],
                            str(row["id"])[:8],
                        )
                except Exception as e:
                    logger.warning(
                        "Permission-pending notification failed (req=%s): %s",
                        str(row["id"])[:8],
                        e,
                    )
        except Exception as e:
            logger.warning("headless permission-notify sweep error: %s", e)
        try:
            await asyncio.wait_for(shutdown_event.wait(), timeout=float(interval_s))
            break
        except asyncio.TimeoutError:
            pass
    logger.info("Headless permission-notify sweeper stopped")


# =============================================================================
# Phase 5 — Attention sleep watchdog
# =============================================================================
#
# Suspends thread workspaces (and the bound agent pod) when the agent has
# been in `awaiting_user` for longer than HEADLESS_ATTENTION_SLEEP_MINUTES.
# State machine:
#   active ─→ awaiting_user (agent: natural pause + no WS subscriber)
#   awaiting_user ─→ suspended (this watchdog after TTL)
#   awaiting_user ─→ active (agent: subscriber reattach, clears timer)
#   suspended ─→ active (magic-link wake or REST reattach restores workspace)
#
# Magic-link "extend window" POSTs bump awaiting_user_since forward so the
# watchdog re-arms; threads.extend_count caps the bumps at 4 (4h total).
#
# Today's "tethered" signal is WS-only — Phase 5 v1 ships before the
# cockpit migrates from WS to SSE. SSE-only consumers (MCP, curl) do not
# block suspension; they should rely on magic-link wake to bring the
# session back. When cockpit moves to SSE, this watchdog will need to
# consult the orchestrator's in-process SSE attach registry too.


_ATTENTION_SLEEP_INTERVAL_S: int = int(
    os.environ.get("HEADLESS_ATTENTION_SLEEP_INTERVAL_S", "60")
)
_ATTENTION_SLEEP_MINUTES: int = int(
    os.environ.get("HEADLESS_ATTENTION_SLEEP_MINUTES", "60")
)


OFFICER_WATCHDOG_INTERVAL_S = int(os.getenv("OFFICER_WATCHDOG_INTERVAL_S", "60"))
OFFICER_WAKE_GRACE_MINUTES = int(os.getenv("OFFICER_WAKE_GRACE_MINUTES", "10"))


async def _maintain_officer_runtime_authorization(
    officer_row: dict[str, Any],
) -> Any:
    """Run the credential-independent Officer liveness check and page once."""

    project_id = officer_row.get("project_id")
    thread_id = officer_row.get("id")
    if not project_id or not thread_id:
        return None
    outcome = await maintain_current_officer_runtime(
        postgres_db,
        project_id=str(project_id),
        thread_id=str(thread_id),
        verification_enabled=OFFICER_RUNTIME_VERIFICATION_ENABLED,
    )
    if outcome.incident_changed and outcome.authorized:
        _kick_officer_event_drain(postgres_db)
    if (
        not outcome.notification_due
        or outcome.officer_incarnation is None
        or outcome.notification_claim_id is None
    ):
        return outcome
    delivered = False
    failure_class = "delivery"
    try:
        delivered = await _dispatch_officer_page(
            officer_row,
            str(thread_id),
            category="officer_runtime",
            dedup_key=f"officer_runtime_auth:{outcome.notification_claim_id}",
            subject="Officer authorization unavailable",
            message_md=(
                "The commissioned Officer cannot maintain its server-derived "
                "runtime authorization. Autonomous planning is paused to "
                "prevent unusable model spend; the server will retry with "
                "bounded backoff."
            ),
        )
        failure_class = "notifier_rejected" if not delivered else ""
    except Exception as exc:
        failure_class = type(exc).__name__[:128]
        logger.warning(
            "officer runtime authorization page failed for project %s",
            str(project_id)[:8],
        )
    await settle_officer_runtime_incident_notification(
        postgres_db,
        project_id=str(project_id),
        thread_id=str(thread_id),
        officer_incarnation=outcome.officer_incarnation,
        notification_claim_id=outcome.notification_claim_id,
        delivered=delivered,
        failure_class=failure_class or None,
    )
    return outcome


async def _officer_watchdog_check_one(officer_row: dict, session_wake_svc) -> None:
    """One officer thread's watchdog pass — see officer_watchdog below."""
    thread_id = str(officer_row["id"])
    # P0 runtime authority is maintained before hold/timer decisions. A held
    # Officer is still commissioned and may remain asleep for days; letting a
    # conference hold skip credential maintenance would simply move the 24 h
    # cliff to another lifecycle branch.
    await _maintain_officer_runtime_authorization(officer_row)
    officer_meta = _thread_officer_meta(officer_row)
    hold = officer_meta.get("hold")
    if hold:
        # Conference hold (centurion.md §4): stand down entirely — no
        # implicit-timer filing, no overdue kicks, no respawn. But first,
        # self-heal a STALE hold: if the conference thread is gone, ended, or
        # idle-suspended (Legate walked away; the attention sweeper parked
        # it), the meeting is over — a missed end-hook must not hold the
        # officer forever. Concluding here releases the hold and enqueues the
        # brief wake (idempotent with the end-hook via insert-dedup on the
        # conference thread id).
        conf_tid = hold.get("thread_id") if isinstance(hold, dict) else None
        if conf_tid:
            conf = await postgres_db.get_thread(str(conf_tid))
            if conf is None or conf.get("status") in ("ended", "suspended"):
                logger.warning(
                    "officer watchdog: stale conference hold on %s "
                    "(conference %s is %s) — concluding",
                    thread_id[:8],
                    str(conf_tid)[:8],
                    conf.get("status") if conf else "gone",
                )
                if conf is not None:
                    await _conclude_conference_if_any(conf)
                else:
                    project_id = officer_row.get("project_id")
                    if project_id:
                        await postgres_db.set_project_officer_hold(
                            str(project_id),
                            expected_thread_id=thread_id,
                            hold=None,
                        )
                return  # next tick resumes normal duties, unheld
        return
    try:
        sleep_max = int(officer_meta.get("sleep_max_minutes") or 60)
    except (TypeError, ValueError):
        sleep_max = 60

    thread = await postgres_db.get_thread(thread_id)
    if not _thread_uses_pinned_execution(thread) or thread.get("status") == "ended":
        return
    agent = await session_wake_svc._resolve_live_agent(postgres_db, thread)
    timer = await postgres_db.get_pending_officer_timer(thread_id)
    now = datetime.now(timezone.utc)

    if agent is not None and thread.get("status") == "active":
        if timer is None:
            # Duty 1: implicit sleep_max. The transport files explicit
            # sleeps; when a turn ended without one (or the filing POST was
            # lost), the watchdog files the default on the officer's behalf
            # (centurion.md §4 — "absent a filing, the system is lazy for
            # him too"). Gated on LAST ENGAGEMENT (any transcript row or the
            # last delivered timer) — ai/tool age alone re-files mid-turn,
            # since a turn's ai row only lands at turn end (k3d smoke).
            last = await postgres_db.get_officer_last_engagement(thread_id)
            if last is None or (now - last) > timedelta(minutes=sleep_max):
                await postgres_db.enqueue_session_wake_event(
                    thread_id,
                    source="timer",
                    dedup_key="timer",
                    payload={
                        "minutes": sleep_max,
                        "reason": "implicit sleep_max (watchdog-filed)",
                    },
                    fire_at=now,
                )
                session_wake_svc.kick_event_drain(postgres_db)
        else:
            fire_at = timer.get("fire_at")
            if fire_at is not None and (now - fire_at) > timedelta(
                minutes=OFFICER_WAKE_GRACE_MINUTES
            ):
                # Duty 2: overdue pending timer with a live pod = delivery
                # failure somewhere in the drain path. Kick it; the drain's
                # own release/retry handles a refusing pod.
                logger.warning(
                    "officer watchdog: timer overdue %.0fs for thread %s — "
                    "kicking drain",
                    (now - fire_at).total_seconds(),
                    thread_id[:8],
                )
                session_wake_svc.kick_event_drain(postgres_db)
        return

    # Duty 3: a missing pod is another observation for the same durable
    # lifecycle owner used by image drift and the supported operator action.
    # The watchdog no longer clears bindings or creates pods on its own.
    recycler = _persistent_thread_recycler
    if recycler is None or not persistent_provisioner.is_available:
        logger.warning(
            "officer watchdog: lifecycle owner unavailable for thread %s",
            thread_id[:8],
        )
        return
    if not PERSISTENT_AGENT_RECONCILIATION_ENABLED:
        logger.info(
            "officer watchdog: automatic persistent reconciliation disabled "
            "for thread %s",
            thread_id[:8],
        )
        return
    observation = await recycler.observe(thread_id)
    if observation is not None:
        # The session-wake probe is intentionally stricter than Kubernetes
        # liveness and can bounce during attach or a transient network fault.
        # A real pod observation is not "missing" authority. The registered
        # lifecycle manager owns build/UID/agent reciprocity decisions and
        # will submit an explicit drift/mismatch reason when appropriate.
        logger.info(
            "officer watchdog: live probe missed thread %s but pod UID %s "
            "still exists; deferring to persistent lifecycle reconciliation",
            thread_id[:8],
            observation.pod_uid[:8],
        )
        return
    await recycler.request_and_reconcile(
        thread_id=thread_id,
        reason="missing_pod",
        expected_build_sha=persistent_provisioner.expected_build_sha,
        observation=None,
        expected_project_id=str(officer_row.get("project_id") or ""),
    )


async def officer_watchdog(shutdown_event: asyncio.Event) -> None:
    """Dumb-code guardian of officer (centurion) sessions — centurion.md §4.

    Three duties, none requiring judgment: file the implicit ``sleep_max``
    timer when an unheld officer has none pending; treat a pending timer
    overdue past ``fire_at + grace`` with a live pod as a delivery failure
    and kick the drain; submit missing runtimes to the shared durable lifecycle
    owner. Leader-gated; the recycler also carries a durable generation/claim.
    """
    from orchestrator.services import session_wake as session_wake_svc

    logger.info(
        "Officer watchdog started (tick=%ds, grace=%dm)",
        OFFICER_WATCHDOG_INTERVAL_S,
        OFFICER_WAKE_GRACE_MINUTES,
    )
    while not shutdown_event.is_set():
        try:
            for officer_row in await postgres_db.list_officer_threads():
                try:
                    await _officer_watchdog_check_one(officer_row, session_wake_svc)
                except Exception:
                    logger.exception(
                        "officer watchdog: check failed for thread %s "
                        "(continuing with the rest)",
                        str(officer_row.get("id"))[:8],
                    )
        except Exception:
            logger.exception("officer watchdog tick raised; will retry next tick")
        try:
            await asyncio.wait_for(
                shutdown_event.wait(), timeout=OFFICER_WATCHDOG_INTERVAL_S
            )
            break
        except asyncio.TimeoutError:
            pass
    logger.info("Officer watchdog stopped")


async def attention_sleep_sweeper(shutdown_event: asyncio.Event) -> None:
    """Background task: suspend threads stuck in awaiting_user past their TTL.

    Runs every HEADLESS_ATTENTION_SLEEP_INTERVAL_S (default 60s). Each
    qualifying pinned generation enters the same durable retirement funnel as
    owner End, settling to ``suspended`` only after generation-fenced staging
    and exact resource cleanup. Resume stays closed for the entire operation.

    Best-effort: a transient failure (DB unavailable, suspend service
    error) is logged and retried on the next tick.
    """
    interval_s = _ATTENTION_SLEEP_INTERVAL_S
    ttl_minutes = _ATTENTION_SLEEP_MINUTES
    logger.info(
        "Attention-sleep sweeper started (interval=%ds, ttl=%dmin)",
        interval_s,
        ttl_minutes,
    )

    while not shutdown_event.is_set():
        try:
            # A disconnect intentionally leaves a short TTL grace so reloads
            # and multi-tab handoffs never flicker. If a turn reached its
            # natural pause inside that grace, converge it once the queue is
            # durably done and the final client TTL has expired. This is
            # independent of workspace suspension being enabled.
            try:
                promoted = await promote_expired_stateless_pauses(postgres_db, limit=50)
                if promoted:
                    logger.info(
                        "presence expiry promoted %d stateless thread(s) "
                        "to awaiting_user",
                        len(promoted),
                    )
            except Exception as exc:
                # Presence convergence is additive. It must never suppress the
                # pre-existing awaiting_user suspension sweep on the same tick.
                logger.warning("presence expiry promotion failed: %s", exc)
            if workspace_suspension_service.is_enabled:
                async with postgres_db.acquire() as conn:
                    # Phase 6: per-thread TTL resolution. Priority order is
                    # (1) thread.metadata.config_override.headless overrides,
                    # (2) users.settings.persistent_agent overrides,
                    # (3) the global HEADLESS_ATTENTION_SLEEP_MINUTES default.
                    # ttl <= 0 disables the watchdog for that thread, matching
                    # the cockpit UX of "Never auto-suspend".
                    rows = await conn.fetch(
                        "SELECT t.id, t.status, t.execution_lane, "
                        "       t.runtime_generation, t.agent_id, "
                        "       t.runtime_attach_token "
                        "FROM threads t "
                        "LEFT JOIN users u ON u.id = t.user_id "
                        "WHERE t.status = 'awaiting_user' "
                        "  AND t.execution_lane <> 'stateless' "
                        "  AND t.awaiting_user_since IS NOT NULL "
                        # Officer sessions never sleep via attention-sleep —
                        # their lifecycle belongs to the officer watchdog
                        # (centurion.md §4). Belt-and-suspenders: the agent
                        # side already skips the awaiting_user flip for them.
                        "  AND COALESCE(t.metadata->'config_override'->'officer'"
                        "->>'enabled','false') <> 'true' "
                        "  AND COALESCE("
                        "    NULLIF(t.metadata->'config_override'->'headless'->>'attention_sleep_minutes', '')::int, "
                        "    NULLIF(u.settings->'persistent_agent'->>'headless_attention_sleep_minutes', '')::int, "
                        "    $1::int"
                        "  ) > 0 "
                        "  AND t.awaiting_user_since < now() - make_interval(mins => COALESCE("
                        "    NULLIF(t.metadata->'config_override'->'headless'->>'attention_sleep_minutes', '')::int, "
                        "    NULLIF(u.settings->'persistent_agent'->>'headless_attention_sleep_minutes', '')::int, "
                        "    $1::int"
                        "  )) "
                        "ORDER BY t.awaiting_user_since ASC "
                        "LIMIT 50",
                        int(ttl_minutes),
                    )

                for row in rows:
                    thread_id = str(row["id"])
                    try:
                        result = await _end_thread_flow(
                            thread_id,
                            dict(row),
                            permanent=False,
                            force=False,
                            expected_runtime_generation=str(row["runtime_generation"]),
                            expected_agent_id=(
                                str(row["agent_id"])
                                if row["agent_id"] is not None
                                else None
                            ),
                            expected_attach_token=(
                                str(row["runtime_attach_token"])
                                if row["runtime_attach_token"] is not None
                                else None
                            ),
                            settle_status="suspended",
                        )
                        if result.get("status") == "suspended":
                            logger.info(
                                "attention-sleep: thread %s suspended (was "
                                "awaiting_user >%dm)",
                                thread_id,
                                ttl_minutes,
                            )
                        else:
                            logger.info(
                                "attention-sleep: exact retirement declined "
                                "for thread %s (%s)",
                                thread_id,
                                result.get("status"),
                            )
                    except Exception as e:
                        logger.warning(
                            "attention-sleep: suspend failed for thread %s: %s",
                            thread_id,
                            e,
                        )
        except Exception as e:
            logger.warning("attention-sleep sweep error: %s", e)

        try:
            await asyncio.wait_for(shutdown_event.wait(), timeout=float(interval_s))
            break
        except asyncio.TimeoutError:
            pass

    logger.info("Attention-sleep sweeper stopped")


